window.PAGES = window.PAGES || {};
window.PAGES["practice-days1-6"] = {"title": "OCI Foundations \u2014 Day 1\u20136 Visualizer", "css": "\n:host{\n  --ink:#131c27; --ink-soft:#4a5768;\n  --paper:#f2f4f5; --panel:#ffffff; --line:#dde1e4;\n  --amber:#b9822f; --amber-soft:#f4e6cd; --amber-glow:rgba(185,130,47,.35);\n  --slate:#3468a0; --slate-soft:#dfeaf5; --slate-glow:rgba(52,104,160,.30);\n  --violet:#6d54a8; --violet-soft:#e9e3f6;\n  --green:#2f8a54; --green-soft:#dcf1e3; --green-glow:rgba(47,138,84,.35);\n  --rust:#b8452f; --rust-soft:#f6ddd6; --rust-glow:rgba(184,69,47,.35);\n  --gray:#8b93a0; --gray-soft:#e9eaec;\n  --radius:8px;\n  --shadow:0 1px 2px rgba(19,28,39,.06), 0 2px 18px rgba(19,28,39,.05);\n}\n[data-theme=\"dark\"]{\n  --ink:#eef1f4; --ink-soft:#a9b3c0;\n  --paper:#0c1219; --panel:#131b25; --line:#26313d;\n  --amber:#e0aa5e; --amber-soft:#2a2113; --amber-glow:rgba(224,170,94,.28);\n  --slate:#7bb0dd; --slate-soft:#152230; --slate-glow:rgba(123,176,221,.25);\n  --violet:#a893db; --violet-soft:#221c33;\n  --green:#6fc493; --green-soft:#112a1c; --green-glow:rgba(111,196,147,.28);\n  --rust:#e2846f; --rust-soft:#2c1712; --rust-glow:rgba(226,132,111,.25);\n  --gray:#7c8695; --gray-soft:#1a222c;\n  --shadow:0 1px 2px rgba(0,0,0,.35), 0 2px 22px rgba(0,0,0,.3);\n}\n*{box-sizing:border-box;}\n:host{margin:0;padding:0;}\n:host{\n  background:\n    radial-gradient(900px 500px at 100% -10%, var(--slate-glow), transparent 60%),\n    radial-gradient(700px 420px at -10% 0%, var(--amber-glow), transparent 55%),\n    var(--paper);\n  color:var(--ink);\n  font-family:'Inter',system-ui,sans-serif;\n  font-size:14.5px; line-height:1.55;\n  transition:background .25s ease,color .25s ease;\n}\nh1,h2,h3,h4{font-family:'Space Grotesk',sans-serif; margin:0 0 8px; letter-spacing:-.01em;}\n.mono{font-family:'IBM Plex Mono',monospace;}\n::selection{background:var(--amber-soft);}\nbutton{font-family:inherit; cursor:pointer;}\na{color:var(--slate);}\n@keyframes fadeUp{from{opacity:0; transform:translateY(6px);} to{opacity:1; transform:translateY(0);}}\n@keyframes popIn{0%{transform:scale(.85); opacity:0;} 100%{transform:scale(1); opacity:1;}}\n@keyframes pulseGlow{0%,100%{box-shadow:0 0 0 0 var(--amber-glow);} 50%{box-shadow:0 0 0 6px transparent;}}\n@keyframes slideIn{from{transform:translateX(120%); opacity:0;} to{transform:translateX(0); opacity:1;}}\n@keyframes confetti{0%{transform:translateY(0) rotate(0); opacity:1;} 100%{transform:translateY(60px) rotate(240deg); opacity:0;}}\n@keyframes shake{0%,100%{transform:translateX(0);} 25%{transform:translateX(-5px);} 75%{transform:translateX(5px);}}\n\n/* ---------- SHELL ---------- */\n#app{display:flex; min-height:100%;}\n#sidebar{\n  width:292px; min-width:292px; background:var(--panel); border-right:1px solid var(--line);\n  padding:18px 14px 24px; position:sticky; top:0; height:100%; overflow-y:auto;\n}\n#main{flex:1; min-width:0; padding:22px 34px 70px; position:relative;}\n@media (max-width:900px){\n  #app{flex-direction:column;}\n  #sidebar{width:100%; min-width:0; height:auto; position:relative; border-right:none; border-bottom:1px solid var(--line);}\n  #main{padding:16px;}\n}\n\n.brand{display:flex; align-items:center; gap:10px; padding:4px 6px 16px; border-bottom:1px solid var(--line); margin-bottom:14px;}\n.brand .mark{\n  width:36px; height:36px; border-radius:9px; background:linear-gradient(155deg,var(--amber),var(--violet) 60%,var(--slate));\n  display:flex; align-items:center; justify-content:center; color:#fff; font-family:'Space Grotesk'; font-weight:700; font-size:12.5px;\n  flex-shrink:0; box-shadow:0 3px 10px var(--amber-glow);\n}\n.brand .name{font-family:'Space Grotesk'; font-weight:600; font-size:15px; line-height:1.2;}\n.brand .sub{font-size:11px; color:var(--ink-soft); margin-top:1px;}\n.theme-toggle{\n  margin-left:auto; width:30px; height:30px; border-radius:8px; border:1px solid var(--line); background:var(--paper);\n  display:flex; align-items:center; justify-content:center; color:var(--ink-soft); font-size:14px;\n}\n\n/* gamification hud */\n.hud{margin:14px 6px; padding:13px; border-radius:10px; border:1px solid var(--line); background:linear-gradient(160deg, var(--panel), var(--paper)); position:relative; overflow:hidden;}\n.hud-top{display:flex; align-items:center; gap:10px; margin-bottom:10px;}\n.level-badge{\n  width:38px; height:38px; border-radius:50%; background:conic-gradient(var(--amber) calc(var(--xppct)*1%), var(--gray-soft) 0);\n  display:flex; align-items:center; justify-content:center; flex-shrink:0; position:relative;\n}\n.level-badge::after{content:\"\"; position:absolute; inset:4px; border-radius:50%; background:var(--panel);}\n.level-badge span{position:relative; z-index:1; font-family:'Space Grotesk'; font-weight:700; font-size:12px;}\n.hud-title{font-family:'Space Grotesk'; font-weight:700; font-size:13.5px;}\n.hud-sub{font-size:10.5px; color:var(--ink-soft); font-family:'IBM Plex Mono';}\n.xpbar{height:6px; border-radius:4px; background:var(--gray-soft); overflow:hidden; margin:8px 0;}\n.xpbar>div{height:100%; background:linear-gradient(90deg,var(--amber),var(--violet)); transition:width .4s ease;}\n.hud-row{display:flex; justify-content:space-between; align-items:center; font-size:11.5px; color:var(--ink-soft);}\n.streak{display:flex; align-items:center; gap:5px; font-family:'IBM Plex Mono'; font-weight:600; color:var(--ink);}\n.streak.hot{color:var(--rust); animation:pulseGlow 1.4s infinite;}\n\n.ring-wrap{display:flex; align-items:center; gap:12px; margin:10px 6px 4px;}\n.ring{\n  width:58px; height:58px; border-radius:50%; flex-shrink:0; position:relative;\n  background:conic-gradient(var(--green) calc(var(--pct)*1%), var(--gray-soft) 0);\n}\n.ring::after{content:\"\"; position:absolute; inset:7px; border-radius:50%; background:var(--panel);}\n.ring b{position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-family:'Space Grotesk'; font-size:13px; z-index:1;}\n.ring-legend{font-size:11.5px; color:var(--ink-soft); line-height:1.6;}\n.ring-legend b{color:var(--ink);}\n\n.badges-row{display:flex; flex-wrap:wrap; gap:6px; margin:10px 6px;}\n.badge-chip{\n  width:30px; height:30px; border-radius:8px; display:flex; align-items:center; justify-content:center; font-size:15px;\n  background:var(--gray-soft); border:1px solid var(--line); opacity:.3; filter:grayscale(1);\n}\n.badge-chip.unlocked{opacity:1; filter:none; background:var(--amber-soft); border-color:var(--amber); box-shadow:0 0 0 2px var(--amber-glow);}\n\n.nav-label{font-size:10.5px; text-transform:uppercase; letter-spacing:.08em; color:var(--ink-soft); font-weight:600; margin:16px 6px 8px;}\n.nav-btn{\n  width:100%; text-align:left; background:none; border:none; padding:9px 10px; border-radius:7px; font-size:13.5px;\n  color:var(--ink); display:flex; align-items:center; gap:9px; font-weight:500; transition:background .12s;\n}\n.nav-btn:hover{background:var(--gray-soft);}\n.nav-btn.active{background:linear-gradient(90deg,var(--amber-soft),transparent); color:var(--amber); font-weight:700; box-shadow:inset 2px 0 0 var(--amber);}\n.nav-btn .ic{width:16px; text-align:center; font-size:13px; opacity:.9;}\n\n.qnav{display:grid; grid-template-columns:repeat(5,1fr); gap:6px; margin:8px 6px;}\n.qdot{\n  aspect-ratio:1; border-radius:7px; border:1px solid var(--line); background:var(--paper);\n  display:flex; align-items:center; justify-content:center; font-family:'IBM Plex Mono'; font-size:11px; color:var(--ink-soft);\n  transition:transform .1s;\n}\n.qdot:hover{border-color:var(--slate); transform:scale(1.06);}\n.qdot.current{outline:2px solid var(--slate); outline-offset:1px;}\n.qdot.know{background:var(--green-soft); color:var(--green); border-color:var(--green);}\n.qdot.review{background:var(--rust-soft); color:var(--rust); border-color:var(--rust);}\n\n/* ---------- TOPBAR ---------- */\n.topbar{display:flex; align-items:center; justify-content:space-between; gap:16px; margin-bottom:20px; flex-wrap:wrap;}\n.topbar h2{font-size:20px; display:flex; align-items:center; gap:8px;}\n.topbar .desc{color:var(--ink-soft); font-size:13px; margin-top:2px;}\n.search-wrap{display:flex; gap:8px; align-items:center; flex-wrap:wrap;}\n.search-input{border:1px solid var(--line); background:var(--panel); border-radius:8px; padding:8px 12px; font-size:13px; color:var(--ink); width:210px;}\n.filter-chip{border:1px solid var(--line); background:var(--panel); border-radius:20px; padding:6px 12px; font-size:12px; color:var(--ink-soft);}\n.filter-chip.on{background:var(--slate-soft); border-color:var(--slate); color:var(--slate); font-weight:700;}\n\n/* ---------- CARD ---------- */\n.card{background:var(--panel); border:1px solid var(--line); border-radius:12px; padding:24px 26px; box-shadow:var(--shadow); margin-bottom:16px; animation:fadeUp .28s ease;}\n.eyebrow{font-family:'IBM Plex Mono'; font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--slate); margin-bottom:10px; display:flex; gap:8px; align-items:center; flex-wrap:wrap;}\n.pill{display:inline-block; font-size:10.5px; padding:3px 9px; border-radius:20px; background:var(--gray-soft); color:var(--ink-soft); font-family:'IBM Plex Mono'; letter-spacing:.03em;}\n.pill.day1{background:var(--slate-soft); color:var(--slate);}\n.pill.day2{background:var(--amber-soft); color:var(--amber);}\n.pill.day3{background:var(--violet-soft); color:var(--violet);}\n.pill.day4{background:var(--green-soft); color:var(--green);}\n.pill.day5{background:var(--rust-soft); color:var(--rust);}\n.pill.day6{background:var(--gray-soft); color:var(--ink-soft);}\n.pill.xp{background:var(--violet-soft); color:var(--violet);}\n\n.q-text{font-size:18px; font-weight:600; line-height:1.5; margin-bottom:16px; font-family:'Space Grotesk';}\n\n/* MCQ */\n.mcq-list{display:flex; flex-direction:column; gap:9px; margin:14px 0 6px;}\n.mcq-opt{\n  border:1.5px solid var(--line); background:var(--paper); border-radius:9px; padding:12px 14px; font-size:13.5px; text-align:left;\n  display:flex; align-items:center; gap:11px; transition:border-color .12s, background .12s, transform .08s;\n}\n.mcq-opt:hover:not(.locked){border-color:var(--slate); transform:translateX(2px);}\n.mcq-opt.selected{border-color:var(--slate); background:var(--slate-soft); font-weight:600;}\n.mcq-opt .optkey{\n  width:24px; height:24px; border-radius:7px; background:var(--gray-soft); color:var(--ink-soft); font-family:'IBM Plex Mono'; font-weight:700;\n  font-size:12px; display:flex; align-items:center; justify-content:center; flex-shrink:0;\n}\n.mcq-opt.selected .optkey{background:var(--slate); color:#fff;}\n.mcq-opt.correct-reveal{border-color:var(--green); background:var(--green-soft); font-weight:600;}\n.mcq-opt.correct-reveal .optkey{background:var(--green); color:#fff;}\n.mcq-opt.wrong-reveal{border-color:var(--rust); background:var(--rust-soft); animation:shake .35s;}\n.mcq-opt.wrong-reveal .optkey{background:var(--rust); color:#fff;}\n.mcq-opt.dim{opacity:.55;}\n\n.result-banner{\n  border-radius:10px; padding:14px 16px; margin:14px 0; font-weight:700; font-size:14px; display:flex; align-items:center; gap:10px;\n  animation:popIn .25s ease;\n}\n.result-banner.correct{background:var(--green-soft); color:var(--green); box-shadow:0 0 0 1px var(--green);}\n.result-banner.incorrect{background:var(--rust-soft); color:var(--rust); box-shadow:0 0 0 1px var(--rust);}\n.result-banner .xpgain{margin-left:auto; font-family:'IBM Plex Mono'; font-size:12px; background:rgba(255,255,255,.35); padding:3px 9px; border-radius:20px;}\n\n.btn{border:1px solid var(--line); background:var(--panel); color:var(--ink); padding:10px 18px; border-radius:8px; font-size:13px; font-weight:700; display:inline-flex; align-items:center; gap:7px; transition:transform .08s, box-shadow .15s;}\n.btn:hover:not(:disabled){transform:translateY(-1px); box-shadow:0 3px 10px rgba(0,0,0,.08);}\n.btn.primary{background:linear-gradient(120deg,var(--ink),#000 130%); color:var(--paper); border-color:var(--ink);}\n[data-theme=\"dark\"] .btn.primary{background:linear-gradient(120deg,var(--amber),#c88a3f); color:#1a1204; border-color:var(--amber);}\n.btn.ghost{background:none;}\n.btn.know{background:var(--green-soft); border-color:var(--green); color:var(--green);}\n.btn.review{background:var(--rust-soft); border-color:var(--rust); color:var(--rust);}\n.btn:disabled{opacity:.4; cursor:not-allowed; transform:none;}\n.btnrow{display:flex; gap:10px; flex-wrap:wrap; margin-top:10px; align-items:center;}\n\n.section{border-top:1px solid var(--line); margin-top:18px; padding-top:16px;}\n.section-head{display:flex; align-items:center; gap:8px; cursor:pointer; user-select:none;}\n.section-head h4{font-size:13.5px; text-transform:uppercase; letter-spacing:.04em; color:var(--ink-soft); flex:1; display:flex; align-items:center; gap:7px;}\n.section-head .chev{font-size:11px; color:var(--gray); transition:transform .15s;}\n.section.collapsed .section-head .chev{transform:rotate(-90deg);}\n.section.collapsed .section-body{display:none;}\n.section-body{margin-top:10px; animation:fadeUp .2s ease;}\n\n.theory-grid{display:grid; grid-template-columns:1fr 1fr; gap:12px;}\n@media(max-width:640px){.theory-grid{grid-template-columns:1fr;}}\n.theory-box{background:var(--paper); border:1px solid var(--line); border-radius:9px; padding:13px 15px; transition:border-color .15s;}\n.theory-box:hover{border-color:var(--slate);}\n.theory-box .lbl{font-size:11px; text-transform:uppercase; letter-spacing:.05em; color:var(--slate); font-weight:700; margin-bottom:5px; display:flex; gap:6px; align-items:center;}\n\n.callout{border-radius:9px; padding:13px 16px; border:1px solid var(--line); background:var(--paper); margin-top:10px;}\n.callout.quick{border-left:3px solid var(--slate); background:var(--slate-soft);}\n.callout.remember{border-left:3px solid var(--amber); background:var(--amber-soft);}\n.callout.trap{border-left:3px solid var(--rust); background:var(--rust-soft);}\n.callout.real{border-left:3px solid var(--violet); background:var(--violet-soft);}\n.callout.correct-box{border-left:3px solid var(--green); background:var(--green-soft);}\n.callout .lbl{font-weight:700; font-size:12.5px; margin-bottom:5px; display:flex; align-items:center; gap:6px;}\n.remember-line{font-family:'IBM Plex Mono'; font-size:13px; margin:3px 0;}\n\n/* diagram */\n.diagram{display:flex; flex-direction:column; align-items:center; gap:0; padding:16px 6px;}\n.dbox{\n  border:1px solid var(--slate); background:var(--slate-soft); color:var(--ink); font-family:'IBM Plex Mono'; font-size:12.5px;\n  padding:10px 18px; border-radius:8px; text-align:center; min-width:170px; max-width:360px; font-weight:600;\n  box-shadow:0 2px 8px rgba(0,0,0,.04); position:relative;\n}\n.dbox::before{content:attr(data-n); position:absolute; left:-9px; top:-9px; width:20px; height:20px; border-radius:50%; background:var(--slate); color:#fff; font-size:10px; display:flex; align-items:center; justify-content:center; font-weight:700;}\n.dbox.alt{border-color:var(--amber); background:var(--amber-soft);}\n.dbox.alt::before{background:var(--amber);}\n.darrow{color:var(--gray); font-size:16px; margin:3px 0;}\n.dtree{display:flex; flex-direction:column; align-items:center;}\n.dtree .children{display:flex; gap:22px; margin-top:10px; flex-wrap:wrap; justify-content:center;}\n.dtree .child{display:flex; flex-direction:column; align-items:center;}\n.dcompare{display:flex; gap:28px; justify-content:center; flex-wrap:wrap; width:100%;}\n.dtrack{display:flex; flex-direction:column; align-items:center;}\n.dtrack .title{font-family:'IBM Plex Mono'; font-weight:700; font-size:12px; color:var(--ink-soft); margin-bottom:8px; text-transform:uppercase; letter-spacing:.04em;}\n.dlayers{display:flex; flex-direction:column; align-items:stretch; gap:0; width:100%; max-width:440px;}\n.dlayer{border:1px solid var(--line); border-radius:8px; padding:11px 15px; margin-bottom:8px; font-family:'IBM Plex Mono'; font-size:12.5px; background:var(--paper); border-left:3px solid var(--violet);}\n.dlayer b{display:block; font-size:11px; color:var(--violet); text-transform:uppercase; letter-spacing:.04em; margin-bottom:2px;}\n\n.explain-simple{background:var(--paper); border:1px dashed var(--line); border-radius:9px; padding:13px 15px; margin-top:10px; font-size:13.5px;}\n.explain-simple .lbl{font-weight:700; color:var(--slate); font-size:11.5px; text-transform:uppercase; margin-bottom:4px;}\n\n/* revision */\n.rev-card{background:var(--panel); border:1px solid var(--line); border-radius:10px; padding:16px 18px; margin-bottom:12px; transition:box-shadow .15s;}\n.rev-card:hover{box-shadow:var(--shadow);}\n.rev-flow{font-family:'IBM Plex Mono'; font-size:12.5px; color:var(--ink-soft); margin:8px 0; line-height:1.9;}\n.rev-flow b{color:var(--ink);}\n\n/* exam */\n.exam-progress{font-family:'IBM Plex Mono'; font-size:12px; color:var(--ink-soft); margin-bottom:10px; display:flex; justify-content:space-between;}\n.exam-bar{height:5px; border-radius:4px; background:var(--gray-soft); overflow:hidden; margin-bottom:14px;}\n.exam-bar>div{height:100%; background:linear-gradient(90deg,var(--slate),var(--violet));}\n.result-grid{display:grid; grid-template-columns:1fr 1fr 1fr; gap:12px; margin:16px 0;}\n@media(max-width:640px){.result-grid{grid-template-columns:1fr;}}\n.result-box{border:1px solid var(--line); border-radius:10px; padding:16px; text-align:center; background:var(--paper);}\n.result-box .num{font-family:'Space Grotesk'; font-size:28px; font-weight:700;}\n.result-box .lbl{font-size:11.5px; color:var(--ink-soft); text-transform:uppercase; letter-spacing:.04em; margin-top:2px;}\n.topic-row{display:flex; justify-content:space-between; align-items:center; padding:9px 0; border-bottom:1px solid var(--line); font-size:13px;}\n.topic-row:last-child{border-bottom:none;}\n.tbar{width:120px; height:6px; border-radius:4px; background:var(--gray-soft); overflow:hidden;}\n.tbar>div{height:100%; background:linear-gradient(90deg,var(--green),var(--slate));}\n\n.empty{text-align:center; padding:60px 20px; color:var(--ink-soft);}\n.empty .big{font-size:34px; margin-bottom:10px;}\n\n/* toast */\n#toast-host{position:fixed; top:20px; right:20px; z-index:999; display:flex; flex-direction:column; gap:10px;}\n.toast{\n  background:var(--panel); border:1px solid var(--amber); border-radius:10px; padding:13px 18px; box-shadow:var(--shadow);\n  display:flex; align-items:center; gap:12px; min-width:240px; animation:slideIn .3s ease;\n}\n.toast .ic{font-size:24px;}\n.toast .t1{font-weight:700; font-size:13.5px;}\n.toast .t2{font-size:11.5px; color:var(--ink-soft);}\n\n/* confetti */\n.confetti-wrap{position:relative; height:0;}\n.confetti-piece{position:absolute; width:6px; height:6px; border-radius:1px; animation:confetti .8s ease forwards;}\n\n", "html": "\n<div id=\"app\">\n  <aside id=\"sidebar\"></aside>\n  <main id=\"main\"></main>\n</div>\n<div id=\"toast-host\"></div>\n\n\n", "js": "\n/* ============================= DATA ============================= */\nconst DATA = [\n{\n  id:1, day:1, topic:\"IAM Policy\",\n  question:\"A project team needs read access to Object Storage in only its Finance compartment. The architect wants to express the grant using OCI policy grammar and also needs to know what happens when an employee belongs to several groups with different grants. What policy structure should be used, and how are the resulting permissions combined?\",\n  answer:\"Every OCI policy statement follows the fixed grammar: Allow <group> to <verb> <resource-type> in compartment <compartment-name>. The four components, in order, are: (1) the Group the policy applies to, (2) the Verb / permission level (inspect, read, use, manage), (3) the Resource-type being accessed, and (4) the Location (compartment or tenancy) where it applies. When a user belongs to several groups, OCI evaluates ALL applicable policies together and grants the union of every permission \u2014 access is additive, not restrictive, and there is no explicit 'deny' statement in OCI policy language.\",\n  explanation:\"OCI's policy language is deliberately simple and reads almost like English: Allow group <G> to <verb> <resource-type> in compartment <C>. Because there is no 'deny' construct, the system is purely additive \u2014 if any policy statement, through any group membership, grants a permission, the user has it.\",\n  theory:{ what:\"An IAM policy is a written statement that grants a group of users a defined level of access to a defined set of resources in a defined location.\", why:\"Policies are how OCI enforces least-privilege access control \u2014 without one, no group has any access to any resource, by default.\", how:\"OCI parses the statement into WHO (group), WHAT (verb), WHICH (resource-type), and WHERE (compartment). At evaluation time, OCI collects every policy statement that matches the user through any group memberships and merges them into one effective permission set.\", example:\"A user is in both 'NetworkAdmins' (manage virtual-network-family in Prod) and 'Auditors' (inspect all-resources in Prod). The user effectively gets manage on networking AND inspect on everything else in Prod.\" },\n  quick:\"An IAM policy statement always reads: Allow GROUP to VERB RESOURCE-TYPE in compartment COMPARTMENT \u2014 and multiple group grants are always additive (union), never restrictive.\",\n  remember:[\"WHO \u2192 WHAT \u2192 WHICH \u2192 WHERE\",\"Multiple groups = MORE access, never less\"],\n  trap:\"Students often assume OCI policies can 'deny' access like explicit-deny statements elsewhere. OCI has no deny statement \u2014 if a user is in ANY group with a matching Allow, they have that access.\",\n  wrongOptionsNote:\"Common wrong answers swap the order (compartment first) or claim the most restrictive policy wins \u2014 OCI always takes the most permissive combined result.\",\n  diagram:{type:\"linear\", steps:[\"WHO \u2014 Group\",\"WHAT \u2014 Verb (inspect / read / use / manage)\",\"WHICH \u2014 Resource-Type\",\"WHERE \u2014 Compartment\"]},\n  examAnswer:\"Policy grammar: Allow <group> to <verb> <resource-type> in compartment <compartment>. With multiple group memberships, OCI grants the union of all permissions \u2014 access is cumulative, no explicit deny.\",\n  realWorld:\"Think of an office keycard system: a policy is like a rule that says 'Marketing badges open Floor 3 meeting rooms.' If you carry badges from two departments, you can use whichever badge lets you through \u2014 more badges always mean more access, never less.\",\n  mcq:{ question:\"When a user belongs to multiple OCI groups, how does OCI determine their effective permissions?\", options:[\"Only the most restrictive policy applies\",\"The permissions are combined \u2014 the user gets the union of all group permissions\",\"Only the last-created policy is evaluated\",\"OCI requires an explicit deny statement to block conflicting access\"], correctIndex:1 }\n},\n{\n  id:2, day:1, topic:\"Compartments\",\n  question:\"A startup has one compartment containing development, test, and production resources. As the environment grows, different teams need separate administration and cost visibility. Propose a compartment hierarchy that provides isolation without creating unnecessary administrative complexity.\",\n  answer:\"Replace the single flat compartment with a dedicated compartment per environment \u2014 Production, Development, and Testing \u2014 nested under the tenancy. Each compartment gets its own IAM policies, budgets, and tags, so access, cost, and change control are scoped per environment instead of shared.\",\n  explanation:\"Compartments are OCI's primary logical boundary for organizing resources. Splitting Dev/Test/Prod into separate compartments means a policy mistake in Development can never accidentally expose Production, and cost/quota reporting becomes environment-specific.\",\n  theory:{ what:\"A compartment is a logical, tenancy-wide container used to organize and isolate OCI resources for security, billing, and administrative purposes.\", why:\"It lets an organization apply different access policies, budgets, and quotas to different parts of the business without needing separate tenancies.\", how:\"Compartments form a hierarchy under the root (tenancy) compartment. IAM policies are written to grant access scoped to one compartment (and optionally its sub-compartments).\", example:\"Create Production, Development and Testing compartments. A policy grants 'DevTeam' manage access only in Development \u2014 they cannot touch Production even by mistake.\" },\n  quick:\"Isolate environments with one compartment per environment (Prod / Dev / Test) so access, cost, and governance can be scoped independently.\",\n  remember:[\"Compartment = Isolation boundary\",\"1 Compartment \u2248 1 Environment or Business Unit\"],\n  trap:\"Students confuse compartments with regions or VCNs. A compartment is a logical/administrative boundary \u2014 it has no geography and no networking behavior of its own.\",\n  wrongOptionsNote:\"A wrong recommendation would be to use tags alone instead of separate compartments \u2014 tags help with cost reporting but cannot scope IAM policy access the way compartments do.\",\n  diagram:{type:\"tree\", root:\"Tenancy (Root Compartment)\", children:[\"Production\",\"Development\",\"Testing\"]},\n  examAnswer:\"Create separate compartments for Production, Development and Testing under the tenancy, each with its own IAM policies, budgets and tags, so access and cost are isolated per environment.\",\n  realWorld:\"Like separate wings in a hospital \u2014 Cardiology, Pediatrics, Radiology \u2014 each with its own staff badges and its own budget, so a mistake in Radiology can't touch the Pediatrics ward.\",\n  mcq:{ question:\"What is the recommended way to isolate Dev, Test and Prod resources in OCI?\", options:[\"Use tags only and keep everything in one compartment\",\"Create separate compartments per environment\",\"Use separate tenancies for each environment\",\"Use separate regions for each environment\"], correctIndex:1 }\n},\n{\n  id:3, day:1, topic:\"Least Privilege\",\n  question:\"A platform team discovers that application developers can administer resources across the entire tenancy, although their jobs only require access to one application environment. How should the IAM design be changed to follow least privilege?\",\n  answer:\"Apply the principle of least privilege: remove these users from the Administrators group, identify the exact resource-types and compartments each person's job actually needs, create narrowly-scoped groups, write compartment-scoped policies, and add users only to relevant groups.\",\n  explanation:\"Tenancy-wide admin rights mean a mistake or compromised credential can affect the entire tenancy. Replacing broad Administrator membership with function-specific, compartment-scoped groups dramatically reduces the blast radius of any error or breach.\",\n  theory:{ what:\"Least privilege is the security principle that a user or system should be granted only the minimum access required to perform its function \u2014 nothing more.\", why:\"It limits damage from mistakes, insider misuse, or a compromised account, and makes audits far simpler since access maps to job function.\", how:\"Identify actual tasks, map them to the minimum verbs/resource-types/compartments needed, create purpose-built groups, write scoped policies, then remove unnecessary broad memberships.\", example:\"A backup operator only needs 'use' access to object-storage in one compartment \u2014 they should never be in the tenancy Administrators group just for convenience.\" },\n  quick:\"Replace broad Administrator access with narrowly scoped, function-specific groups and compartment-level policies \u2014 grant only what the job requires.\",\n  remember:[\"Least Privilege = Just Enough Access\",\"Admins group = last resort, not default\"],\n  trap:\"A common wrong instinct is to leave admin access 'for convenience' or only add restrictions on top without removing Administrators membership \u2014 least privilege requires actually removing the excess access.\",\n  wrongOptionsNote:\"Simply auditing access without changing group membership does not solve the problem \u2014 the fix requires actual removal from Administrators and creation of scoped groups/policies.\",\n  diagram:{type:\"linear\", steps:[\"Broad Tenancy-Admin Access\",\"Identify actual job function\",\"Create narrowly-scoped Group\",\"Write compartment-scoped Policy\",\"Remove user from Administrators\"]},\n  examAnswer:\"Apply least privilege: remove tenancy-wide admin rights, create job-specific groups scoped to the needed compartments/resource-types, and assign users only to those groups instead of Administrators.\",\n  realWorld:\"A hotel doesn't give every staff member a master key. Housekeeping gets keys only to the floors they clean, not the manager's office \u2014 reducing what can go wrong if a key is lost.\",\n  mcq:{ question:\"What is the correct IAM fix when users have unnecessary tenancy-wide admin access?\", options:[\"Leave access as is but monitor it more closely\",\"Remove them from Administrators and assign scoped, function-based groups\",\"Add MFA but keep Administrator membership\",\"Move all users into a single generic group\"], correctIndex:1 }\n},\n{\n  id:4, day:1, topic:\"Tagging & Cost Governance\",\n  question:\"Finance cannot reliably attribute OCI charges to individual business units because many resources were created without a consistent metadata standard. What tagging and governance process should the organization introduce so that spending can be allocated reliably?\",\n  answer:\"Define a standard Tag Namespace (e.g., 'Business-Unit', 'Cost-Center'), enforce mandatory tagging at resource creation using tag defaults and/or policies, and require every resource to carry these tags. Cost Analysis can then be filtered and grouped by tag so every dollar maps back to a business unit.\",\n  explanation:\"Tags are OCI's mechanism for adding business-relevant metadata to otherwise anonymous cloud resources. Without mandatory, standardized tagging, untagged resources become 'unattributed spend' that no business unit can be held accountable for.\",\n  theory:{ what:\"A tag is a key-value label attached to an OCI resource; a tag namespace is a governed set of tag keys enforced across the tenancy.\", why:\"Tags let cost, usage, and ownership be sliced by business dimension rather than only by compartment or resource type.\", how:\"Define a tag namespace and required keys, set tag defaults so new resources auto-inherit them, and use policies to require tags before creation is allowed. Cost Analysis then groups spend by tag value.\", example:\"Every compute instance must carry a 'Cost-Center' tag. Cost Analysis is filtered by Cost-Center to show exactly how much each department spent last month.\" },\n  quick:\"Enforce a mandatory tag namespace (e.g., Cost-Center) with tag defaults, and use Cost Analysis grouped by tag to attribute spend to a business unit.\",\n  remember:[\"Tags = Business Metadata\",\"No Tag = No Accountability\"],\n  trap:\"Students sometimes suggest compartments alone will fix this \u2014 compartments give structural isolation, but if multiple business units share a compartment, only tags can attribute cost at finer, cross-cutting granularity.\",\n  wrongOptionsNote:\"Relying only on manual, ad-hoc tagging without a namespace and defaults will not solve recurring gaps \u2014 tag defaults and enforcement are required for consistency.\",\n  diagram:{type:\"linear\", steps:[\"Resource Created\",\"Mandatory Tag Applied (Cost-Center)\",\"Tag Namespace Enforced Tenancy-wide\",\"Cost Analysis grouped by Tag\",\"Spend attributed to Business Unit\"]},\n  examAnswer:\"Create a governed tag namespace, apply tag defaults so all new resources are automatically tagged, and enforce tagging via policy. Use Cost Analysis grouped by tag to attribute spend to each business unit.\",\n  realWorld:\"Like labeling every expense receipt with a department name before submitting it to finance \u2014 without the label, accounting has no idea which team to bill.\",\n  mcq:{ question:\"How should an organization ensure all cloud spend can be attributed to a business unit?\", options:[\"Rely on compartment names alone\",\"Enforce mandatory cost-tracking tags with tag defaults\",\"Manually track spend in a spreadsheet\",\"Disable Cost Analysis and use invoices only\"], correctIndex:1 }\n},\n{\n  id:5, day:1, topic:\"Region / AD / Fault Domain\",\n  question:\"An architect is placing two application servers for resilience and wants to understand the physical isolation offered by OCI. How do Region, Availability Domain, and Fault Domain differ, and which placement level protects two instances from a localized hardware problem within one AD?\",\n  answer:\"A Region is a localized geographic area containing one or more data centers. An Availability Domain (AD) is one or more independent data centers within a region, isolated from other ADs by power and networking failures. A Fault Domain (FD) is a logical grouping of hardware inside a single AD, isolating instances from localized hardware failures. To protect against a localized hardware failure inside one AD, distribute instances across different Fault Domains.\",\n  explanation:\"These three levels form OCI's physical hierarchy from broadest to narrowest: Region \u2192 Availability Domain \u2192 Fault Domain \u2192 the compute instance. Fault Domains protect against failures smaller than a whole data center, such as a failed rack or power supply, while keeping instances in the same AD for low-latency connectivity.\",\n  theory:{ what:\"Region = geographic location; Availability Domain = independent data centers inside a region; Fault Domain = hardware grouping inside a single AD.\", why:\"This hierarchy lets architects choose the right blast-radius to protect against: region failure, data-center failure, or a single-rack/hardware failure.\", how:\"Deploy across multiple Regions for disaster recovery; deploy across multiple ADs within a region for data-center-level outages; deploy across multiple Fault Domains within a single AD for rack/hardware-level failures.\", example:\"A 3-node database cluster is placed one instance per Fault Domain inside a single AD \u2014 if one rack loses power, only one node goes down.\" },\n  quick:\"Region = geography, AD = independent data centers, FD = hardware grouping inside an AD. Use Fault Domains to protect against a localized hardware failure within one AD.\",\n  remember:[\"Region = Geography\",\"AD = Data Center Domain\",\"FD = Hardware Failure Domain\"],\n  trap:\"A common mistake is answering 'use multiple Availability Domains' for a hardware-level failure \u2014 multiple ADs protect against data-center-level outages, not a single rack/hardware failure.\",\n  wrongOptionsNote:\"Confusing Region with Availability Domain is also common \u2014 a Region can contain multiple ADs, but a Region itself is a geographic boundary, not an instance-placement resiliency unit.\",\n  diagram:{type:\"linear\", steps:[\"Region (Geography)\",\"Availability Domain (Independent Data Center)\",\"Fault Domain (Hardware Grouping)\",\"Compute Instance\"]},\n  examAnswer:\"Region = geographic area; Availability Domain = independent data center(s); Fault Domain = hardware grouping within one AD. Place instances across different Fault Domains to protect against a localized hardware failure.\",\n  realWorld:\"A Region is like a country; an Availability Domain is like a separate city's data center within that country; a Fault Domain is like a separate power circuit inside one data center \u2014 losing one circuit doesn't take down the whole building.\",\n  mcq:{ question:\"Which infrastructure level should you use to protect instances from a single rack/hardware failure inside one Availability Domain?\", options:[\"Region\",\"Availability Domain\",\"Fault Domain\",\"Compartment\"], correctIndex:2 }\n},\n{\n  id:6, day:1, topic:\"Identity Management Design\",\n  question:\"A new OCI tenancy has separate operations, development, and audit teams. Propose an identity design using users, groups, roles/permissions, and policies so access is assigned to teams rather than individually maintained for every employee.\",\n  answer:\"Organize people into Groups based on job function. Organize resources into Compartments based on environment/business-unit. Write Policies that grant each Group specific verbs on specific resource-types within specific compartments. Use Dynamic Groups for non-human/instance-based access, and Identity Domains for centralized authentication (federation/SSO/MFA).\",\n  explanation:\"OCI IAM is built from five core building blocks: Users, Groups, Compartments, Policies, and Dynamic Groups \u2014 all managed within an Identity Domain. Users never get permissions individually; they inherit permissions purely through group membership.\",\n  theory:{ what:\"OCI IAM is the framework of Users, Groups, Compartments and Policies used to authenticate identities and authorize access to resources.\", why:\"Centralizing identity design around groups and compartments keeps access consistent, auditable, and easy to change.\", how:\"Create Users, place them into Groups by function, organize resources into Compartments, write Policies connecting Groups to Compartments. Enable MFA and federate through Identity Domains; use Dynamic Groups for instances/services needing API access.\", example:\"New hires join the 'Developers' group, which has a policy granting 'use' on compute instances in Development only \u2014 no individual policy is written per person.\" },\n  quick:\"Design identity around Users \u2192 Groups \u2192 Policies \u2192 Compartments, using Identity Domains for authentication/MFA and Dynamic Groups for non-human access.\",\n  remember:[\"Users join Groups\",\"Groups get Policies\",\"Policies target Compartments\"],\n  trap:\"Students sometimes suggest granting permissions directly to individual users. OCI IAM policies can only reference Groups (and Dynamic Groups), not individual users.\",\n  wrongOptionsNote:\"Skipping compartments and applying all policies tenancy-wide defeats the purpose of scoped access.\",\n  diagram:{type:\"linear\", steps:[\"Users\",\"Groups (by job function)\",\"Policies (verb + resource-type)\",\"Compartments (scope)\"]},\n  examAnswer:\"Organize users into function-based Groups, resources into Compartments, connect them with scoped Policies. Use Identity Domains for authentication/MFA/federation and Dynamic Groups for instance-based access.\",\n  realWorld:\"Like a company assigning employees to departments (Groups) instead of writing a unique security clearance for every single employee \u2014 much easier to manage at scale.\",\n  mcq:{ question:\"In OCI IAM, how are permissions ultimately granted to a user?\", options:[\"Directly to the individual user\",\"Through the group(s) the user belongs to\",\"Through their email domain\",\"Through the compartment they log into\"], correctIndex:1 }\n},\n{\n  id:7, day:2, topic:\"Budget vs Quota\",\n  question:\"A cloud team wants one control to warn management when spending approaches a monthly financial threshold and another control to restrict how many resources a compartment can consume. Which OCI mechanisms provide these two controls, and what happens when each threshold is reached?\",\n  answer:\"A Budget tracks and controls spending against a compartment or tag, and when its threshold is reached it sends an alert notification \u2014 it does not block resource creation. A Quota controls resource consumption at a compartment level, and when its limit is reached, it actively restricts further creation of that resource-type.\",\n  explanation:\"Budgets and Quotas solve two different governance problems that are frequently confused: Budgets are financial monitoring/alerting (reactive), while Quotas are a hard, preventive resource-consumption control (proactive/restrictive).\",\n  theory:{ what:\"A Budget monitors cost against a compartment or cost-tracking tag. A Quota restricts how many of a resource-type a compartment can consume.\", why:\"Budgets give financial visibility and early-warning alerts; Quotas give hard, technical guardrails to prevent runaway resource sprawl.\", how:\"A Budget is configured with a monthly amount and alert thresholds (e.g. 80%, 100%) that trigger notifications. A Quota is written in quota-policy syntax specifying a maximum count of a resource-type; once reached, OCI blocks further creation.\", example:\"A team sets a Budget of $5,000/month with an 80% alert. Separately, a Quota limits a compartment to 10 compute instances \u2014 the 11th creation is blocked outright.\" },\n  quick:\"Budget = money (alerts only). Quota = resource consumption (actively blocks creation once the limit is reached).\",\n  remember:[\"Budget = MONEY, sends an Alert\",\"Quota = RESOURCES, blocks Creation\"],\n  trap:\"The most common trap is assuming a Budget can stop resource creation like a Quota does \u2014 a Budget only notifies; it never technically prevents spending or creation.\",\n  wrongOptionsNote:\"Confusing a Quota with a Service Limit is also a classic trap \u2014 a Quota is a customer-configurable restriction within the Oracle-imposed Service Limit.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Budget\", steps:[\"Money / Spending\",\"Threshold (e.g., 80%)\",\"Alert Notification Sent\"]}, {title:\"Quota\", steps:[\"Resource Consumption\",\"Quota Limit Reached\",\"Resource Creation Restricted\"]} ]},\n  examAnswer:\"A Budget monitors spend and sends an alert when a threshold is crossed \u2014 it does not block anything. A Quota restricts resource-type consumption and actively blocks creation once the limit is hit.\",\n  realWorld:\"A Budget is like a bank app that texts you when you're close to your monthly spending limit \u2014 it warns you but doesn't stop the transaction. A Quota is like a debit card with a hard daily cap that gets declined once you hit it.\",\n  mcq:{ question:\"What happens when an OCI Budget threshold is reached?\", options:[\"Resource creation is blocked automatically\",\"An alert notification is sent, but nothing is blocked\",\"The compartment is deleted\",\"A Quota is automatically created\"], correctIndex:1 }\n},\n{\n  id:8, day:2, topic:\"Security Advisor\",\n  question:\"During a security posture review, an administrator wants OCI-generated guidance rather than an automated blocking control. What does Security Advisor provide, and what is an example of the type of improvement its recommendations can highlight?\",\n  answer:\"Security Advisor scans the tenancy's configuration against OCI security best practices and returns prioritized, actionable recommendations \u2014 it does not detect active threats or automatically fix anything, it advises. Example: it might recommend enabling MFA for users who don't have it enabled.\",\n  explanation:\"Security Advisor is a recommendation/advisory engine, distinct from Cloud Guard (detects and responds to active problems) and Security Zones (preventively blocks non-compliant resource creation).\",\n  theory:{ what:\"Security Advisor evaluates a tenancy's configuration against Oracle's recommended security best practices.\", why:\"It gives administrators a prioritized checklist of concrete improvements without requiring them to know every OCI best practice.\", how:\"It scans IAM, networking, storage and other settings, compares them to best-practice baselines, and surfaces actionable recommendations.\", example:\"Security Advisor flags that the 'Administrators' group does not require MFA and recommends enabling it.\" },\n  quick:\"Security Advisor recommends best-practice security improvements based on the tenancy's current configuration \u2014 it advises, it doesn't detect threats or block anything.\",\n  remember:[\"Advisor = Recommend\"],\n  trap:\"Students often confuse Security Advisor with Cloud Guard. Security Advisor gives periodic best-practice recommendations; Cloud Guard continuously detects and responds to active security problems.\",\n  wrongOptionsNote:\"An answer claiming Security Advisor 'blocks' insecure resources is wrong \u2014 that preventive behavior belongs to Security Zones.\",\n  diagram:{type:\"linear\", steps:[\"Tenancy Configuration\",\"Security Advisor Scan\",\"Compared to Best Practices\",\"Prioritized Recommendations (e.g., Enable MFA)\"]},\n  examAnswer:\"Security Advisor evaluates configuration against OCI best practices and returns prioritized recommendations, such as enabling MFA \u2014 it advises but does not detect threats or block resources.\",\n  realWorld:\"Like a home inspector who walks through your house and hands you a checklist of recommended fixes (install smoke detectors, fix the loose railing) \u2014 they point things out, they don't fix them for you.\",\n  mcq:{ question:\"What does OCI Security Advisor primarily do?\", options:[\"Automatically blocks non-compliant resources\",\"Continuously detects and responds to active threats\",\"Recommends security best-practice improvements based on configuration\",\"Encrypts all tenancy data automatically\"], correctIndex:2 }\n},\n{\n  id:9, day:2, topic:\"Cloud Guard\",\n  question:\"A security operations team wants OCI to identify risky configurations and then trigger appropriate remediation for selected findings. Which Cloud Guard components participate in this workflow, and what is the responsibility of each?\",\n  answer:\"Cloud Guard continuously monitors OCI resources using Detectors, which apply detector recipes to identify security problems. When found, the problem is surfaced and can trigger a Responder, which executes a corrective action (automatically or with approval) to remediate the issue.\",\n  explanation:\"Cloud Guard is OCI's continuous detect-and-respond security posture tool. Detectors find problems, Responders fix problems \u2014 together forming a closed monitoring-and-remediation loop.\",\n  theory:{ what:\"Cloud Guard is an OCI native security service that continuously monitors resources, detects misconfigurations and threats, and can automatically respond to them.\", why:\"Manual reviews cannot keep up with a dynamic cloud environment \u2014 Cloud Guard provides continuous, automated detection and remediation.\", how:\"Detector recipes continuously scan resources and activity logs for risky patterns, generating a Problem when found. Responder recipes then define corrective action, automatically or after admin approval.\", example:\"A Configuration Detector notices a bucket was made public. Cloud Guard raises a Security Problem, and a Responder automatically makes the bucket private again.\" },\n  quick:\"Cloud Guard continuously detects security problems using Detectors and can automatically fix them using Responders \u2014 a closed detect-and-respond loop.\",\n  remember:[\"Detector = Detect\",\"Responder = Respond\"],\n  trap:\"Exams often test whether students think Cloud Guard prevents resources from being created in the first place \u2014 it does not. Prevention at creation-time is the job of Security Zones.\",\n  wrongOptionsNote:\"An answer that swaps the roles (Responder detects, Detector fixes) reverses the correct definitions.\",\n  diagram:{type:\"linear\", steps:[\"OCI Resources\",\"Cloud Guard\",\"Detector\",\"Security Problem\",\"Responder\",\"Corrective Action\"]},\n  examAnswer:\"Cloud Guard continuously monitors resources. Detectors identify security problems; Responders execute corrective actions to remediate them, automatically or with approval.\",\n  realWorld:\"Like a smart home security system: motion sensors (Detectors) notice someone at the door, and the system (Responder) can automatically lock the doors or call the police.\",\n  mcq:{ question:\"In Cloud Guard, what is the role of a Responder?\", options:[\"It detects the security problem\",\"It executes a corrective action to fix a detected problem\",\"It generates the security recommendation report\",\"It approves new IAM policies\"], correctIndex:1 }\n},\n{\n  id:10, day:2, topic:\"BYOL vs License Included\",\n  question:\"A company has existing licenses for software that it plans to run with an OCI service. The architect is comparing bringing those licenses to OCI with purchasing the license as part of the cloud service. When is the existing-license model appropriate, and how does it differ from License Included?\",\n  answer:\"With License Included (LI), Oracle bundles the software license into the OCI service's rate. With Bring Your Own License (BYOL), the customer uses licenses they already own and pays OCI only for the underlying infrastructure, at a lower rate. The organization should choose BYOL because it already owns eligible licenses \u2014 reusing them avoids paying for a license twice.\",\n  explanation:\"BYOL vs License Included is purely a cost/licensing decision, not a technical one \u2014 the underlying OCI service works the same either way. The determining factor is whether the customer already holds eligible, unused licenses.\",\n  theory:{ what:\"License Included means the OCI service price includes the software license cost. BYOL means the customer supplies their own already-purchased license and pays only for infrastructure.\", why:\"Organizations that already invested in Oracle software licenses can reuse them in OCI instead of paying for a duplicate license bundled into the service price.\", how:\"When provisioning a licensable OCI service, the customer selects a licensing option. BYOL requires enough eligible, unused licenses to cover the deployment; the service is then billed at the infrastructure-only rate.\", example:\"A company already owns Oracle Database Enterprise Edition licenses. They select BYOL and pay only the compute/storage rate, saving the bundled license cost.\" },\n  quick:\"License Included bundles the license into OCI's price; BYOL lets you reuse licenses you already own and pay only for infrastructure. Choose BYOL when you already hold eligible licenses.\",\n  remember:[\"LI = License + Infra bundled\",\"BYOL = Bring your own License, pay Infra only\"],\n  trap:\"A trap is assuming BYOL is always cheaper regardless of circumstances \u2014 it's only advantageous when the organization genuinely already owns unused, eligible licenses.\",\n  wrongOptionsNote:\"Claiming BYOL changes the technical capability of the service is incorrect \u2014 the licensing choice affects billing only.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"License Included\", steps:[\"No existing license\",\"Oracle provides license\",\"Pay bundled infra + license rate\"]}, {title:\"BYOL\", steps:[\"Existing eligible license owned\",\"Bring license to OCI\",\"Pay infrastructure-only rate\"]} ]},\n  examAnswer:\"License Included bundles license cost into the service price; BYOL lets an organization apply licenses it already owns and pay only the infrastructure rate. Choose BYOL whenever eligible unused licenses already exist.\",\n  realWorld:\"Like bringing your own streaming subscription's login to a friend's smart TV instead of paying for a separate subscription bundled with the TV.\",\n  mcq:{ question:\"When should an organization choose BYOL over License Included?\", options:[\"When it wants Oracle to fully manage licensing regardless of cost\",\"When it already owns eligible, unused licenses\",\"When it has no existing licenses\",\"BYOL and License Included are technically identical, so it never matters\"], correctIndex:1 }\n},\n{\n  id:11, day:2, topic:\"Budget & Cost Analysis\",\n  question:\"The finance team wants an automatic warning before cloud spending exceeds its approved amount and also needs to analyze charges by service, compartment, and other dimensions. Which OCI cost-management features should they use and what does each one answer?\",\n  answer:\"Use a Budget to set a spending threshold and receive alerts as spend approaches or exceeds it. Use Cost Analysis to visually explore and break down where the tenancy's spend is coming from \u2014 by compartment, service, or tag.\",\n  explanation:\"Budget and Cost Analysis are complementary but distinct: Budget is proactive alerting against a target amount, while Cost Analysis is exploratory/visual reporting to understand spend composition and trends.\",\n  theory:{ what:\"Budget is a threshold-based spend-alerting feature; Cost Analysis is an interactive visualization tool for exploring cost and usage data.\", why:\"Together they cover both halves of cost governance: getting warned before overspending, and understanding the 'why' behind the numbers.\", how:\"A Budget is set against a compartment or tag with alert thresholds that trigger notifications. Cost Analysis lets you filter and group historical spend by compartment, service, SKU, or tag over custom date ranges.\", example:\"A Budget alerts finance at 80% of the monthly cap. The admin opens Cost Analysis, groups by service, and discovers most spend is coming from an oversized Block Volume allocation.\" },\n  quick:\"Budget sends threshold-based spend alerts; Cost Analysis visualizes and breaks down where the spend is actually coming from.\",\n  remember:[\"Budget = Warns you\",\"Cost Analysis = Explains it\"],\n  trap:\"Students sometimes think Cost Analysis can send alerts, or that Budget provides a service breakdown \u2014 Budget only tracks a single target and alerts.\",\n  wrongOptionsNote:\"Suggesting only one of the two features fully answers the question is incomplete \u2014 the requirement has two parts, each mapping to a different feature.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Budget\", steps:[\"Set spend threshold\",\"Monitor spend vs threshold\",\"Send alert notification\"]}, {title:\"Cost Analysis\", steps:[\"Pull usage & cost data\",\"Group by compartment/service/tag\",\"Visualize spend breakdown\"]} ]},\n  examAnswer:\"Use Budget to set a threshold and get alerted as spend approaches it. Use Cost Analysis to visually break down where that spend is coming from by compartment, service, or tag.\",\n  realWorld:\"A Budget is your monthly spending alert; Cost Analysis is like your bank statement's category breakdown, showing exactly how much went to groceries vs. entertainment.\",\n  mcq:{ question:\"Which OCI feature would you use to understand WHERE tenancy spend is coming from (by service/compartment/tag)?\", options:[\"Budget\",\"Cost Analysis\",\"Quota\",\"Security Advisor\"], correctIndex:1 }\n},\n{\n  id:12, day:2, topic:\"Service Limit vs Quota\",\n  question:\"A team is unable to create another resource even though the service appears to support more capacity overall. The administrator suspects that a tenancy-level service limit and a compartment-level quota are being confused. Explain the distinction and how each can affect resource creation.\",\n  answer:\"A Service Limit is the maximum amount of a resource an Oracle tenancy is allowed to use, set by Oracle. A Quota is an administrator-defined restriction that caps resource consumption within a compartment \u2014 set below the service limit for internal governance. The described restriction, occurring before the overall tenancy limit is hit, is caused by a Quota, not the Service Limit.\",\n  explanation:\"Service Limits and Quotas both cap resource counts, but at different layers: Oracle sets the outer Service Limit for the whole tenancy/region; the customer optionally sets a tighter inner Quota per compartment.\",\n  theory:{ what:\"A Service Limit is Oracle's tenancy/region-wide ceiling on a resource. A Quota is a customer-defined, compartment-level restriction equal to or tighter than the Service Limit.\", why:\"Service Limits protect Oracle's infrastructure and give a safe operating ceiling; Quotas let customers subdivide that ceiling internally.\", how:\"Service Limits can be increased via a service request to Oracle. Quotas are written by administrators using quota-policy statements and always apply within the Oracle service limit.\", example:\"The tenancy's Service Limit allows 100 compute instances region-wide, but the admin sets a Quota of 10 for the Development compartment \u2014 creation is blocked at 10 even though the tenancy is far from 100.\" },\n  quick:\"Service Limit = Oracle's tenancy-wide ceiling on a resource. Quota = a customer-set, compartment-level restriction inside that ceiling.\",\n  remember:[\"Service Limit = Oracle's outer wall\",\"Quota = Customer's inner fence\"],\n  trap:\"The exam trap is assuming any resource-creation block means the tenancy is 'out of capacity' \u2014 a block can happen well before the true Service Limit because an admin-defined Quota is tighter.\",\n  wrongOptionsNote:\"Assuming only Oracle can restrict resource creation is wrong \u2014 Quotas are explicitly a customer/administrator-controlled restriction.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Service Limit\", steps:[\"Set by Oracle\",\"Tenancy/Region-wide ceiling\",\"Raised via Oracle service request\"]}, {title:\"Quota\", steps:[\"Set by Administrator\",\"Compartment-level restriction\",\"Always within the Service Limit\"]} ]},\n  examAnswer:\"A Service Limit is Oracle's maximum allowed resource usage. A Quota is a customer-defined, compartment-scoped restriction inside that limit. The described block is a Quota, since it occurred before the true Service Limit was reached.\",\n  realWorld:\"The building has a fire-code capacity of 500 people (Service Limit set by the city), but the office manager caps meeting room bookings to 20 people (Quota) well before that fire-code number is ever reached.\",\n  mcq:{ question:\"A resource creation is blocked well before the tenancy's true capacity is reached. What is the most likely cause?\", options:[\"The Oracle-wide Service Limit was reached\",\"A customer-defined Quota is restricting that compartment\",\"The region is out of Availability Domains\",\"Cloud Guard blocked the resource\"], correctIndex:1 }\n},\n{\n  id:13, day:2, topic:\"Defense in Depth\",\n  question:\"A security architect refuses to depend on a single control for a production application. Describe the security design principle behind this decision and give an OCI example where multiple independent controls work together.\",\n  answer:\"This describes Defense in Depth \u2014 layering multiple, independent security controls so that if one layer fails, others still protect the workload. An OCI example: combining Network Security Groups (network layer), IAM policies with MFA (identity layer), and data encryption at rest (data layer) around the same workload.\",\n  explanation:\"Defense in Depth assumes that no single control is perfect. Stacking independent layers \u2014 network, identity, application, data, and monitoring \u2014 means a failure at one layer is caught or mitigated by another.\",\n  theory:{ what:\"Defense in Depth is a security strategy that uses multiple, independent layers of controls rather than relying on any single protective measure.\", why:\"Every individual control can fail or be bypassed; layering ensures a single point of failure does not lead to a full breach.\", how:\"Apply controls at every relevant layer: network (NSGs, Security Lists), identity (IAM, MFA), application, data (encryption), and monitoring (Cloud Guard, Audit).\", example:\"A database is protected by an NSG restricting inbound traffic, an IAM policy limiting who can manage it, encryption at rest, and Cloud Guard monitoring \u2014 four independent layers.\" },\n  quick:\"Defense in Depth layers multiple independent security controls (network, identity, data, monitoring) so no single failure exposes the workload.\",\n  remember:[\"Defense in Depth = Many Layers, One Goal\"],\n  trap:\"Students sometimes name only one control (e.g., 'just use a firewall') when asked for the principle \u2014 the whole point is that it's never just one control.\",\n  wrongOptionsNote:\"Naming Zero Trust instead of Defense in Depth is a common mix-up \u2014 Zero Trust is about not trusting network location by default; Defense in Depth is about stacking multiple layered controls.\",\n  diagram:{type:\"layers\", layers:[ {label:\"Monitoring\", detail:\"Cloud Guard, Audit Logs\"}, {label:\"Data\", detail:\"Encryption at rest / in transit\"}, {label:\"Identity\", detail:\"IAM Policies, MFA\"}, {label:\"Network\", detail:\"NSGs, Security Lists\"} ]},\n  examAnswer:\"Defense in Depth uses multiple independent security layers so no single control's failure compromises the workload. Example: NSGs + IAM policies with MFA + encryption at rest + Cloud Guard monitoring around the same workload.\",\n  realWorld:\"Like a medieval castle: a moat, a wall, a locked gate, and guards inside \u2014 if an intruder gets past one layer, more layers stand between them and the treasure.\",\n  mcq:{ question:\"What does the Defense in Depth principle recommend?\", options:[\"Rely on one very strong control, like a firewall\",\"Use multiple independent layers of security controls\",\"Rely entirely on Zero Trust and skip network controls\",\"Only secure the data layer, since that's most valuable\"], correctIndex:1 }\n},\n{\n  id:14, day:2, topic:\"CIA Triad\",\n  question:\"A healthcare application must keep records secret from unauthorized users, prevent unauthorized changes, and remain accessible to authorized staff. Map these three requirements to the three elements of the CIA model.\",\n  answer:\"Confidentiality protects data from unauthorized disclosure \u2014 enforced through IAM policies and encryption. Integrity protects data from unauthorized or accidental alteration \u2014 enforced through hashing, checksums, and access controls. Availability ensures data and services remain accessible to authorized users when needed \u2014 enforced through redundancy, high availability, and disaster recovery.\",\n  explanation:\"The CIA triad is the foundational model for reasoning about security objectives. Every security control can be mapped to protecting one or more of these three properties.\",\n  theory:{ what:\"The CIA triad is a foundational information-security model of Confidentiality, Integrity, and Availability.\", why:\"It gives a simple, complete framework for evaluating whether a control actually addresses a real risk.\", how:\"Confidentiality via encryption and IAM. Integrity via checksums, digital signatures, versioning. Availability via redundancy across Fault Domains/ADs/Regions, backups, and DR planning.\", example:\"Encrypting a database protects Confidentiality; enabling object versioning protects Integrity; deploying across multiple ADs protects Availability.\" },\n  quick:\"Confidentiality = keep data secret, Integrity = keep data correct/unaltered, Availability = keep data/services accessible.\",\n  remember:[\"Confidentiality = Secret\",\"Integrity = Correct\",\"Availability = Accessible\"],\n  trap:\"Students sometimes swap Integrity and Availability \u2014 Integrity is about correctness/tamper-protection, Availability is purely about uptime/access.\",\n  wrongOptionsNote:\"Describing Confidentiality as 'making sure data isn't lost' confuses it with backup/Availability concerns \u2014 Confidentiality is strictly about unauthorized disclosure.\",\n  diagram:{type:\"tree\", root:\"CIA Triad\", children:[\"Confidentiality \u2014 Secret\",\"Integrity \u2014 Correct\",\"Availability \u2014 Accessible\"]},\n  examAnswer:\"CIA = Confidentiality (prevent unauthorized disclosure), Integrity (prevent unauthorized/accidental alteration), Availability (ensure authorized access when needed).\",\n  realWorld:\"Confidentiality is a locked diary (only you can read it). Integrity is a sealed envelope (no one can secretly change the letter inside). Availability is the mail service actually delivering it on time.\",\n  mcq:{ question:\"Which CIA principle is protected by encrypting data at rest?\", options:[\"Availability\",\"Confidentiality\",\"Integrity\",\"Accountability\"], correctIndex:1 }\n},\n{\n  id:15, day:2, topic:\"Zero Trust\",\n  question:\"An organization previously trusted requests simply because they originated inside its corporate network. It is moving to a model that evaluates every access request based on identity, context, and policy. Which security approach is this, and what principle drives it?\",\n  answer:\"A traditional perimeter model trusts anything inside the corporate network boundary by default and only inspects traffic at the edge. Zero Trust removes that assumption entirely \u2014 no user, device, or request is trusted by default, regardless of network location; every request must be authenticated and authorized on its own merits. A fundamental Zero Trust principle: 'Never trust, always verify.'\",\n  explanation:\"Zero Trust responds to the reality that threats can originate from inside the network just as easily as from outside \u2014 so trust must never be granted based on network location alone.\",\n  theory:{ what:\"Zero Trust is a security model in which no user, device, or system is trusted by default, even if it is already inside the corporate network perimeter.\", why:\"Perimeter-based trust fails once an attacker or compromised credential gets inside the network \u2014 Zero Trust removes the 'soft interior.'\", how:\"Every access request is authenticated and authorized individually, typically using MFA, least-privilege access, and continuous monitoring rather than relying on network segmentation alone.\", example:\"Under Zero Trust, an employee on the corporate VPN still has to pass MFA and a scoped IAM policy check to access an OCI resource.\" },\n  quick:\"Zero Trust assumes no implicit trust based on network location \u2014 every request is verified individually. Core principle: 'Never trust, always verify.'\",\n  remember:[\"Zero Trust = Verify Every Time\",\"Perimeter Model = Trust Inside, Guard Only the Edge\"],\n  trap:\"A trap answer describes Zero Trust as simply 'more firewalls' \u2014 it's fundamentally about identity-based, continuous verification.\",\n  wrongOptionsNote:\"Stating Zero Trust eliminates the need for IAM policies is wrong \u2014 it actually depends heavily on strong identity verification and IAM.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Perimeter Model\", steps:[\"Inside network = trusted\",\"Guard only at the edge\",\"Minimal internal verification\"]}, {title:\"Zero Trust\", steps:[\"No implicit trust, anywhere\",\"Verify every request\",\"Continuous authentication & authorization\"]} ]},\n  examAnswer:\"Perimeter models trust anything inside the network boundary; Zero Trust removes that assumption and verifies every request regardless of location. Fundamental principle: never trust, always verify.\",\n  realWorld:\"Like a high-security office that re-checks your ID badge at every single door, even if you already badged into the building lobby \u2014 being 'inside' grants no extra trust.\",\n  mcq:{ question:\"What is a core Zero Trust principle?\", options:[\"Trust any device inside the corporate network\",\"Never trust, always verify \u2014 regardless of network location\",\"Rely solely on perimeter firewalls\",\"Grant broad access once MFA is enabled once\"], correctIndex:1 }\n},\n{\n  id:16, day:2, topic:\"Shared Responsibility Model\",\n  question:\"An OCI customer believes Oracle should configure every security control for its workload. Explain how security responsibilities are divided between Oracle and the customer, and give one example responsibility for each side.\",\n  answer:\"The Shared Responsibility Model divides security duties between Oracle and the customer: Oracle secures the underlying cloud infrastructure ('security OF the cloud') \u2014 physical data center security, hardware, and virtualization \u2014 while the customer secures what they configure and put in the cloud ('security IN the cloud') \u2014 e.g., IAM policy configuration and data classification/access control.\",\n  explanation:\"This model corrects the common misconception that moving to the cloud means Oracle handles all security. A customer's misconfiguration (e.g., an overly permissive IAM policy) is the customer's own responsibility.\",\n  theory:{ what:\"The Shared Responsibility Model defines which security tasks Oracle handles versus which the customer must handle.\", why:\"It sets clear expectations so customers understand which risks remain entirely their own responsibility, even in a fully managed cloud.\", how:\"Oracle handles physical data centers, hardware, network infra, and the hypervisor. The customer handles IAM configuration, security rules they define, OS-level patching (IaaS), data classification, and application security.\", example:\"Oracle ensures the physical data center and host hardware are secure; the customer ensures a compute instance isn't accidentally exposed via a wrong IAM policy.\" },\n  quick:\"Oracle secures the cloud infrastructure itself; the customer secures what they configure and store in it. Misconfiguration is always the customer's responsibility.\",\n  remember:[\"Oracle = Security OF the Cloud\",\"Customer = Security IN the Cloud\"],\n  trap:\"The exam trap is assuming Oracle patches/secures everything including the customer's OS and application layer for IaaS \u2014 for IaaS, OS patching remains the customer's responsibility.\",\n  wrongOptionsNote:\"Claiming the customer is responsible for physical data center security is incorrect \u2014 that is exclusively Oracle's responsibility.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Oracle \u2014 OF the Cloud\", steps:[\"Physical data centers\",\"Hardware & network infra\",\"Hypervisor / virtualization\"]}, {title:\"Customer \u2014 IN the Cloud\", steps:[\"IAM policy configuration\",\"Data classification & access\",\"OS patching (IaaS)\"]} ]},\n  examAnswer:\"Shared Responsibility Model: Oracle secures the underlying cloud infrastructure; the customer secures what they configure and run in it. Misconfiguration risk always stays with the customer.\",\n  realWorld:\"Like renting an apartment: the landlord secures the building's locks and structure, but you're responsible for locking your own apartment door and not leaving your key under the mat.\",\n  mcq:{ question:\"Under the Shared Responsibility Model, who is responsible for correctly configuring IAM policies?\", options:[\"Oracle\",\"The customer\",\"Both equally, with no distinction\",\"Neither \u2014 IAM is automatically configured\"], correctIndex:1 }\n},\n{\n  id:17, day:2, topic:\"Security Zones\",\n  question:\"A compliance team wants OCI to stop administrators from creating resources that violate mandatory security configurations. Which OCI control should be selected, and how does it differ from a service that mainly detects problems after resources exist?\",\n  answer:\"Use OCI Security Zones. Its primary purpose is preventive: it attaches a set of security policies to a compartment and blocks \u2014 at creation time \u2014 any resource action that would violate those policies, rather than only detecting the violation afterward.\",\n  explanation:\"Security Zones is the only one of OCI's three security-posture tools that actively prevents non-compliant actions before they happen, instead of detecting/recommending after the fact.\",\n  theory:{ what:\"Security Zones enforces a defined set of security best-practice policies on a compartment, blocking any resource creation or update that would violate them.\", why:\"Detection after the fact is valuable, but some organizations need a hard guarantee that non-compliant resources can never even be created.\", how:\"An administrator attaches a Security Zone recipe (predefined policies) to a compartment. OCI evaluates every resource action against those policies in real time and rejects violations.\", example:\"A recipe requiring 'no internet-facing subnets' is attached to Production \u2014 an attempt to create a public subnet there is blocked immediately.\" },\n  quick:\"Security Zones prevents non-compliant resource configurations by blocking violating actions at creation time within an attached compartment.\",\n  remember:[\"Zones = Prevent\"],\n  trap:\"Students often answer 'Cloud Guard' for this question \u2014 but Cloud Guard only detects and responds after the fact; only Security Zones actively blocks creation.\",\n  wrongOptionsNote:\"Answering 'Security Advisor' is also wrong \u2014 Security Advisor only recommends, it does not block anything.\",\n  diagram:{type:\"linear\", steps:[\"Security Zone Recipe (Policies)\",\"Attached to Compartment\",\"Resource Creation Attempted\",\"Evaluated Against Policies\",\"Non-compliant Action Blocked\"]},\n  examAnswer:\"Use Security Zones. Its primary purpose is preventive \u2014 it blocks the creation of resources that would violate the security policies attached to a compartment.\",\n  realWorld:\"Like a construction site that won't let a truck through the gate at all unless it passes a safety checklist \u2014 it's blocked at the gate, not flagged after it's already inside.\",\n  mcq:{ question:\"Which OCI feature actively blocks the creation of non-compliant resources?\", options:[\"Cloud Guard\",\"Security Advisor\",\"Security Zones\",\"Cost Analysis\"], correctIndex:2 }\n},\n{\n  id:18, day:2, topic:\"Security Posture Management\",\n  question:\"A security manager is designing a tenancy-wide posture program and wants three complementary capabilities: identify security problems, prevent prohibited configurations, and receive recommendations for improvements. Which OCI features fit those three roles?\",\n  answer:\"Combine all three complementary OCI security-posture tools: Cloud Guard for continuous detection and automated response, Security Zones for preventive guardrails, and Security Advisor for best-practice configuration recommendations.\",\n  explanation:\"No single tool covers detect, prevent, and recommend \u2014 each requirement maps to exactly one OCI security posture service, and a complete approach uses all three together.\",\n  theory:{ what:\"Security posture management is the combined use of monitoring, preventive, and advisory tools to continuously improve a tenancy's security state.\", why:\"Relying on only one tool leaves gaps \u2014 detection alone doesn't prevent bad configurations, prevention alone doesn't catch active threats.\", how:\"Enable Cloud Guard tenancy-wide, attach Security Zone recipes to sensitive compartments, and regularly review Security Advisor recommendations.\", example:\"A tenancy enables Cloud Guard to catch a misconfigured bucket, attaches a Security Zone to Production to prevent that entirely, and reviews Security Advisor weekly.\" },\n  quick:\"A complete security posture uses all three tools together: Cloud Guard (detect + respond), Security Zones (prevent), and Security Advisor (recommend).\",\n  remember:[\"Cloud Guard = Detect & Respond\",\"Security Zones = Prevent\",\"Security Advisor = Recommend\"],\n  trap:\"Picking just one of the three tools when the question asks for continuous monitoring AND prevention AND recommendations is an incomplete answer.\",\n  wrongOptionsNote:\"Treating Cloud Guard and Security Zones as interchangeable is incorrect \u2014 one is reactive/detective, the other preventive.\",\n  diagram:{type:\"tree\", root:\"Security Posture Management\", children:[\"Cloud Guard \u2014 Detect & Respond\",\"Security Zones \u2014 Prevent\",\"Security Advisor \u2014 Recommend\"]},\n  examAnswer:\"Use Cloud Guard for continuous detection/response, Security Zones for preventive enforcement, and Security Advisor for ongoing recommendations \u2014 together a complete security posture approach.\",\n  realWorld:\"Like airport security: cameras that detect suspicious behavior (Cloud Guard), a metal detector that physically blocks banned items (Security Zones), and a safety audit report (Security Advisor) \u2014 all working together.\",\n  mcq:{ question:\"Which combination provides complete security posture management (detect, prevent, recommend)?\", options:[\"Cloud Guard only\",\"Security Zones only\",\"Cloud Guard + Security Zones + Security Advisor\",\"IAM Policies only\"], correctIndex:2 }\n},\n{\n  id:19, day:2, topic:\"Cost Governance by Department\",\n  question:\"Five business units share one OCI tenancy and leadership needs monthly spend visibility for each unit. Design a governance approach using resource organization and metadata so finance can attribute charges without creating a separate tenancy for every department.\",\n  answer:\"Create a compartment per department (or a mandatory 'Department' cost-tracking tag if a shared compartment structure must remain), set a separate Budget per department, and use Cost Analysis grouped by compartment or tag to monitor each department's spend individually.\",\n  explanation:\"This combines three governance tools: Compartments (or Tags) for attribution, Budgets for per-department alerting, and Cost Analysis for ongoing visibility \u2014 applied at the department level.\",\n  theory:{ what:\"Department-level cost governance combines structural isolation with financial monitoring tools so spend can be tracked per organizational unit.\", why:\"Without a per-department boundary, all spend is blended and no single department can be held accountable.\", how:\"Create a compartment for each department, set an individual Budget for each with its own thresholds, and use Cost Analysis grouped by compartment or tag.\", example:\"'Marketing' and 'Engineering' each get their own compartment and their own $10,000 Budget; Cost Analysis shows each department's trend independently.\" },\n  quick:\"Give each department its own compartment (or tag), its own Budget for alerts, and use Cost Analysis grouped by compartment/tag for ongoing visibility.\",\n  remember:[\"1 Department = 1 Compartment (or Tag) = 1 Budget\"],\n  trap:\"A trap is recommending only Cost Analysis without any Budget \u2014 Cost Analysis alone provides visibility but no proactive alerting.\",\n  wrongOptionsNote:\"Recommending a single tenancy-wide Budget for all five departments combined fails the requirement to monitor each department separately.\",\n  diagram:{type:\"linear\", steps:[\"Compartment (or Tag) per Department\",\"Budget set per Department\",\"Cost Analysis grouped by Compartment/Tag\",\"Per-department spend visibility\"]},\n  examAnswer:\"Create a compartment (or consistent tag) per department, configure an individual Budget per department, and use Cost Analysis grouped by compartment/tag to monitor each department's spend independently.\",\n  realWorld:\"Like a shared family credit card being split into separate authorized-user cards per family member, each with a spending alert set for their own limit.\",\n  mcq:{ question:\"What is the best approach to track spend separately for 5 departments sharing one tenancy?\", options:[\"One shared Budget for the whole tenancy\",\"Compartment/tag per department with individual Budgets\",\"Ask each department to self-report spend manually\",\"Disable cost tracking for shared resources\"], correctIndex:1 }\n},\n{\n  id:20, day:2, topic:\"Compliance Audit Review\",\n  question:\"An organization is preparing evidence for an internal OCI compliance review. Which two categories of control evidence would you inspect first, and which OCI records or governance mechanisms could provide that evidence?\",\n  answer:\"Review (1) IAM configuration \u2014 group memberships, policy scope, and MFA enrollment \u2014 with evidence from the Identity console; and (2) activity/change history \u2014 who did what and when \u2014 with evidence from the Audit service, which retains a record of API calls and console actions.\",\n  explanation:\"A compliance audit needs to answer two questions: 'who can access what' and 'what actually happened' \u2014 OCI provides a distinct, purpose-built source of evidence for each.\",\n  theory:{ what:\"Compliance review areas are the configuration and activity domains an auditor examines to confirm a tenancy meets required standards.\", why:\"Auditors need concrete, retrievable evidence that access controls are correctly scoped and that changes are tracked and attributable.\", how:\"Pull Groups, Policy statements, and MFA status from the Identity console for access review. Pull records from the Audit service, which logs every API call (who, what, when, from where).\", example:\"An auditor asks 'who can delete production databases?' \u2014 answered via IAM policies in the Identity console. Then 'was this policy ever changed without approval?' \u2014 answered via the Audit service.\" },\n  quick:\"Review IAM configuration (evidence: Identity console) and activity/change history (evidence: Audit service) as the two core compliance audit areas.\",\n  remember:[\"IAM \u2192 Identity Console\",\"Activity \u2192 Audit Service\"],\n  trap:\"Students sometimes name only IAM and forget auditors equally need change/activity history, which lives in the Audit service, not the Identity console.\",\n  wrongOptionsNote:\"Claiming Cost Analysis is a primary compliance evidence source is a mismatch \u2014 it's a financial tool, not an access-control or activity-audit source.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"IAM Review\", steps:[\"Groups & Policy scope\",\"MFA enrollment\",\"Evidence: Identity Console\"]}, {title:\"Activity Review\", steps:[\"API calls & console actions\",\"Who / What / When\",\"Evidence: Audit Service\"]} ]},\n  examAnswer:\"Review IAM configuration (groups, policy scope, MFA) using Identity console evidence, and review activity/change history using Audit service evidence, which logs all API and console actions.\",\n  realWorld:\"Like reviewing a building's keycard access list (IAM) and its security-camera footage log (Audit) before a safety inspection \u2014 two different systems, two different kinds of proof.\",\n  mcq:{ question:\"Where would you find evidence of who performed a specific configuration change in OCI?\", options:[\"Cost Analysis\",\"Audit service\",\"Security Advisor\",\"Quotas page\"], correctIndex:1 }\n},\n{\n  id:21, day:2, topic:\"Capstone \u2014 Operating Model\",\n  question:\"A company is consolidating five business units into one OCI tenancy. Design an operating model that separates resources, assigns access through teams, makes ownership of spend visible, and gives security staff a repeatable posture-management process. Identify one OCI capability for each part.\",\n  answer:\"(i) Resource organization: create one Compartment per business unit. (ii) Identity and access management: create function-based Groups per business unit with compartment-scoped Policies. (iii) Cost ownership: apply a mandatory 'Business-Unit' cost-tracking Tag and set an individual Budget per compartment, reviewed via Cost Analysis. (iv) Security posture management: enable Cloud Guard tenancy-wide, attach Security Zones to sensitive compartments, and review Security Advisor recommendations regularly.\",\n  explanation:\"This capstone question combines every governance pillar covered earlier: Compartments give structural isolation, IAM Groups/Policies give scoped access control, Tags/Budgets/Cost Analysis give financial accountability, and Cloud Guard/Security Zones/Security Advisor give layered security posture.\",\n  theory:{ what:\"An OCI operating model is the combined set of organizational, access, financial, and security governance patterns that let multiple business units safely share one tenancy.\", why:\"Without a standardized model, business units end up with inconsistent access, blended costs, and uneven security.\", how:\"Structure resources into per-business-unit Compartments; scope IAM Groups and Policies to those compartments; enforce cost-tracking Tags and per-compartment Budgets reviewed in Cost Analysis; layer Cloud Guard, Security Zones, and Security Advisor across the tenancy.\", example:\"Business Unit 'Finance' gets its own compartment, its own 'FinanceAdmins' group scoped to that compartment, its own Budget and tag, and a Security Zone attached \u2014 the same pattern repeats for all five units.\" },\n  quick:\"Compartment per business unit + scoped IAM groups/policies + tags/budgets/cost analysis + Cloud Guard/Security Zones/Security Advisor together form a complete multi-business-unit OCI operating model.\",\n  remember:[\"Organize = Compartments\",\"Access = IAM Groups & Policies\",\"Cost = Tags + Budget + Cost Analysis\",\"Security = Cloud Guard + Security Zones + Security Advisor\"],\n  trap:\"A common mistake is proposing a single shared compartment for all five business units with only tags for separation \u2014 tags alone cannot scope IAM access.\",\n  wrongOptionsNote:\"Naming only one security tool for part (iv) is incomplete \u2014 full security posture management requires the combination of Cloud Guard, Security Zones, and Security Advisor.\",\n  diagram:{type:\"tree\", root:\"OCI Operating Model\", children:[\"Compartments \u2014 per Business Unit\",\"IAM \u2014 Groups & scoped Policies\",\"Cost \u2014 Tags + Budget + Cost Analysis\",\"Security \u2014 Cloud Guard + Security Zones + Security Advisor\"]},\n  examAnswer:\"(i) Compartment per business unit. (ii) IAM Groups with compartment-scoped Policies. (iii) Cost-tracking Tags + per-compartment Budgets via Cost Analysis. (iv) Cloud Guard + Security Zones + Security Advisor applied tenancy-wide.\",\n  realWorld:\"Like a shopping mall with independent stores: each has its own lease (compartment), its own staff badges (IAM), its own POS reporting (cost tracking), while the mall provides shared cameras, locked service doors, and a safety consultant (security posture) for the whole building.\",\n  mcq:{ question:\"Which OCI feature set should back the (iv) Security posture management pillar of a multi-business-unit operating model?\", options:[\"IAM Policies only\",\"Cloud Guard + Security Zones + Security Advisor\",\"Budgets only\",\"Compartments only\"], correctIndex:1 }\n},\n{\n  id:22, day:3, topic:\"systemd Service Management\",\n  question:\"An operations engineer has deployed a background service on Oracle Linux. It must start immediately, start automatically after reboot, expose its recent journal messages, and allow the engineer to verify its active state. Which systemd commands satisfy these four operational needs?\",\n  answer:\"Start immediately: systemctl start <service>. Start automatically at boot: systemctl enable <service>. View recent log output: journalctl -u <service>. Check current status: systemctl status <service>.\",\n  explanation:\"systemd is the init system and service manager on most modern Linux distributions including Oracle Linux. It separates 'run now' (start) from 'run on every future boot' (enable) \u2014 the two are independent and a service can be started without being enabled, or enabled without being started immediately.\",\n  theory:{ what:\"systemd is the Linux service manager that controls starting, stopping, enabling and monitoring background services (units).\", why:\"Production services must survive reboots and be verifiable/diagnosable without manually inspecting processes.\", how:\"systemctl start/stop toggles the current running state. systemctl enable/disable controls whether the unit is launched automatically at boot. systemctl status gives a live snapshot; journalctl -u <service> pulls that unit's log stream from the systemd journal.\", example:\"After installing nginx: systemctl start nginx (runs now), systemctl enable nginx (survives reboot), systemctl status nginx (confirms active/running), journalctl -u nginx (shows recent access/error log entries).\" },\n  quick:\"start = run now, enable = run on every future boot, status = current state snapshot, journalctl -u <service> = that service's logs.\",\n  remember:[\"start \u2260 enable \u2014 running now is not the same as surviving reboot\",\"journalctl -u = per-service log stream\"],\n  trap:\"Students often assume systemctl start alone is enough for production \u2014 without systemctl enable, the service will NOT come back up after the next reboot.\",\n  wrongOptionsNote:\"Confusing systemctl restart with enable, or assuming status shows historical logs (that's journalctl's job), are common exam traps.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Run Now\", steps:[\"systemctl start <svc>\"]}, {title:\"Run at Boot\", steps:[\"systemctl enable <svc>\"]}, {title:\"Inspect\", steps:[\"systemctl status <svc>\",\"journalctl -u <svc>\"]} ]},\n  examAnswer:\"systemctl start <service> (run now), systemctl enable <service> (start at boot), journalctl -u <service> (recent logs), systemctl status <service> (current status).\",\n  realWorld:\"Like a car: turning the key (start) gets it moving right now, but setting it to auto-start on a timer (enable) is a separate setting \u2014 and the dashboard (status) is different from the trip computer's history log (journalctl).\",\n  mcq:{ question:\"Which command makes a systemd service start automatically after every future reboot?\", options:[\"systemctl start <service>\",\"systemctl enable <service>\",\"systemctl status <service>\",\"journalctl -u <service>\"], correctIndex:1 }\n},\n{\n  id:23, day:3, topic:\"Stateful vs Stateless Firewall Rules\",\n  question:\"A web server accepts HTTPS traffic and the administrator notices that response packets are allowed without creating a separate reverse-direction rule. What does this behavior reveal about OCI security-rule statefulness, and how does it affect rule design?\",\n  answer:\"OCI Security List and NSG rules are stateful by default. This means that if a connection is permitted in one direction, the return traffic is automatically allowed regardless of any outbound/inbound rule that would otherwise block it \u2014 the administrator only has to write the rule for the initiating direction, not for the reply traffic.\",\n  explanation:\"A stateful firewall tracks the connection itself (source, destination, ports, protocol) as a single session; once the initiating packet is allowed, OCI automatically permits the matching return traffic. A stateless rule, by contrast, evaluates every packet independently in both directions, which requires the administrator to write explicit mirror rules for replies.\",\n  theory:{ what:\"Stateful = the firewall tracks a connection as a session and auto-allows its return traffic. Stateless = every packet is evaluated independently with no memory of prior packets.\", why:\"Statefulness reduces rule-writing effort and the risk of accidentally blocking legitimate replies; statelessness offers finer control at the cost of needing explicit rules in both directions.\", how:\"OCI Security Lists and NSGs default to stateful rules. OCI also supports optional stateless rules (marked explicitly) for cases needing packet-level control, such as very high-throughput scenarios.\", example:\"A stateful ingress rule allowing TCP/443 from 0.0.0.0/0 automatically permits the response packets back to the client \u2014 no matching egress rule is required.\" },\n  quick:\"OCI security rules are stateful by default \u2014 permitting one direction of a connection automatically allows its return traffic, so no mirror rule is needed.\",\n  remember:[\"Stateful = tracks the session, auto-allows replies\",\"Stateless = every packet judged alone, needs rules both ways\"],\n  trap:\"A common exam trap is assuming an explicit egress rule is always required for a response to reach the client \u2014 with the (default) stateful behavior, it is not.\",\n  wrongOptionsNote:\"Claiming OCI defaults to stateless rules, or that stateful rules require double the rule-writing effort, both invert the actual behavior.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Stateful (Default)\", steps:[\"Inbound rule allows request\",\"Connection tracked as a session\",\"Return traffic auto-permitted\"]}, {title:\"Stateless\", steps:[\"Explicit inbound rule required\",\"Explicit outbound rule required\",\"No automatic return traffic\"]} ]},\n  examAnswer:\"OCI security rules default to stateful \u2014 the connection is tracked and return traffic is automatically permitted, so the administrator writes only the rule for the initiating direction.\",\n  realWorld:\"Like a receptionist who remembers your face after signing you in \u2014 you don't need a second signed pass just to walk back out; a stateless rule is like needing to sign in AND sign out separately every single time.\",\n  mcq:{ question:\"By default, OCI security rules are:\", options:[\"Stateless \u2014 every direction needs an explicit rule\",\"Stateful \u2014 return traffic for a permitted connection is automatically allowed\",\"Disabled until manually configured\",\"Stateful only for HTTPS traffic\"], correctIndex:1 }\n},\n{\n  id:24, day:3, topic:\"SSH Troubleshooting Signals\",\n  question:\"Two administrators test SSH access to Linux VMs. One connection never receives an SSH response, while another reaches the SSH service but fails with a public-key authentication message. What different failure stages do these symptoms point toward?\",\n  answer:\"A timeout means the SSH packets never reached (or a response never returned from) the SSH service at all \u2014 this points to a network-path problem: the security rules/NSG may be blocking port 22, the instance may not have a public IP or route, or the sshd service may be down. 'Permission denied (publickey)' means the network path and SSH service ARE working \u2014 the TCP connection succeeded and sshd responded \u2014 but the specific key being offered does not match an authorized key on the instance, so the fault lies in authentication (wrong key, wrong username, or the public key was never added to ~/.ssh/authorized_keys).\",\n  explanation:\"These two failure signatures sit at different layers: a timeout is a connectivity/network-layer symptom (nothing answered), while 'Permission denied (publickey)' is an application-layer authentication symptom (something answered and explicitly rejected the credential). Diagnosing which one occurred immediately narrows where to look.\",\n  theory:{ what:\"SSH connection failures fall into two broad categories: the connection never establishes (network layer) or the connection establishes but authentication fails (application layer).\", why:\"Distinguishing the two saves troubleshooting time \u2014 there is no point checking SSH keys if the real problem is a blocked port, and no point checking security rules if the TCP handshake clearly succeeded.\", how:\"A timeout means to check: security list/NSG rules for port 22, whether the instance has a public IP/is in a public subnet, and whether sshd is running. 'Permission denied (publickey)' means to check: the correct username for the image (e.g., opc for Oracle Linux, ubuntu for Ubuntu), whether the correct private key is being used, and whether the matching public key is present in the instance's authorized_keys.\", example:\"An admin gets a timeout \u2014 the NSG turns out to be missing an ingress rule for TCP/22. On a second instance, the admin gets Permission denied (publickey) because they used the wrong username (root instead of opc).\" },\n  quick:\"Timeout = network path/security-rule/service problem (nothing answered). Permission denied (publickey) = the network and SSH service are fine, but the offered key/username isn't authorized.\",\n  remember:[\"Timeout \u2192 check the path (rules, IP, sshd)\",\"Permission denied (publickey) \u2192 check the credentials (key, username)\"],\n  trap:\"Students often respond to 'Permission denied (publickey)' by re-checking security lists \u2014 but if the server actively replied with a rejection, the network path already worked; the fix is on the authentication side.\",\n  wrongOptionsNote:\"Claiming both errors point to the same root cause ignores that one is a silence (network) and the other is an explicit rejection (auth) \u2014 they require different fixes.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Timeout\", steps:[\"No response received\",\"Check Security Rules / NSG\",\"Check public IP & route\",\"Check sshd is running\"]}, {title:\"Permission denied (publickey)\", steps:[\"Server responded & rejected\",\"Check correct username\",\"Check correct private key\",\"Check authorized_keys on host\"]} ]},\n  examAnswer:\"A timeout indicates a network/connectivity fault (blocked port, missing route, or sshd down); 'Permission denied (publickey)' indicates the network and SSH service are working but the key/username offered is not authorized on the instance.\",\n  realWorld:\"A timeout is like knocking on a door and nobody answers at all \u2014 maybe you're at the wrong house. 'Permission denied (publickey)' is like someone opening the door and saying 'that's not the right key for this lock' \u2014 you're clearly at the right house, just with the wrong key.\",\n  mcq:{ question:\"An SSH attempt returns 'Permission denied (publickey)'. What does this tell you?\", options:[\"The port is blocked by a security rule\",\"The network path and SSH service are working, but the credentials are wrong\",\"The instance has no public IP\",\"The instance is powered off\"], correctIndex:1 }\n},\n{\n  id:25, day:4, topic:\"Terraform Destroy & Recreate\",\n  question:\"Terraform proposes replacing a resource instead of modifying it in place after a configuration change. What kind of attribute change causes this behavior, and why should an operations team treat the replacement as a potentially disruptive event?\",\n  answer:\"This happens when the changed attribute is an immutable ('ForceNew') attribute for that resource type \u2014 one that the underlying cloud provider does not support modifying on an existing resource. Terraform cannot patch such an attribute in place, so its only option is to destroy the existing resource and create a brand-new one with the new value. The operational risk is downtime and data loss: if the resource holds state (e.g., a compute instance's attached data, a database), that state is lost unless it was backed up or externally managed, and dependent resources referencing the old resource's ID may break until Terraform updates those references.\",\n  explanation:\"Terraform providers define, per attribute, whether a change can be applied in place or forces replacement. This is a provider-level constraint mirroring what the cloud API itself allows \u2014 Terraform isn't being arbitrarily destructive, it's respecting that the cloud resource simply cannot be modified that way.\",\n  theory:{ what:\"A 'ForceNew' (immutable) attribute is one that cannot be changed on an existing resource via the provider's API \u2014 any change to it requires the resource to be destroyed and re-created.\", why:\"Some cloud resource properties are fundamentally fixed at creation time (e.g., an instance's availability domain); Terraform surfaces this constraint through forced replacement rather than silently failing.\", how:\"terraform plan compares desired vs. current state; if a changed attribute is marked ForceNew in the provider schema, the plan shows '-/+' (destroy then create) instead of '~' (update in place).\", example:\"Changing a compute instance's Availability Domain forces destroy-and-recreate, because an instance cannot be physically moved between ADs, whereas changing its display name can be updated in place.\" },\n  quick:\"A ForceNew (immutable) attribute change can't be patched in place, so Terraform destroys and recreates the resource \u2014 risking downtime and loss of any state the old resource held.\",\n  remember:[\"ForceNew attribute changed = destroy + recreate, not update\",\"Risk = downtime + potential data loss on the old resource\"],\n  trap:\"Assuming terraform apply always updates resources safely in place is a common exam trap \u2014 always read the plan output ('-/+' vs '~') before applying, especially for stateful resources.\",\n  wrongOptionsNote:\"Blaming this behavior on a Terraform bug is incorrect \u2014 it reflects a genuine limitation of the underlying cloud provider's API, which Terraform is accurately surfacing.\",\n  diagram:{type:\"linear\", steps:[\"Attribute changed in config\",\"Provider schema marks it ForceNew\",\"terraform plan shows -/+ (destroy, create)\",\"Old resource destroyed\",\"New resource created with new value\"]},\n  examAnswer:\"The changed attribute is an immutable (ForceNew) property that the cloud provider cannot modify in place, so Terraform must destroy and recreate the resource \u2014 risking downtime and loss of any state on the old resource.\",\n  realWorld:\"Like changing the foundation material of a house \u2014 you can repaint a wall in place (update), but you can't change the concrete foundation without demolishing and rebuilding the house (destroy + recreate).\",\n  mcq:{ question:\"Why does terraform plan sometimes show a resource being destroyed and recreated for a single attribute change?\", options:[\"Terraform always recreates resources on any change\",\"The attribute is immutable (ForceNew) and cannot be updated in place\",\"The Terraform state file is corrupted\",\"The provider does not support that resource type\"], correctIndex:1 }\n},\n{\n  id:26, day:4, topic:\"Terraform Variables, Outputs & Modules\",\n  question:\"A Terraform project is being turned into a reusable template for several environments. Explain how input values, returned values, and reusable groups of resources can be represented using Terraform variables, outputs, and modules.\",\n  answer:\"A Variable is a named input that lets the same configuration be parameterized for different environments (e.g., instance shape, compartment OCID) without editing the code itself. An Output exposes a value computed or created by the configuration (e.g., a resource's OCID or public IP) so it can be read by the operator or consumed by another configuration. A Module is a reusable, self-contained package of Terraform configuration (its own variables, resources, and outputs) that can be called multiple times with different inputs, avoiding copy-pasted code for repeated infrastructure patterns.\",\n  explanation:\"Together these three constructs turn a one-off script into reusable infrastructure code: Variables make it configurable, Outputs make its results consumable, and Modules make the whole pattern repeatable across environments or projects.\",\n  theory:{ what:\"Variable = a typed input parameter; Output = an exported result value; Module = a callable, packaged set of resources with its own variables and outputs.\", why:\"Hardcoding values means duplicating and editing code for every environment; these constructs let one configuration be parameterized, composed, and reused instead.\", how:\"Variables are declared with variable blocks and supplied via .tfvars, CLI flags, or environment variables. Outputs are declared with output blocks and read via terraform output or referenced by a calling module. Modules are called with a module block pointing at a source directory/registry, passing variables in and reading outputs back.\", example:\"A 'vcn' module accepts a cidr_block variable and outputs the created vcn_id. It's called twice \u2014 once for a Dev VCN, once for a Prod VCN \u2014 with different CIDR variables, and each call's vcn_id output feeds into that environment's subnet module.\" },\n  quick:\"Variable = configurable input, Output = exposed result, Module = a reusable, callable package of resources \u2014 together they make configurations parameterizable and reusable.\",\n  remember:[\"Variable = IN\",\"Output = OUT\",\"Module = a reusable Terraform 'function'\"],\n  trap:\"Students sometimes think a module is just a folder of code with no distinct interface \u2014 a module's real value is that its own variables and outputs form a defined, reusable contract.\",\n  wrongOptionsNote:\"Claiming outputs are only for debugging is incomplete \u2014 outputs are also how a parent configuration consumes values from a called module.\",\n  diagram:{type:\"linear\", steps:[\"Variables \u2014 parameterize input\",\"Resources \u2014 created using those variables\",\"Outputs \u2014 expose resulting values\",\"Module \u2014 packages variables + resources + outputs for reuse\"]},\n  examAnswer:\"A Variable parameterizes input, an Output exposes a resulting value, and a Module packages reusable variables/resources/outputs so the same infrastructure pattern can be called repeatedly with different inputs.\",\n  realWorld:\"Like a recipe card (module) with ingredient-quantity blanks you fill in per meal (variables) and a finished-dish description at the bottom you can reference for the next recipe (outputs).\",\n  mcq:{ question:\"What does a Terraform Output primarily provide?\", options:[\"A parameterized input value\",\"An exported value from the configuration for reuse or inspection\",\"A reusable package of resources\",\"A record of state-file changes\"], correctIndex:1 }\n},\n{\n  id:27, day:4, topic:\"Terraform Provisioning Workflow\",\n  question:\"An engineer has finished writing Terraform configuration and wants to validate it, preview changes, create the infrastructure, and later remove it. Put the normal Terraform workflow commands in the appropriate sequence and explain their purpose.\",\n  answer:\"terraform init \u2014 initializes the working directory, downloads the required provider plugins and sets up the backend. terraform plan \u2014 compares the desired configuration against current state and shows what will be added, changed or destroyed, without making any changes. terraform apply \u2014 executes the plan and actually creates/updates/destroys the real infrastructure. terraform destroy \u2014 tears down all resources managed by the configuration.\",\n  explanation:\"These four commands form the standard lifecycle: init prepares the workspace, plan previews changes safely, apply commits them, and destroy tears everything down when the infrastructure is no longer needed.\",\n  theory:{ what:\"init/plan/apply/destroy are Terraform's core workflow commands covering setup, preview, execution, and teardown.\", why:\"Separating preview (plan) from execution (apply) lets an operator review exactly what will change before committing, avoiding accidental destructive changes.\", how:\"init must run first in any new/cloned configuration. plan is run (and reviewed) before every apply. apply prompts for confirmation (or accepts -auto-approve) before making real changes. destroy is run deliberately when resources should be removed.\", example:\"A new team member clones the repo, runs terraform init to fetch the OCI provider, terraform plan to preview a new compartment and VCN, terraform apply to create them, and later terraform destroy to tear the environment down after a demo.\" },\n  quick:\"init = set up the workspace, plan = preview changes, apply = execute changes, destroy = tear down all managed resources.\",\n  remember:[\"init \u2192 plan \u2192 apply\", \"destroy = full teardown\"],\n  trap:\"Skipping terraform plan and going straight to apply is a common exam trap answer \u2014 the workflow is designed around reviewing the plan output before committing changes.\",\n  wrongOptionsNote:\"Confusing terraform validate (syntax-only check) with terraform plan (full state comparison) is a frequent wrong answer \u2014 validate does not compare against real infrastructure state.\",\n  diagram:{type:\"linear\", steps:[\"terraform init \u2014 set up providers/backend\",\"terraform plan \u2014 preview changes\",\"terraform apply \u2014 execute changes\",\"terraform destroy \u2014 tear down resources\"]},\n  examAnswer:\"terraform init (setup), terraform plan (preview), terraform apply (execute), terraform destroy (teardown) \u2014 the standard four-command Terraform provisioning workflow.\",\n  realWorld:\"Like building a house: init is ordering your tools and materials, plan is reviewing the blueprint before construction, apply is actually building it, and destroy is demolishing it when it's no longer needed.\",\n  mcq:{ question:\"Which Terraform command previews what will change without making any actual changes?\", options:[\"terraform init\",\"terraform plan\",\"terraform apply\",\"terraform destroy\"], correctIndex:1 }\n},\n{\n  id:28, day:4, topic:\"OCI Resource Manager Stacks\",\n  question:\"A cloud team wants Terraform execution, job history, source configuration, and state management to be handled as an OCI-managed service rather than from individual laptops. What Resource Manager construct should they create, and what operational benefits does it provide?\",\n  answer:\"A Resource Manager stack is an OCI-managed representation of a Terraform configuration (its .tf files, variables and state) that OCI stores and runs on the platform's behalf, rather than on a local machine. Two advantages over running Terraform from a laptop: (1) the Terraform state file is stored centrally and securely by OCI instead of on an individual's disk, removing the risk of a lost/corrupted local state file and enabling safe team collaboration; and (2) OCI handles provider installation, execution environment, and job history/logging automatically, so there's no dependency on any one engineer's local Terraform version or credentials being correctly configured.\",\n  explanation:\"Resource Manager turns Terraform into a managed, team-shared OCI service rather than a per-developer CLI tool, addressing the classic pain points of local Terraform usage: state file safety, consistent execution environment, and auditable job history.\",\n  theory:{ what:\"An OCI Resource Manager stack packages a Terraform configuration and its associated state, and runs Terraform jobs (plan/apply/destroy) inside OCI rather than locally.\", why:\"Local Terraform runs risk inconsistent versions, lost/corrupted state files, and no shared audit trail \u2014 Resource Manager centralizes and standardizes execution.\", how:\"A stack is created from a source (a .zip upload, a Git repository, or a template), variables are supplied through the console, and Jobs (Plan / Apply / Destroy) are run against that stack, each producing a viewable log and outcome.\", example:\"A team creates a stack from their Git repo's Terraform config; any team member can trigger a Plan job to review changes and an Apply job to execute them, with full job history visible to everyone rather than living only on one laptop.\" },\n  quick:\"A Resource Manager stack is OCI's managed home for a Terraform config + state; it gives centrally-stored state and consistent, auditable execution instead of relying on one person's laptop.\",\n  remember:[\"Stack = Terraform config + state, managed by OCI\",\"Local Terraform risk: lost state, inconsistent versions\"],\n  trap:\"Students sometimes describe a stack as just 'a copy of the Terraform files' \u2014 its real value is that OCI also manages the state file and job execution/history centrally.\",\n  wrongOptionsNote:\"Claiming Resource Manager eliminates the need for a Terraform configuration entirely is wrong \u2014 a stack is still built from standard Terraform (.tf) files.\",\n  diagram:{type:\"linear\", steps:[\"Terraform config (source: zip / Git / template)\",\"Uploaded as a Resource Manager Stack\",\"Jobs run: Plan / Apply / Destroy\",\"State stored centrally by OCI\"]},\n  examAnswer:\"A Resource Manager stack is OCI's managed home for a Terraform configuration and its state. Advantages over a laptop: centrally stored, safe state (no lost/corrupted local file) and consistent, auditable job execution shared across the team.\",\n  realWorld:\"Like moving a shared team spreadsheet from someone's personal laptop to a shared cloud drive \u2014 everyone works from the same authoritative copy with a visible history, instead of risking one person's machine being the single point of failure.\",\n  mcq:{ question:\"What is one key advantage of using an OCI Resource Manager stack over running Terraform locally?\", options:[\"It removes the need to write Terraform configuration files\",\"The Terraform state is stored centrally by OCI instead of on an individual laptop\",\"It automatically fixes any Terraform syntax errors\",\"It replaces the need for IAM policies\"], correctIndex:1 }\n},\n{\n  id:29, day:4, topic:\"Resource Manager Drift Detection\",\n  question:\"An administrator manually changes an OCI resource that is supposed to be managed by Terraform. Later, the team wants to identify differences between the declared infrastructure and the actual environment before reconciling them. Which Resource Manager capability should they run?\",\n  answer:\"Drift Detection. It compares the actual, current configuration of the deployed resources against what Terraform's state file believes they should be, and reports any differences (drift) \u2014 for example, a resource that was manually modified in the OCI Console outside of Terraform.\",\n  explanation:\"Drift happens whenever infrastructure is changed outside of Terraform's own apply cycle (a manual console edit, another automation tool, or an out-of-band API call). Drift Detection surfaces that gap so the team can decide whether to update the Terraform configuration to match reality or re-apply Terraform to correct the resource back to the declared state.\",\n  theory:{ what:\"Drift is any mismatch between a resource's real, current configuration and what Terraform's state file records for it. Drift Detection is the Resource Manager job that finds and reports this mismatch.\", why:\"Undetected drift means Terraform's plan/apply decisions are based on stale assumptions, which can cause unexpected changes or failed applies later.\", how:\"Running a Drift Detection job on a stack queries the actual resource state from OCI and diffs it against the stored Terraform state, listing every attribute that no longer matches.\", example:\"An engineer manually resizes a compute instance's shape in the Console for an urgent fix. The next Drift Detection run on that stack flags the shape attribute as drifted from what Terraform's state expects.\" },\n  quick:\"Drift Detection is the Resource Manager job that compares real resource configuration against Terraform's state and reports any mismatches caused by out-of-band changes.\",\n  remember:[\"Drift = real world \u2260 Terraform state\",\"Drift Detection = the job that finds that gap\"],\n  trap:\"Students sometimes confuse Drift Detection with terraform plan \u2014 plan compares desired configuration vs. state to show future changes; Drift Detection specifically checks whether the real resource still matches the recorded state at all.\",\n  wrongOptionsNote:\"Assuming drift is automatically corrected by Resource Manager is wrong \u2014 Drift Detection only reports the mismatch; fixing it still requires a deliberate plan/apply or a state update.\",\n  diagram:{type:\"linear\", steps:[\"Resource manually changed outside Terraform\",\"Real configuration \u2260 Terraform state\",\"Drift Detection job run on the Stack\",\"Mismatched attributes reported\"]},\n  examAnswer:\"Drift Detection is the Resource Manager feature that compares deployed resources' actual configuration against the Terraform state and reports any divergence caused by changes made outside Terraform.\",\n  realWorld:\"Like a home inventory audit that compares what's actually in the house against what's listed on the insurance policy \u2014 it flags the mismatch, but someone still has to decide whether to update the policy or put the missing item back.\",\n  mcq:{ question:\"Which Resource Manager feature reports when a resource's real configuration no longer matches the Terraform state?\", options:[\"terraform plan\",\"Drift Detection\",\"Job History\",\"Stack Variables\"], correctIndex:1 }\n},\n{\n  id:30, day:5, topic:\"Security List vs Network Security Group\",\n  question:\"A three-layer application has web servers whose network permissions should remain easy to associate with individual VNICs as the servers move between subnets. The architect is choosing between subnet-attached rules and VNIC-associated rules. Which OCI controls should be compared, and why would one be preferable for this design?\",\n  answer:\"A Security List applies its rules to every VNIC in every subnet it's attached to \u2014 its scope is the subnet. A Network Security Group (NSG) applies its rules directly to specific VNICs/resources regardless of which subnet they sit in \u2014 its scope is the resource(s) you explicitly add to it. For a three-tier application, NSGs are preferable: you can create one NSG per tier (web, app, database) and write rules like 'allow app-tier NSG to reach db-tier NSG on port 1521', which is far more precise than subnet-wide rules and doesn't need to change if resources move between subnets.\",\n  explanation:\"Security Lists were OCI's original mechanism and remain simple for uniform, subnet-wide policy. NSGs were introduced for exactly the multi-tier scenario: they let rules reference other NSGs by name/ID instead of by CIDR block, making tier-to-tier access control readable and resilient to IP changes.\",\n  theory:{ what:\"A Security List is a set of stateful/stateless rules attached to one or more subnets, applying to every VNIC in that subnet. An NSG is a set of rules attached directly to specific VNICs/resources, independent of subnet.\", why:\"Security Lists give simple, uniform subnet-wide policy; NSGs give precise, resource-level and tier-to-tier policy that scales better for multi-tier or micro-segmented architectures.\", how:\"A Security List is attached when a subnet is created/edited and its rules apply to everything in that subnet. An NSG is created independently, resources are added as members, and rules can reference another NSG as the source/destination instead of a CIDR.\", example:\"A Security List on the 'app-subnet' allows all instances in that subnet to reach the internet. Separately, an NSG named 'db-tier-nsg' only allows inbound traffic from the 'app-tier-nsg', regardless of which subnet either tier's instances are actually placed in.\" },\n  quick:\"Security List = subnet-wide rules. NSG = resource-level rules that can reference other NSGs \u2014 preferred for three-tier apps because it enables precise tier-to-tier rules.\",\n  remember:[\"Security List = attached to a SUBNET\",\"NSG = attached to a RESOURCE (VNIC)\",\"3-tier app \u2192 prefer NSGs\"],\n  trap:\"Students often assume Security Lists and NSGs are mutually exclusive \u2014 OCI actually evaluates both together; a packet is allowed only if permitted by the applicable Security List(s) AND NSG(s).\",\n  wrongOptionsNote:\"Claiming Security Lists can reference another Security List as a source (the way NSGs can reference another NSG) is incorrect \u2014 that resource-to-resource rule capability is specific to NSGs.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Security List\", steps:[\"Attached to a Subnet\",\"Applies to every VNIC in it\",\"Best for uniform subnet policy\"]}, {title:\"NSG\", steps:[\"Attached to specific VNICs/resources\",\"Rules can reference another NSG\",\"Best for tier-to-tier, 3-tier apps\"]} ]},\n  examAnswer:\"A Security List applies rules at the subnet level; an NSG applies rules at the resource/VNIC level and can reference other NSGs. NSGs are preferred for a three-tier application because they allow precise, tier-to-tier rules independent of subnet placement.\",\n  realWorld:\"A Security List is like a building-wide rule ('everyone on this floor can use the lobby'); an NSG is like an individual keycard group ('only Finance-team badges open the Finance server room'), regardless of which floor those people sit on.\",\n  mcq:{ question:\"Why would an NSG be preferred over a Security List for a three-tier application?\", options:[\"NSGs are cheaper than Security Lists\",\"NSGs allow rules scoped to specific resources and can reference other NSGs directly, enabling precise tier-to-tier control\",\"Security Lists cannot be used with VCNs\",\"NSGs remove the need for any routing configuration\"], correctIndex:1 }\n},\n{\n  id:31, day:5, topic:\"Private Subnet Connectivity Troubleshooting\",\n  question:\"A private application tier can resolve the database name and the database port is allowed, but the application still cannot establish a connection to the database. In what order should an OCI engineer inspect the route path, network security controls, and endpoint configuration to isolate the failure?\",\n  answer:\"(1) Route Table \u2014 confirm the private subnet's route table has a route (typically via a Service Gateway) toward the Autonomous Database/OCI services, since Autonomous Database is accessed as an OCI public service endpoint even from a private subnet. (2) Service Gateway \u2014 confirm a Service Gateway exists in the VCN and is correctly targeted by that route, since it's the component that lets private-subnet resources reach OCI services (including Autonomous Database) without needing a public IP or NAT Gateway. (3) NSG (in addition to the already-checked Security List) \u2014 confirm there isn't a separate NSG attached to the instances that is blocking the traffic, since Security Lists and NSGs are evaluated together and a permissive Security List does not override a restrictive NSG.\",\n  explanation:\"Since the security rules were already confirmed to permit the port, the fault most likely lies upstream of rule evaluation \u2014 in routing (can the traffic even get there) \u2014 or in a second rule layer the team didn't check (NSGs, which apply alongside Security Lists). Checking routing before assuming a rules problem reflects the OSI-layer order of troubleshooting: path first, then policy.\",\n  theory:{ what:\"Connectivity from a private subnet to an OCI public service like Autonomous Database depends on routing (via a Service Gateway) as well as security rules.\", why:\"A private subnet has no direct internet route and no public IPs; without a Service Gateway route, security rules being 'correct' is irrelevant because the traffic never has a path to leave the subnet toward the service.\", how:\"Check the subnet's Route Table for a rule targeting the Service Gateway for the 'All OCI Services in Region' destination. Confirm the Service Gateway itself exists and is attached to the VCN. Then check for any additional NSG (beyond the Security List already confirmed) that might independently block the traffic.\", example:\"A private subnet's route table has no entry for the Service Gateway \u2014 even though the Security List correctly allows port 1522, traffic to Autonomous Database has no route out of the subnet and silently fails.\" },\n  quick:\"Check, in order: (1) Route Table has a Service Gateway route, (2) the Service Gateway itself is configured, (3) no additional NSG is blocking the traffic that the Security List alone wouldn't catch.\",\n  remember:[\"Private subnet \u2192 OCI service = needs a Service Gateway route\",\"Security List permit \u2260 automatically reachable \u2014 check routing and NSGs too\"],\n  trap:\"Assuming 'the security rules are correct' means security is fully cleared is a trap \u2014 Security Lists and NSGs are evaluated together, so a separate NSG can still silently block traffic.\",\n  wrongOptionsNote:\"Suggesting a NAT Gateway is required is a common wrong answer \u2014 NAT Gateway is for reaching the public internet; reaching OCI public services like Autonomous Database from a private subnet is the Service Gateway's job.\",\n  diagram:{type:\"linear\", steps:[\"1. Check Route Table for Service Gateway route\",\"2. Confirm Service Gateway is attached to the VCN\",\"3. Check for a blocking NSG alongside the Security List\"]},\n  examAnswer:\"Check, in order: the subnet's route table for a Service Gateway route to OCI services, that the Service Gateway is properly configured in the VCN, and whether an NSG (separate from the already-checked Security List) is blocking the traffic.\",\n  realWorld:\"Even with a security guard who agrees to let you into a building (rules OK), if there's no road connecting your location to the building at all (no route), you still can't get there \u2014 check the road before re-questioning the guard.\",\n  mcq:{ question:\"Instances in a private subnet cannot reach an Autonomous Database despite correct security rules. What should be checked first?\", options:[\"Whether the instance has a public IP\",\"Whether the Route Table has a Service Gateway route to OCI services\",\"Whether a NAT Gateway is attached\",\"Whether the database is in the same compartment\"], correctIndex:1 }\n},\n{\n  id:32, day:5, topic:\"Block Volume Attachment\",\n  question:\"An administrator is adding persistent application storage to a Compute VM. After selecting the volume and its attachment, what operating-system preparation is needed before the new storage can appear as a usable mounted filesystem?\",\n  answer:\"When attaching a block volume, you must specify: (1) the attachment type (e.g., paravirtualized or iSCSI) and (2) the target instance the volume is being attached to. To make the attached volume usable inside the operating system, the administrator must then: connect to the volume from within the OS (for iSCSI attachments, running the provided iscsiadm login commands \u2014 paravirtualized volumes appear automatically as a block device), partition and format the new block device with a filesystem, and mount it to a directory (optionally adding an entry to /etc/fstab for it to persist across reboots).\",\n  explanation:\"Attaching a block volume in the OCI Console only makes it visible to the instance at the infrastructure level \u2014 it does not automatically become usable storage inside the guest OS. The administrator must still perform the OS-level steps (connect/discover, format, mount) before applications can read or write to it.\",\n  theory:{ what:\"Block Volume attachment connects a network-based block storage volume to a compute instance, using either the paravirtualized or iSCSI attachment type.\", why:\"Separating volume creation/attachment (infrastructure layer) from filesystem setup (OS layer) mirrors how physical disks work \u2014 plugging in a drive doesn't automatically format or mount it.\", how:\"Specify attachment type and target instance when attaching. For iSCSI, run the iscsiadm commands OCI provides to log in to the volume from the OS. Then use tools like fdisk/parted to partition, mkfs to format, and mount (plus an /etc/fstab entry) to make it persistently accessible.\", example:\"A 200GB block volume is attached to a Linux instance as paravirtualized; the admin then runs fdisk to create a partition, mkfs.ext4 to format it, and mount /dev/oracleoci/oraclevdb1 to /data before the application can use it.\" },\n  quick:\"Attachment requires: attachment type + target instance. Usability requires: connect/discover the device, partition & format it, then mount it (and add to /etc/fstab for persistence).\",\n  remember:[\"Attach \u2260 Usable \u2014 attaching only makes the disk visible\",\"Usable = connect \u2192 format \u2192 mount\"],\n  trap:\"Students often assume attaching a volume in the Console is the final step \u2014 without partitioning, formatting and mounting inside the OS, the volume is invisible to applications.\",\n  wrongOptionsNote:\"Assuming an attached volume is automatically formatted with a filesystem is incorrect \u2014 a newly attached block volume is raw/unformatted until the administrator formats it.\",\n  diagram:{type:\"linear\", steps:[\"Specify attachment type & target instance\",\"Attach volume (visible at infra level only)\",\"Connect/discover device in the OS (iSCSI login if needed)\",\"Partition & format with a filesystem\",\"Mount (+ /etc/fstab entry) \u2014 now usable\"]},\n  examAnswer:\"Attaching requires specifying the attachment type (paravirtualized/iSCSI) and the target instance. Making it usable requires connecting/discovering the device in the OS, partitioning and formatting it, then mounting it (with an /etc/fstab entry for persistence).\",\n  realWorld:\"Plugging in an external hard drive to a laptop (attach) doesn't automatically give it a drive letter and folders \u2014 you may still need to initialize, format and open it before you can save files to it.\",\n  mcq:{ question:\"After attaching a block volume to an instance, what must still be done before an application can use it?\", options:[\"Nothing \u2014 attaching makes it immediately usable\",\"Partition, format and mount the volume inside the OS\",\"Delete and recreate the volume\",\"Restart the entire instance twice\"], correctIndex:1 }\n},\n{\n  id:33, day:5, topic:\"Three-Tier VCN Design\",\n  question:\"An online service has a public-facing web tier, a private application tier, and a database tier that should not accept direct internet traffic. Sketch an OCI VCN layout for the three tiers and choose the appropriate gateway path for each tier.\",\n  answer:\"Create three subnets: (1) a Public web-tier subnet, routing to an Internet Gateway so it can serve inbound client traffic and reach the internet; (2) a Private app-tier subnet, routing to a NAT Gateway for any outbound internet access it needs (e.g., pulling updates) while remaining unreachable directly from the internet; (3) a Private database-tier subnet, routing to a Service Gateway so it can reach OCI public services (like Object Storage or Autonomous Database backups) privately, without needing internet access at all. NSGs are then used between tiers (web\u2192app, app\u2192db) to enforce that only the tier above can reach the tier below.\",\n  explanation:\"This design follows the standard defense-in-depth pattern: only the web tier is directly internet-facing; the app tier can initiate outbound calls but is never directly reachable from the internet; and the database tier has the smallest exposure of all, needing only OCI-service reachability, not general internet access.\",\n  theory:{ what:\"A three-tier VCN separates web, application and database components into distinct subnets, each with only the network exposure it actually needs.\", why:\"Minimizing each tier's exposure limits the blast radius if any single tier is compromised \u2014 a breached web instance still can't directly reach the database subnet without going through the app tier's rules.\", how:\"Public subnet + Internet Gateway route for the web tier. Private subnet + NAT Gateway route for the app tier's outbound-only needs. Private subnet + Service Gateway route for the database tier's access to OCI services. NSGs are layered on top to restrict which tier can talk to which.\", example:\"A load balancer and web instances sit in the public subnet; application servers sit in a private subnet routed via NAT Gateway; an Autonomous Database sits in a private subnet routed via Service Gateway for backups to Object Storage.\" },\n  quick:\"Web tier: public subnet \u2192 Internet Gateway. App tier: private subnet \u2192 NAT Gateway. DB tier: private subnet \u2192 Service Gateway.\",\n  remember:[\"Web = Public + Internet Gateway\",\"App = Private + NAT Gateway\",\"DB = Private + Service Gateway\"],\n  trap:\"A common exam trap is routing the database subnet through a NAT Gateway 'just in case' \u2014 if the database only needs OCI service access, the Service Gateway is the correct, more restrictive choice.\",\n  wrongOptionsNote:\"Placing the app or database tier in a public subnet defeats the purpose of tiered isolation and is a frequent wrong design choice.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Web Tier\", steps:[\"Public Subnet\",\"Internet Gateway\"]}, {title:\"App Tier\", steps:[\"Private Subnet\",\"NAT Gateway\"]}, {title:\"DB Tier\", steps:[\"Private Subnet\",\"Service Gateway\"]} ]},\n  examAnswer:\"Web tier: public subnet routed via Internet Gateway. App tier: private subnet routed via NAT Gateway for outbound access. Database tier: private subnet routed via Service Gateway for OCI-service access only.\",\n  realWorld:\"Like a building's floors: the lobby (web) is open to the public street door; the offices (app) can step out through a staff-only exit when needed but aren't visible from the street; the server room (db) only connects to the building's internal service corridor.\",\n  mcq:{ question:\"Which gateway should a private database-tier subnet route through if it only needs to reach OCI public services like Object Storage?\", options:[\"Internet Gateway\",\"NAT Gateway\",\"Service Gateway\",\"Dynamic Routing Gateway\"], correctIndex:2 }\n},\n{\n  id:34, day:5, topic:\"cloud-init & User Data\",\n  question:\"A DevOps team wants a newly launched Oracle Linux VM to install a web package and start its service automatically without a person logging in after provisioning. Which Compute startup mechanism should they use, and what should its cloud-config accomplish?\",\n  answer:\"cloud-init is the industry-standard boot-time initialization tool that most Linux cloud images (including Oracle Linux's OCI images) run automatically on their very first boot. It reads the 'user data' supplied when the instance was launched and executes the instructions it contains \u2014 such as installing packages, writing files, running commands, or creating users \u2014 before the instance is considered fully ready. To install and enable a web server, the user data would be a cloud-config (YAML, beginning with #cloud-config) specifying the package to install (e.g., httpd) under a packages list, and a runcmd section to enable and start the service, e.g., systemctl enable httpd and systemctl start httpd.\",\n  explanation:\"cloud-init removes the need to manually SSH in and configure every new instance \u2014 the same user data can be reused to launch any number of identically-configured instances, which is essential for reproducible, automatable provisioning (and pairs naturally with Terraform-driven provisioning).\",\n  theory:{ what:\"cloud-init is a boot-time agent baked into cloud OS images that consumes 'user data' supplied at launch to perform first-boot configuration automatically.\", why:\"It enables reproducible, hands-off configuration of every new instance without manual post-launch steps, which is essential at scale and for automation pipelines.\", how:\"User data is passed at instance launch (via Console, CLI, or Terraform's user_data attribute), typically as a #cloud-config YAML document listing packages to install, files to write, and runcmd commands to execute on first boot.\", example:\"user_data (base64-encoded) contains: #cloud-config, packages: [httpd], runcmd: [systemctl enable httpd, systemctl start httpd] \u2014 the instance boots with Apache already installed, enabled and running, with no manual login required.\" },\n  quick:\"cloud-init runs automatically at first boot and executes the supplied user data (a #cloud-config file) to install packages and run commands \u2014 e.g., installing and enabling a web server with no manual login needed.\",\n  remember:[\"cloud-init = first-boot automation engine\",\"user data = the instructions it executes\"],\n  trap:\"Students sometimes think user data re-runs on every boot \u2014 by default cloud-init user data executes only once, on the instance's first boot.\",\n  wrongOptionsNote:\"Assuming user data requires the administrator to manually trigger it after launch is incorrect \u2014 cloud-init runs it automatically as part of the boot sequence.\",\n  diagram:{type:\"linear\", steps:[\"Instance launched with user data (#cloud-config)\",\"cloud-init runs automatically at first boot\",\"Packages installed (e.g., httpd)\",\"runcmd executes (enable & start service)\",\"Web server ready \u2014 no manual login needed\"]},\n  examAnswer:\"cloud-init is the first-boot automation tool that executes the supplied user data. A #cloud-config with a packages list (httpd) and a runcmd section (systemctl enable httpd, systemctl start httpd) installs and enables a web server automatically at launch.\",\n  realWorld:\"Like a hotel room that's already set up exactly the way you requested before you even check in \u2014 towels, temperature, minibar stocked \u2014 because the setup instructions were submitted in advance and executed automatically.\",\n  mcq:{ question:\"When does cloud-init typically execute the user data supplied at instance launch?\", options:[\"On every reboot of the instance\",\"Only when manually triggered by SSH login\",\"Automatically, on the instance's first boot\",\"Only if Terraform is used to launch the instance\"], correctIndex:2 }\n},\n{\n  id:35, day:5, topic:\"Block Volume Not Appearing After Attach\",\n  question:\"A storage administrator attaches a block volume successfully, but the application cannot see it with normal filesystem commands. What operating-system steps are required before it becomes a persistent mounted filesystem, and what problem can arise if a network-backed filesystem mount lacks the appropriate boot dependency option?\",\n  answer:\"The two missing steps are: (1) the volume has not been partitioned and formatted with a filesystem (df -h only shows mounted filesystems, and an unformatted raw block device has none), and (2) the volume has not been mounted to a directory. Writing an /etc/fstab entry for a network-attached block volume without the _netdev option risks the instance hanging or failing to boot: without _netdev, the OS tries to mount the volume before networking is initialized, and since block volumes are network-attached storage, that mount attempt fails or times out, potentially blocking the rest of the boot sequence.\",\n  explanation:\"df -h only lists currently mounted filesystems \u2014 an attached-but-unformatted-and-unmounted volume is invisible to it even though the OS can see the raw block device. The _netdev flag exists specifically because OCI block volumes are iSCSI/network-attached, not locally attached disks, so they depend on network availability before they can be mounted at boot.\",\n  theory:{ what:\"df -h shows only mounted filesystems, not raw attached block devices. _netdev is an /etc/fstab mount option that tells the OS a device requires networking before it can be mounted.\", why:\"A newly attached block volume is raw and unformatted by default and won't show in df -h until formatted and mounted; and because block volumes are network-attached, the boot process must wait for networking before attempting to mount them.\", how:\"After attaching, partition (fdisk/parted), format (mkfs), then mount the volume \u2014 it now appears in df -h. In /etc/fstab, add the _netdev option (and often nofail) to the volume's entry so the boot sequence waits for network readiness and doesn't hang if the volume is temporarily unavailable.\", example:\"An admin attaches and formats a volume but forgets to mount it \u2014 df -h shows nothing. After mounting, it appears. Later, an /etc/fstab entry without _netdev causes the instance to hang at boot after a reboot, because the OS tries to mount the volume before the network stack (and thus the iSCSI connection) is up.\" },\n  quick:\"Missing steps: format the volume, then mount it. Missing _netdev in /etc/fstab risks the instance hanging/failing to boot, since block volumes need networking before they can mount.\",\n  remember:[\"df -h only shows MOUNTED filesystems\",\"No _netdev = boot may hang (mount attempted before networking is up)\"],\n  trap:\"Students often assume adding an fstab entry alone guarantees persistence \u2014 without _netdev (and ideally nofail), a network-attached volume in fstab can actually break the next reboot instead of helping it.\",\n  wrongOptionsNote:\"Assuming the volume simply needs to be reattached is a common wrong answer \u2014 reattachment isn't the issue; formatting and mounting are the missing OS-level steps.\",\n  diagram:{type:\"linear\", steps:[\"Volume attached (raw, unformatted)\",\"Missing: partition & format\",\"Missing: mount to a directory\",\"Now visible in df -h\",\"fstab entry without _netdev risks boot hang\"]},\n  examAnswer:\"The volume still needs to be partitioned/formatted and then mounted \u2014 only then will it appear in df -h. An /etc/fstab entry without _netdev risks the instance hanging or failing to boot, because the OS attempts to mount the network-attached volume before networking is available.\",\n  realWorld:\"Like buying a new bookshelf (attaching) but never assembling it or putting it in a room (format/mount) \u2014 it won't show up as furniture in your home inventory until it does; and bolting it to the wall before the wall is even built (_netdev missing) can jam the whole move-in.\",\n  mcq:{ question:\"Why might a freshly attached block volume not appear under df -h?\", options:[\"It needs to be detached and reattached\",\"It has not yet been formatted and mounted\",\"df -h only works for boot volumes\",\"The instance needs to be terminated and recreated\"], correctIndex:1 }\n},\n{\n  id:36, day:5, topic:\"Instance Console Connection\",\n  question:\"A Compute VM has stopped responding to SSH and the administrator cannot reach the operating system over the network. Which OCI out-of-band access mechanism can be used to troubleshoot the machine without relying on SSH?\",\n  answer:\"Use an Instance Console Connection, which provides a serial-console-style connection to the instance directly through the OCI Console (or CLI), independent of the instance's network/VCN configuration and SSH. Because it connects at the virtual serial port level rather than over the network, it works even when networking, security rules, or sshd itself are the reason SSH is failing, letting the administrator log in locally and diagnose or fix the underlying issue.\",\n  explanation:\"SSH depends on a working network path, correct security rules, and a running sshd \u2014 if any of those is the actual problem, SSH itself cannot be used to diagnose it. The Instance Console Connection bypasses the network stack entirely, giving direct access to the instance's console the way a physical keyboard/monitor would on-premises.\",\n  theory:{ what:\"An Instance Console Connection is an OCI feature providing serial-console access to a compute instance, bypassing the network entirely.\", why:\"When the network path, security rules, or the SSH service itself is broken, SSH cannot be used to fix the problem \u2014 a non-network access path is required.\", how:\"Create a Console Connection for the instance from the Console/CLI, which generates a connection string used with a local SSH client to reach the serial console (not the instance's network) via an OCI proxy \u2014 from there, you're logged into the instance's local console as if physically present.\", example:\"An admin misconfigures the NSG and locks out all SSH access. Using the Instance Console Connection, they log in via the serial console (unaffected by the NSG) and fix the NSG rule from inside the instance.\" },\n  quick:\"Use an Instance Console Connection \u2014 a serial-console-style access path that bypasses the network entirely, so it works even when SSH itself is broken due to networking or security rules.\",\n  remember:[\"Console Connection = access that bypasses the network\",\"Useful exactly when SSH itself is the problem\"],\n  trap:\"Students sometimes assume console access still requires SSH to be working \u2014 the whole point of the Instance Console Connection is that it works independently of network/SSH availability.\",\n  wrongOptionsNote:\"Suggesting the instance must simply be rebooted or terminated skips a valid non-destructive diagnostic option that OCI specifically provides for this scenario.\",\n  diagram:{type:\"linear\", steps:[\"SSH fails (network/rules/sshd issue)\",\"Create Instance Console Connection\",\"Access serial console via OCI proxy (bypasses network)\",\"Diagnose/fix issue from inside the instance\"]},\n  examAnswer:\"Use an OCI Instance Console Connection, which gives serial-console access to the instance independent of its network configuration \u2014 it works even when SSH itself is failing due to networking, security-rule, or sshd problems.\",\n  realWorld:\"Like a building maintenance engineer who has a service door key that works even when the main electronic entry system (network/SSH) is down \u2014 a way in that doesn't depend on the thing that's currently broken.\",\n  mcq:{ question:\"An instance is unreachable via SSH. Which OCI feature provides access independent of the network stack?\", options:[\"NAT Gateway\",\"Instance Console Connection\",\"Load Balancer health check\",\"Security List\"], correctIndex:1 }\n},\n{\n  id:37, day:6, topic:\"Master Key Rotation & Vault Replication\",\n  question:\"A security team rotates a Vault master key version as part of its key-management schedule and later needs equivalent key protection in another OCI region. Explain how already-encrypted data is treated during rotation and which Vault capability supports regional key availability.\",\n  answer:\"When a master encryption key is rotated, OCI creates a new key version \u2014 it does not delete or invalidate the old one. Data already encrypted under the previous key version remains decryptable, because Vault retains prior key versions specifically so existing ciphertext stays readable; only new encryption operations going forward use the new key version. The Vault feature that makes the same key usable in a second region is Key Replication (Vault/Key Replication), which replicates a vault and its keys to another region so resources there can use the identical key material.\",\n  explanation:\"Rotation is designed to be non-disruptive: it changes which key version is used for new encryption without breaking access to data encrypted earlier, because OCI keeps the full version history of a key. Replication solves a separate problem \u2014 making the same key available in a second region for cross-region access or disaster-recovery scenarios, without which a resource in another region couldn't decrypt data protected by a region-specific key.\",\n  theory:{ what:\"Key rotation creates a new version of a master encryption key while retaining old versions; Key Replication copies a vault and its keys to a second region.\", why:\"Rotation supports security best practice (periodically changing the active key) without breaking existing encrypted data; replication supports cross-region and disaster-recovery architectures that need the same key available in more than one region.\", how:\"Rotating a key in Vault generates a new key version; OCI automatically uses the newest version for new encrypt operations while old versions remain available to decrypt data encrypted under them. Replication is configured on the vault, creating and keeping in sync a replica vault (and its keys) in a target region.\", example:\"A vault key is rotated quarterly for compliance; a customer database encrypted a year ago under an older version is still fully readable. Separately, the vault is replicated to a second region so a DR-standby database there can decrypt data using the same key.\" },\n  quick:\"Rotating a master key creates a new version but keeps old versions, so previously encrypted data stays decryptable. Key Replication makes the same key available in a second region.\",\n  remember:[\"Rotation = new version, old versions kept (old data still decryptable)\",\"Replication = same key, second region\"],\n  trap:\"Students often assume rotation makes old encrypted data unreadable \u2014 it does not; OCI Vault retains prior key versions precisely to prevent that.\",\n  wrongOptionsNote:\"Confusing Secret rotation with Key rotation, or assuming a new Vault must be manually created in the second region rather than using Replication, are common wrong answers.\",\n  diagram:{type:\"linear\", steps:[\"Master key rotated\",\"New key version created\",\"Old key version(s) retained\",\"Old data still decryptable with old version\",\"New data encrypted with new version\"]},\n  examAnswer:\"Rotating a master encryption key creates a new key version while retaining previous versions, so existing encrypted data remains decryptable. Vault Key Replication makes the same key available for use in a second region.\",\n  realWorld:\"Like a building changing its main lock's key but keeping a record of the old key valid for existing safe-deposit boxes that were locked with it, while a duplicate of the new master key is also sent to the building's branch office in another city.\",\n  mcq:{ question:\"When a master encryption key is rotated, what happens to data already encrypted under the previous key version?\", options:[\"It becomes permanently unreadable\",\"It remains decryptable, since old key versions are retained\",\"It is automatically re-encrypted immediately\",\"It is moved to Object Storage automatically\"], correctIndex:1 }\n},\n{\n  id:38, day:6, topic:\"Master Encryption Key vs Data Encryption Key\",\n  question:\"An application uses envelope encryption in OCI and the security team needs to distinguish the key that protects application data from the key that protects the data-encryption-key hierarchy. Explain the roles of these two keys and identify the Vault protection choices available for the master key.\",\n  answer:\"A Master Encryption Key (MEK) is stored and protected in Vault and is used only to encrypt/decrypt Data Encryption Keys \u2014 it never directly encrypts the actual data. A Data Encryption Key (DEK) is generated for the actual data-encryption work; it's wrapped (encrypted) by the master key and stored alongside the encrypted data, and is unwrapped using the master key whenever the data needs to be decrypted. This 'envelope encryption' pattern means bulk data is never encrypted directly with the tightly-controlled master key. A master key's two protection modes in Vault are HSM (Hardware Security Module) \u2014 where the key material lives in a FIPS 140-2 validated hardware module and never leaves it \u2014 and Software \u2014 where the key is protected using software-based security, offered as a lower-cost option without a dedicated hardware module.\",\n  explanation:\"This is envelope encryption: the DEK does the heavy lifting on actual data, while the MEK's only job is protecting DEKs, which keeps the highly sensitive master key's usage minimal and centrally controlled. Protection mode is a separate, orthogonal choice about how securely the master key material itself is safeguarded.\",\n  theory:{ what:\"MEK = the top-level key stored in Vault, used only to wrap/unwrap DEKs. DEK = the key that actually encrypts data, generated per encryption operation and stored wrapped by the MEK. Protection mode = how the MEK's key material itself is safeguarded (HSM or Software).\", why:\"Envelope encryption limits how often and where the sensitive master key is used, reducing exposure, while still allowing efficient bulk data encryption via disposable DEKs. Offering both HSM and Software protection modes balances the strongest possible security assurance against cost/complexity.\", how:\"When data needs encrypting, Vault (or the calling service) generates a DEK, encrypts the data with it, then uses the MEK to wrap the DEK for storage. To decrypt, the MEK unwraps the DEK, which then decrypts the data. The MEK itself is created in a Vault with either HSM protection (backed by dedicated hardware) or Software protection.\", example:\"Object Storage encrypts a large file using DEKs generated for each encryption operation; those DEKs are wrapped by a single Vault MEK, so the MEK is used far less often than if it encrypted every byte of data directly.\" },\n  quick:\"MEK wraps/protects DEKs (never touches raw data directly); DEK encrypts the actual data. Master keys use either HSM protection (dedicated hardware) or Software protection.\",\n  remember:[\"MEK \u2192 wraps the DEK\",\"DEK \u2192 encrypts the DATA\",\"Protection modes: HSM vs Software\"],\n  trap:\"Students often think the master key directly encrypts the data \u2014 in envelope encryption, the master key only ever wraps/unwraps the data encryption key, never the data itself.\",\n  wrongOptionsNote:\"Claiming HSM and Software protection modes offer identical security guarantees is incorrect \u2014 HSM provides a dedicated, FIPS-validated hardware boundary that Software protection does not.\",\n  diagram:{type:\"linear\", steps:[\"Data Encryption Key (DEK) generated\",\"DEK encrypts the actual data\",\"Master Encryption Key (MEK) wraps the DEK\",\"Wrapped DEK stored with the encrypted data\",\"MEK protection mode: HSM or Software\"]},\n  examAnswer:\"The MEK (in Vault) only wraps/unwraps DEKs; the DEK is what actually encrypts the data \u2014 this is envelope encryption. A master key's two protection modes are HSM (dedicated hardware module) and Software.\",\n  realWorld:\"Like a hotel master key (MEK) that doesn't open your suitcase directly \u2014 it only opens a room safe, and the room safe (DEK) is what actually protects your belongings; the master key itself can be kept in a high-security vault (HSM) or a regular locked drawer (Software).\",\n  mcq:{ question:\"In OCI envelope encryption, what does the Master Encryption Key (MEK) directly protect?\", options:[\"The raw application data itself\", \"The Data Encryption Key (DEK), which in turn encrypts the data\", \"The compartment's IAM policies\", \"The instance's SSH keys\"], correctIndex:1 }\n},\n{\n  id:39, day:2, topic:\"Cost Optimization Levers\",\n  question:\"A finance team wants to lower OCI expenditure without removing required application functionality. Which four optimization actions could they investigate, and which OCI capabilities can help identify or implement those opportunities?\",\n  answer:\"(1) Right-sizing \u2014 use Cost Analysis and monitoring data to identify over-provisioned compute/storage and resize shapes to match actual usage. (2) Licensing choice \u2014 use BYOL instead of License Included wherever eligible unused licenses already exist, paying only the infrastructure rate. (3) Spend visibility and alerting \u2014 use Budgets with threshold alerts to catch runaway or unexpected spend early, and Cost Analysis to identify which compartments/services/tags are driving cost. (4) Eliminating idle/unused resources \u2014 use Cost Analysis (and Security Advisor-style recommendations) to identify unattached block volumes, idle instances, or unused reserved capacity, and decommission them.\",\n  explanation:\"None of these levers reduce what the workload can actually do \u2014 they eliminate waste (idle resources, oversized shapes, avoidable license cost) and add visibility (budgets, cost analysis) so spend can be actively managed rather than discovered after the fact.\",\n  theory:{ what:\"Cost optimization levers are the specific, non-capability-reducing actions available to lower OCI spend: right-sizing, licensing choice, visibility/alerting, and idle-resource cleanup.\", why:\"Cutting capability (e.g., removing redundancy) reduces resilience; these levers instead remove waste and improve visibility, preserving what the workload can do while lowering cost.\", how:\"Use Cost Analysis grouped by service/compartment/tag to find right-sizing and idle-resource candidates; switch eligible workloads to BYOL; configure Budgets with alert thresholds for ongoing spend visibility.\", example:\"Cost Analysis reveals a block volume unattached for 3 months (cleanup candidate) and a compute shape running at 8% average CPU (right-sizing candidate) \u2014 both are addressed without touching what the application actually delivers.\" },\n  quick:\"Reduce spend without cutting capability via: right-sizing, BYOL over License Included where eligible, Budgets + Cost Analysis for visibility, and cleaning up idle/unattached resources.\",\n  remember:[\"Right-size the shape\",\"BYOL where eligible\",\"Budgets + Cost Analysis for visibility\",\"Clean up idle resources\"],\n  trap:\"Students often equate 'reducing cost' with 'reducing capability' (e.g., removing redundancy) \u2014 the correct levers target waste and visibility, not capability.\",\n  wrongOptionsNote:\"Suggesting a Quota as a cost-reduction lever is a mismatch \u2014 Quotas control resource consumption limits, not cost visibility or waste elimination directly.\",\n  diagram:{type:\"compare\", tracks:[ {title:\"Right-Size\", steps:[\"Cost Analysis usage data\",\"Resize over-provisioned shapes\"]}, {title:\"Licensing\", steps:[\"Check BYOL eligibility\",\"Switch from License Included\"]}, {title:\"Visibility\", steps:[\"Set Budgets + alerts\",\"Review Cost Analysis regularly\"]}, {title:\"Cleanup\", steps:[\"Find idle/unattached resources\",\"Decommission them\"]} ]},\n  examAnswer:\"Four cost levers: right-sizing (via Cost Analysis usage data), BYOL over License Included where eligible, spend visibility via Budgets and Cost Analysis, and eliminating idle/unattached resources found via Cost Analysis.\",\n  realWorld:\"Like trimming a household budget by downsizing an underused gym membership, switching to a cheaper existing-equipment plan, setting spending alerts, and cancelling a forgotten subscription \u2014 none of which reduces your quality of life.\",\n  mcq:{ question:\"Which of the following is a cost-reduction lever that does NOT reduce a workload's capability?\", options:[\"Removing redundant availability domains\",\"Right-sizing over-provisioned compute shapes\",\"Disabling all monitoring\",\"Reducing IAM group memberships\"], correctIndex:1 }\n},\n{\n  id:40, day:2, topic:\"Governance Fix Sequencing & Audit Evidence\",\n  question:\"An internal audit identifies four governance weaknesses: environment boundaries are unclear, administrative access is broader than necessary, resource metadata is inconsistent, and audit evidence for retention is incomplete. Propose the OCI control or governance change for each weakness and give a sensible remediation sequence.\",\n  answer:\"(ii) Fix first \u2014 remove unnecessary users from the Administrators group and assign scoped, least-privilege groups/policies (IAM), since this is the highest-risk, fastest-to-fix item. (i) Fix second \u2014 restructure resources into separate Production and Development compartments, since this is a structural prerequisite that scoped policies, budgets and tags will subsequently depend on. (iii) Fix third \u2014 define a mandatory tag namespace with tag defaults and retro-tag/attribute existing spend via Cost Analysis, now that the compartment structure exists to tag against. (iv) Fix fourth \u2014 enable and configure the Audit service's retention settings (and confirm Logging is capturing what's needed) so future audits have evidence of activity history. Sequencing prioritizes closing the highest-risk access gap immediately, then fixing structure, then attribution, then evidence/retention.\",\n  explanation:\"The sequencing logic follows risk and dependency: an over-privileged Administrators group is an active security risk and should be closed immediately regardless of other work; compartment restructuring is foundational because tagging and future policy scoping are easier once resources are properly organized; tagging then depends on that structure; and audit/log retention, while important for future compliance evidence, doesn't represent an active exploitable risk the way excess admin access does.\",\n  theory:{ what:\"Sequencing a multi-finding governance remediation means ordering fixes by risk and dependency, not just by the order findings were listed.\", why:\"Treating all findings as equally urgent wastes effort on low-risk items while an active risk (excess admin access) remains open longer than necessary.\", how:\"Rank by (a) active exploitable risk first, (b) structural prerequisites next, (c) items dependent on that structure next, (d) evidence/retention controls that support future audits last.\", example:\"An audit finds excess admin rights and messy compartments simultaneously \u2014 the admin group is trimmed same-day via IAM, while the compartment restructuring project is scheduled and completed over the following weeks, with tagging and Audit retention configured as structure is finalized.\" },\n  quick:\"Sequence by risk and dependency: fix excess admin access first (IAM), then compartment structure, then tagging (Cost Analysis), then Audit service log retention.\",\n  remember:[\"Highest active risk first (IAM least privilege)\",\"Structure before attribution (compartments before tags)\",\"Evidence/retention (Audit service) last, but still required\"],\n  trap:\"Treating all four findings as equal priority, or fixing tagging before compartment structure, is a common trap \u2014 tags are easier to apply correctly once the compartment structure they'll align with already exists.\",\n  wrongOptionsNote:\"Claiming Cost Analysis alone resolves the log-retention finding is a mismatch \u2014 log retention evidence comes from the Audit (and Logging) service, not from cost tooling.\",\n  diagram:{type:\"linear\", steps:[\"1. Fix excess admin access (IAM least privilege)\",\"2. Restructure compartments (Prod / Dev separation)\",\"3. Enforce tagging (namespace + Cost Analysis)\",\"4. Enable Audit service log retention\"]},\n  examAnswer:\"Sequence: first fix excess Administrators-group membership via IAM least privilege (highest active risk), then restructure compartments (Prod/Dev separation), then enforce mandatory tagging via Cost Analysis, and finally ensure Audit service log retention is enabled as ongoing compliance evidence.\",\n  realWorld:\"Like a home-safety inspection finding an unlocked front door, a messy garage, unlabeled storage boxes, and no security-camera footage \u2014 you lock the door first, then organize the garage, then label the boxes, then finally set up the camera system.\",\n  mcq:{ question:\"In a multi-finding governance remediation, which type of finding should typically be fixed first?\", options:[\"Missing tags\",\"Missing log retention evidence\",\"Active excess access risk (e.g., unnecessary Administrators membership)\",\"Compartment naming inconsistency\"], correctIndex:2 }\n},\n{\n  id:41, day:3, topic:\"Linux Numeric Permissions\",\n  question:\"A deployment script on Oracle Linux is listed as `-rwxr-x---`. Which numeric permission represents it, and what can a member of the file's group do?\",\n  answer:\"The permission is 750. The owner has read, write and execute; the group has read and execute but not write; others have no permissions. Therefore a group member can execute and read the script but cannot modify it.\",\n  explanation:\"Linux permissions map read=4, write=2 and execute=1. The three sets are owner, group and others, so rwx=7, r-x=5 and ---=0.\",\n  theory:{what:\"Linux file permissions control read, write and execute access for the owner, group and everyone else.\",why:\"They provide a simple least-privilege boundary for files and executable scripts.\",how:\"Convert each rwx triplet to numbers using 4/2/1 and concatenate the owner, group and other values.\",example:\"rwxr-x--- becomes 7-5-0, or chmod 750.\"},\n  quick:\"rwxr-x--- = 750; the group can read and execute, but cannot write.\",\n  remember:[\"r=4, w=2, x=1\",\"Owner / Group / Others = first / second / third digit\"],\n  trap:\"Do not treat the group execute permission as write permission; r-x contains no w.\",\n  wrongOptionsNote:\"640 removes group execute; 755 gives others access; 700 removes all group permissions.\",\n  diagram:{type:\"linear\",steps:[\"Owner: rwx = 7\",\"Group: r-x = 5\",\"Others: --- = 0\",\"Result: 750\"]},\n  examAnswer:\"The mode is 750. The owner can read/write/execute, the group can read/execute, and others have no access.\",\n  realWorld:\"A deployment script can be executable by the deployment team while remaining inaccessible to unrelated users.\",\n  mcq:{question:\"Which permission mode matches rwxr-x---?\",options:[\"700\",\"740\",\"750\",\"755\"],correctIndex:2}\n},\n{\n  id:42, day:3, topic:\"OCI CIDR and Reserved Addresses\",\n  question:\"A network engineer assigns 10.20.30.0/24 to an OCI subnet. How many IPv4 addresses are in the block, how many does OCI reserve, and how many remain assignable to resources?\",\n  answer:\"A /24 contains 256 addresses. OCI reserves five addresses in each subnet, leaving 251 addresses that can be assigned to resources.\",\n  explanation:\"IPv4 has 32 bits, so /24 leaves 8 host bits: 2^8 = 256 addresses. OCI reserves five addresses in a subnet for networking functions, so 256 - 5 = 251 assignable addresses.\",\n  theory:{what:\"CIDR prefix length determines how many addresses belong to a subnet.\",why:\"Correct CIDR planning prevents address exhaustion and supports future subnet growth.\",how:\"Calculate 2^(32-prefix). For /24, 2^8 gives 256 total addresses; then account for OCI's reserved addresses.\",example:\"10.20.30.0/24 has 256 total addresses and 251 assignable addresses after OCI's five reserved addresses.\"},\n  quick:\"/24 = 256 total IPv4 addresses; OCI reserves 5, leaving 251 assignable addresses.\",\n  remember:[\"/24 \u2192 8 host bits \u2192 256 total\",\"OCI subnet: total minus 5 reserved = assignable\"] ,\n  trap:\"Do not subtract the traditional two network/broadcast addresses as if this were an ordinary on-premises subnet calculation; use OCI's documented subnet reservation rule.\",\n  wrongOptionsNote:\"128 and 254 result from using the wrong prefix or traditional assumptions; 251 is the OCI assignable count for a /24.\",\n  diagram:{type:\"linear\",steps:[\"10.20.30.0/24\",\"8 host bits\",\"256 total addresses\",\"5 OCI-reserved\",\"251 assignable\"]},\n  examAnswer:\"A /24 contains 256 addresses. OCI reserves five, leaving 251 assignable addresses.\",\n  realWorld:\"An architect uses this calculation before splitting a VCN into web, app and database subnets.\",\n  mcq:{question:\"How many addresses are assignable in an OCI /24 subnet after OCI's five reserved addresses?\",options:[\"250\",\"251\",\"252\",\"254\"],correctIndex:1}\n},\n{\n  id:43, day:3, topic:\"OCI CLI Profiles and Authentication\",\n  question:\"An engineer uses the OCI CLI from a Windows laptop and from OCI Cloud Shell. Where is the standard local CLI configuration stored, and what is the key authentication difference between the two environments?\",\n  answer:\"The standard local OCI CLI configuration is stored under ~/.oci/config. A laptop commonly uses an API-key-based CLI profile, while Cloud Shell can use its OCI environment authentication mechanisms rather than requiring the same local private-key setup.\",\n  explanation:\"The config file stores CLI profiles and references to credentials used by local CLI operations. Cloud Shell is already an OCI-hosted environment and can use its supported OCI authentication mechanisms, making setup different from a laptop.\",\n  theory:{what:\"OCI CLI profiles define how the CLI identifies the tenancy, user and region and how it authenticates.\",why:\"Profiles let engineers use different identities or environments without rewriting every command.\",how:\"Configure a profile locally, then select it with the CLI; in Cloud Shell, use the authentication method available to the hosted OCI environment.\",example:\"A laptop profile may point to an API key and tenancy OCID, while Cloud Shell can authenticate through its OCI-integrated mechanism.\"},\n  quick:\"Local CLI configuration normally lives in ~/.oci/config; laptop CLI commonly uses an API-key profile, while Cloud Shell has OCI-integrated authentication options.\",\n  remember:[\"~/.oci/config = CLI profiles\",\"Laptop \u2260 Cloud Shell authentication setup\"] ,\n  trap:\"Do not assume Cloud Shell must always be configured exactly like a developer laptop with a copied private key.\",\n  wrongOptionsNote:\"The config file is not a Terraform state file, and authentication is not identical across every CLI execution environment.\",\n  diagram:{type:\"linear\",steps:[\"OCI CLI\",\"Laptop \u2192 ~/.oci/config \u2192 profile/API key\",\"Cloud Shell \u2192 OCI-hosted authentication\"]},\n  examAnswer:\"The default local configuration is ~/.oci/config. Local CLI use commonly relies on an API-key profile, while Cloud Shell can use OCI-integrated authentication mechanisms.\",\n  realWorld:\"A trainer can demonstrate OCI CLI in Cloud Shell without asking every student to copy private keys onto the lab machine.\",\n  mcq:{question:\"Which file normally stores OCI CLI profile configuration on a local machine?\",options:[\"~/.terraformrc\",\"~/.oci/config\",\"/etc/oci/profile\",\"~/.ssh/oci.conf\"],correctIndex:1}\n},\n{\n  id:44, day:4, topic:\"Declarative vs Imperative IaC\",\n  question:\"A DevOps team can either write a script that performs a sequence of creation commands or describe the infrastructure it wants Terraform to maintain. Which approach is declarative, and what does idempotence mean in this setting?\",\n  answer:\"Terraform's desired-state configuration is declarative: it describes the end state rather than every operation. Idempotence means repeatedly applying the same desired configuration should converge on the same intended state instead of creating duplicate or unintended changes.\",\n  explanation:\"Imperative automation tells the system how to perform steps. Declarative IaC states what should exist and lets Terraform determine the required actions. Idempotence makes repeated automation safe and predictable.\",\n  theory:{what:\"Declarative IaC defines desired state; imperative automation defines the sequence of actions.\",why:\"Declarative and idempotent infrastructure reduces manual coordination and makes repeatable deployments easier.\",how:\"Terraform compares configuration with state and real infrastructure, then plans changes needed to reach the desired state.\",example:\"Running the same Terraform configuration again should not create a second VCN simply because the command was repeated.\"},\n  quick:\"Declarative = describe the desired state; idempotent = repeating the operation converges to the same state safely.\",\n  remember:[\"Declarative = WHAT\",\"Imperative = HOW\",\"Idempotent = repeat safely\"] ,\n  trap:\"Idempotence does not mean 'nothing ever changes'; it means repeated application does not introduce unintended duplicate effects.\",\n  wrongOptionsNote:\"Imperative describes step-by-step actions, while declarative describes the target state.\",\n  diagram:{type:\"linear\",steps:[\"Desired configuration\",\"Terraform compares state\",\"Plan changes\",\"Apply\",\"Repeat \u2192 same desired state\"]},\n  examAnswer:\"Terraform is declarative because it defines the desired state. Idempotence means repeated application produces the same intended infrastructure state without unintended duplication.\",\n  realWorld:\"A CI pipeline can safely run Terraform after a retry without blindly creating a second copy of the environment.\",\n  mcq:{question:\"Which statement best describes declarative Terraform?\",options:[\"It specifies every shell command in execution order\",\"It describes the desired infrastructure state\",\"It requires manual changes after every apply\",\"It cannot be repeated safely\"],correctIndex:1}\n},\n{\n  id:45, day:4, topic:\"Terraform Remote State and Locking\",\n  question:\"Two engineers manage the same OCI environment from separate workstations. What problem does a shared remote Terraform state solve, and why is state locking important when both engineers could run apply at nearly the same time?\",\n  answer:\"Remote state gives the team a shared, authoritative state location. State locking prevents concurrent operations from modifying the same state simultaneously, reducing race conditions, conflicting updates and state corruption.\",\n  explanation:\"Terraform state records how configuration maps to real resources. A shared remote backend lets collaborators work from the same state, while locking coordinates changes so only an allowed operation updates it at a time.\",\n  theory:{what:\"Terraform state is the mapping between configuration and deployed resources; remote state stores that mapping centrally for a team.\",why:\"Local state on separate laptops can diverge and concurrent applies can conflict.\",how:\"Use a supported remote backend with locking so Terraform reads shared state and coordinates writes.\",example:\"Engineer A obtains the lock and applies a change; Engineer B must wait rather than writing a competing state update.\"},\n  quick:\"Remote state = one shared state source; locking = prevents conflicting simultaneous state updates.\",\n  remember:[\"Remote = shared\",\"Lock = one writer at a time\"] ,\n  trap:\"Remote state alone is not the same as locking; both collaboration and concurrency protection matter.\",\n  wrongOptionsNote:\"Version control stores configuration, not the complete live Terraform state relationship; locking specifically addresses concurrent state operations.\",\n  diagram:{type:\"linear\",steps:[\"Engineer A + Engineer B\",\"Shared remote state\",\"Lock acquired\",\"One apply writes\",\"Other operation waits\"]},\n  examAnswer:\"Remote state centralizes the state for collaboration, while state locking prevents simultaneous Terraform operations from corrupting or conflicting over that shared state.\",\n  realWorld:\"A platform team avoids two CI jobs applying different changes to the same infrastructure at the same time.\",\n  mcq:{question:\"What is the main purpose of Terraform state locking?\",options:[\"Encrypt Terraform code\",\"Prevent conflicting concurrent state operations\",\"Create OCI users\",\"Replace the Terraform provider\"],correctIndex:1}\n},\n{\n  id:46, day:4, topic:\"Resource Manager Existing Resources\",\n  question:\"An OCI tenancy contains resources that were created manually before Terraform was adopted. The team wants Resource Manager to help create Terraform configuration representing those existing resources. Which capability should the team investigate?\",\n  answer:\"The team should use Resource Manager's capability for generating Terraform configuration/state from existing OCI resources, where supported, so manually created infrastructure can be brought toward Terraform management.\",\n  explanation:\"Existing infrastructure can be difficult to recreate by hand in HCL. Resource Manager provides capabilities that can help discover existing resources and produce Terraform-oriented configuration/state artifacts.\",\n  theory:{what:\"Infrastructure discovery helps teams move manually provisioned resources toward infrastructure-as-code management.\",why:\"It reduces the effort of reconstructing resource definitions and makes the existing environment easier to manage consistently.\",how:\"Select the supported existing-resource generation/import workflow, review the generated configuration, and validate it before managing the resources with Terraform.\",example:\"A manually created VCN can be discovered and represented in Terraform configuration rather than being rebuilt from scratch.\"},\n  quick:\"Use Resource Manager's existing-resource configuration generation/import capability to help bring manually created OCI resources under Terraform management.\",\n  remember:[\"Existing resources \u2192 discover/generate \u2192 review \u2192 manage with Terraform\"],\n  trap:\"Do not confuse drift detection with generating configuration for resources that were never managed by Terraform.\",\n  wrongOptionsNote:\"Drift detects divergence from managed configuration; it is not the same as discovering unmanaged resources for initial Terraform adoption.\",\n  diagram:{type:\"linear\",steps:[\"Existing OCI resources\",\"Resource Manager discovery/generation\",\"Terraform configuration/state\",\"Review\",\"Terraform management\"]},\n  examAnswer:\"Use the Resource Manager capability that can generate Terraform configuration/state from existing OCI resources, then review and adopt the generated configuration.\",\n  realWorld:\"A team can transition a manually built VCN into an IaC-managed environment without recreating every resource from memory.\",\n  mcq:{question:\"Which task is associated with bringing manually created OCI resources toward Terraform management?\",options:[\"Running a budget alert\",\"Generating Terraform configuration for existing resources\",\"Creating an IAM group\",\"Rotating a Vault key\"],correctIndex:1}\n},\n{\n  id:47, day:5, topic:\"Boot vs Block Volume and Multi-Attach\",\n  question:\"An application team wants to keep the operating system on its normal boot disk but store shared application data separately. They are also considering attaching one data volume to multiple compute instances. Which OCI storage type and feature should they evaluate, and what filesystem concern must be considered?\",\n  answer:\"Use a Block Volume for separate persistent application data and evaluate Block Volume multi-attach when supported. Multi-instance write access requires a filesystem/application design that safely supports shared access; a normal single-writer filesystem should not simply be mounted read-write by multiple hosts.\",\n  explanation:\"Boot Volumes contain the operating system for a Compute instance, while Block Volumes provide separate persistent storage. Multi-attach is intended for shared attachment scenarios, but the filesystem and application must support concurrent access safely.\",\n  theory:{what:\"Boot Volume stores the instance OS; Block Volume provides detachable persistent block storage for data.\",why:\"Separating OS and application data improves lifecycle management and enables storage patterns such as shared attachment where appropriate.\",how:\"Create a Block Volume, attach it to supported instances, and use a filesystem/application architecture designed for the intended access pattern.\",example:\"A cluster can use a multi-attached block device only when its filesystem and application are designed for coordinated multi-host access.\"},\n  quick:\"Boot Volume = OS; Block Volume = persistent data. Multi-attach requires a filesystem/application design safe for shared access.\",\n  remember:[\"Boot = boot the OS\",\"Block = application data\",\"Multi-attach \u2260 automatically safe multi-writer\"] ,\n  trap:\"Attaching the same ordinary filesystem read-write to multiple hosts can corrupt data; multi-attach is not a replacement for a clustered filesystem.\",\n  wrongOptionsNote:\"A boot volume is primarily the OS disk; Object Storage is not a block device for mounting as a normal local filesystem.\",\n  diagram:{type:\"linear\",steps:[\"Compute VM\",\"Boot Volume \u2192 OS\",\"Block Volume \u2192 Data\",\"Multi-attach \u2192 multiple VMs\",\"Filesystem/application must support shared access\"]},\n  examAnswer:\"Boot Volumes hold the OS; Block Volumes provide persistent data storage and can support multi-attach where applicable. Shared attachment requires a filesystem/application design that safely supports concurrent access.\",\n  realWorld:\"A clustered application may separate each VM's OS disk from a shared data volume designed for coordinated access.\",\n  mcq:{question:\"Which statement is correct?\",options:[\"Boot Volume is always a shared database filesystem\",\"Block Volume can be used for persistent data and may support multi-attach\",\"Multi-attach makes any filesystem safe for concurrent writes\",\"Object Storage is the same as a block device\"],correctIndex:1}\n},\n{\n  id:48, day:5, topic:\"OCI Gateway Selection\",\n  question:\"A three-tier application has a public web tier, a private application tier that needs outbound package updates, and a private database that must reach supported OCI services without public internet exposure. Which gateway path belongs to each tier?\",\n  answer:\"The public web tier uses an Internet Gateway. The private application tier can use a NAT Gateway for outbound internet access. The private database can use a Service Gateway to reach supported OCI services privately.\",\n  explanation:\"Internet Gateway provides public internet connectivity for public resources. NAT Gateway allows private resources to initiate outbound internet connections without accepting unsolicited inbound internet traffic. Service Gateway provides private access to supported OCI services.\",\n  theory:{what:\"OCI gateways determine how subnet traffic leaves or reaches a VCN.\",why:\"Choosing the correct gateway prevents unnecessary public exposure while still providing required connectivity.\",how:\"Associate the subnet with an appropriate route table and route destination traffic through the required gateway.\",example:\"Web \u2192 Internet Gateway; App \u2192 NAT Gateway; DB \u2192 Service Gateway for supported OCI services.\"},\n  quick:\"Public web \u2192 IGW; private outbound internet \u2192 NAT; private OCI service access \u2192 Service Gateway.\",\n  remember:[\"IGW = Internet\",\"NAT = private outbound internet\",\"SGW = OCI services\"] ,\n  trap:\"A NAT Gateway does not make a private resource publicly reachable; it provides outbound initiation only.\",\n  wrongOptionsNote:\"Using an Internet Gateway for a private database unnecessarily exposes the path to public internet connectivity.\",\n  diagram:{type:\"linear\",steps:[\"Web subnet \u2192 Internet Gateway\",\"App subnet \u2192 NAT Gateway\",\"DB subnet \u2192 Service Gateway\",\"Route tables decide the path\"]},\n  examAnswer:\"Use Internet Gateway for the public web tier, NAT Gateway for private outbound internet access, and Service Gateway for private access to supported OCI services.\",\n  realWorld:\"A private application server can download OS updates through NAT without receiving direct inbound internet connections.\",\n  mcq:{question:\"Which gateway is normally used when a private OCI subnet needs outbound internet access without direct inbound internet exposure?\",options:[\"Internet Gateway\",\"NAT Gateway\",\"Service Gateway\",\"Dynamic Routing Gateway\"],correctIndex:1}\n},\n{\n  id:49, day:5, topic:\"Load Balancer 502 Troubleshooting\",\n  question:\"A public OCI Load Balancer accepts client connections, but users receive HTTP 502 responses even though the backend VM is running. Which two configuration areas should the administrator inspect first?\",\n  answer:\"Inspect the listener/backend-set relationship and the backend health-check configuration, including backend port and protocol. A running operating system does not guarantee that the load balancer can successfully connect to the application endpoint.\",\n  explanation:\"A 502 can occur when the load balancer cannot obtain a valid response from the backend. The VM may be healthy while the application port, listener/backend protocol, backend registration, or health check is incorrect.\",\n  theory:{what:\"OCI Load Balancer distributes client traffic to configured backend servers through listeners and backend sets.\",why:\"Backend health is about application reachability from the load balancer, not merely whether the VM itself is powered on.\",how:\"Check listener configuration, backend set membership, backend port, protocol and health-check results.\",example:\"A VM is running Nginx on 8080 but the backend is configured for port 80, causing failed health checks and client errors.\"},\n  quick:\"For a 502, inspect the listener/backend-set path and backend health, especially port and protocol.\",\n  remember:[\"VM healthy \u2260 application/backend healthy\",\"Check listener \u2192 backend set \u2192 health check \u2192 port/protocol\"] ,\n  trap:\"Do not stop troubleshooting after seeing that the Compute instance is running.\",\n  wrongOptionsNote:\"CPU utilization and boot volume status alone do not confirm that the Load Balancer can reach the correct application endpoint.\",\n  diagram:{type:\"linear\",steps:[\"Client\",\"Listener\",\"Backend Set\",\"Health Check\",\"Backend Port / Protocol\",\"Application\"]},\n  examAnswer:\"Check the listener/backend-set configuration and backend health-check details, especially the backend port and protocol.\",\n  realWorld:\"An application may listen on 8080 while the load balancer is configured for 80, producing failures despite a healthy VM.\",\n  mcq:{question:\"A VM is running but an OCI Load Balancer returns 502. What should be checked first?\",options:[\"Only the VM's CPU usage\",\"Listener/backend configuration and backend health checks\",\"Only the boot volume size\",\"Only the IAM password policy\"],correctIndex:1}\n},\n{\n  id:50, day:6, topic:\"RTO vs RPO \u2014 Exam Extension\",\n  question:\"A business says its recovered service must be available within 30 minutes and it can tolerate losing at most five minutes of transactions. Which disaster-recovery objectives describe these two requirements?\",\n  answer:\"The 30-minute recovery requirement is the RTO, while the five-minute acceptable data-loss window is the RPO. More frequent backups can generally improve the achievable RPO.\",\n  explanation:\"RTO measures how quickly service must be restored. RPO measures how much recent data loss is acceptable, expressed as a time window.\",\n  theory:{what:\"Recovery Time Objective is the target time to restore service; Recovery Point Objective is the target amount of data loss measured in time.\",why:\"They define different disaster-recovery outcomes and drive different architecture and backup choices.\",how:\"Set RTO based on downtime tolerance and RPO based on data-loss tolerance, then select replication and backup mechanisms that meet both.\",example:\"RTO 30 minutes and RPO 5 minutes means the service should return within 30 minutes and data loss should be no more than about five minutes.\"},\n  quick:\"RTO = how fast you recover; RPO = how much data you can lose.\",\n  remember:[\"RTO = Time to Restore\",\"RPO = Point of data recovery\"] ,\n  trap:\"Backup frequency primarily improves RPO, not RTO.\",\n  wrongOptionsNote:\"Confusing downtime with data loss reverses the definitions.\",\n  diagram:{type:\"linear\",steps:[\"Failure\",\"\u2190 RPO: acceptable data-loss window\",\"Recovery process\",\"\u2190 RTO: target time to restore service\"]},\n  examAnswer:\"RTO is the target recovery time; RPO is the maximum acceptable data-loss window. More frequent backups generally improve RPO.\",\n  realWorld:\"A payment system may require a low RPO while a less critical internal tool can tolerate a larger recovery point.\",\n  mcq:{question:\"Which objective is directly improved by taking backups more frequently?\",options:[\"RTO\",\"RPO\",\"IAM policy scope\",\"Service quota\"],correctIndex:1}\n},\n{\n  id:51, day:5, topic:\"Site-to-Site VPN Troubleshooting \u2014 Exam Extension\",\n  question:\"An OCI VPN tunnel reports UP, but packets from an on-premises application never reach a private VCN subnet. Which combination should the network engineer verify next?\",\n  answer:\"Verify the on-premises routes, OCI route tables/DRG routes, and security rules for the required source and destination traffic. A tunnel being UP does not guarantee that end-to-end routing and filtering are correct.\",\n  explanation:\"VPN status describes tunnel establishment, not complete application connectivity. Traffic still needs correct routes in both directions and permissive security controls.\",\n  theory:{what:\"Site-to-Site VPN provides encrypted connectivity between an on-premises network and OCI through a DRG.\",why:\"Routing and security must be correct on both sides for application traffic to traverse the tunnel.\",how:\"Trace the packet path from on-premises route \u2192 VPN/DRG \u2192 OCI route table \u2192 subnet/VNIC \u2192 security controls and verify the return path.\",example:\"The tunnel is UP but the OCI subnet has no route back to the on-premises CIDR, so replies never return.\"},\n  quick:\"VPN UP only proves the tunnel is established; check routes on both sides, DRG/route tables and security rules.\",\n  remember:[\"Tunnel UP \u2260 traffic UP\",\"Check both directions\"] ,\n  trap:\"Do not assume a healthy tunnel automatically creates application routes.\",\n  wrongOptionsNote:\"Changing IAM policies will not fix a missing network route for data-plane traffic.\",\n  diagram:{type:\"linear\",steps:[\"On-prem route\",\"VPN tunnel\",\"DRG\",\"OCI route table\",\"Subnet / VNIC\",\"Security rules\",\"Return route\"]},\n  examAnswer:\"Check on-premises routing, OCI DRG/route-table routes, and security rules for both directions of the required traffic.\",\n  realWorld:\"A company can have a green VPN tunnel while an incorrect route still prevents a branch subnet from reaching OCI.\",\n  mcq:{question:\"What does a VPN tunnel in UP state NOT guarantee?\",options:[\"That the tunnel is established\",\"That end-to-end application traffic is correctly routed\",\"That the VPN exists\",\"That the peers negotiated successfully\"],correctIndex:1}\n},\n{\n  id:52, day:5, topic:\"FastConnect \u2014 Exam Extension\",\n  question:\"An enterprise wants a dedicated private connectivity path between its data center and OCI instead of relying on the public internet. Which OCI service should the architect evaluate, and what is the role of its virtual circuit?\",\n  answer:\"The architect should evaluate FastConnect. Its virtual circuit provides the logical private connectivity path used to exchange traffic between the customer network and OCI through the FastConnect connection.\",\n  explanation:\"FastConnect is designed for private, dedicated connectivity between on-premises environments and OCI. The virtual circuit represents the logical connection used to carry traffic into OCI networking services.\",\n  theory:{what:\"FastConnect provides private connectivity between a customer network and OCI.\",why:\"It is useful for predictable enterprise connectivity, private traffic paths and workloads that should not depend on public internet routing.\",how:\"Establish the FastConnect connection and configure the appropriate virtual circuit and routing through the OCI networking architecture.\",example:\"A data center uses FastConnect to reach VCN workloads through a private network path.\"},\n  quick:\"FastConnect = private enterprise connectivity to OCI; the virtual circuit is the logical traffic connection.\",\n  remember:[\"FastConnect = private path\",\"Virtual circuit = logical connection\"] ,\n  trap:\"FastConnect is not simply another internet gateway; it provides private connectivity from the customer network into OCI.\",\n  wrongOptionsNote:\"NAT Gateway provides outbound internet for private OCI resources; it does not provide dedicated on-premises connectivity.\",\n  diagram:{type:\"linear\",steps:[\"Customer Data Center\",\"FastConnect\",\"Virtual Circuit\",\"OCI networking / DRG\",\"VCN\"]},\n  examAnswer:\"FastConnect provides private connectivity between on-premises and OCI, with a virtual circuit representing the logical connection used to exchange traffic.\",\n  realWorld:\"A bank can use a private connection to reach OCI workloads without sending enterprise application traffic over the public internet.\",\n  mcq:{question:\"Which OCI service is designed for private dedicated connectivity between an enterprise network and OCI?\",options:[\"NAT Gateway\",\"FastConnect\",\"Internet Gateway\",\"Service Gateway\"],correctIndex:1}\n},\n{\n  id:53, day:6, topic:\"Database HA Across ADs \u2014 Exam Extension\",\n  question:\"A critical database must continue operating if one Availability Domain becomes unavailable. What architectural property should protect the workload, and how is this different from preparing for an entire-region outage?\",\n  answer:\"The database architecture should use redundancy or a supported high-availability configuration across Availability Domains where available. Protection from a region-wide outage requires a separate cross-region disaster-recovery design.\",\n  explanation:\"Availability and disaster recovery address different failure scopes. Multi-AD redundancy targets localized or AD-level failures, while cross-region DR addresses loss of an entire OCI region.\",\n  theory:{what:\"High availability keeps a service running through expected infrastructure failures; disaster recovery restores service after a larger site or region failure.\",why:\"Designing for the wrong failure domain can leave a workload exposed to the actual outage scenario.\",how:\"Identify the failure domain, place redundant components accordingly, and add a cross-region recovery strategy for regional disasters.\",example:\"A database may have redundant deployment across ADs for local resilience plus a replica or recovery environment in another region for regional DR.\"},\n  quick:\"AD failure \u2192 multi-AD HA; region failure \u2192 cross-region DR.\",\n  remember:[\"HA = keep running\",\"DR = recover after larger failure\"] ,\n  trap:\"Multi-AD redundancy does not by itself protect against loss of the entire region.\",\n  wrongOptionsNote:\"A single backup in the same AD does not provide strong protection from an AD outage; regional DR needs another failure domain.\",\n  diagram:{type:\"linear\",steps:[\"Region A\",\"AD 1 \u2194 AD 2 = HA\",\"Region A failure\",\"\u2193\",\"Region B = DR target\"]},\n  examAnswer:\"Use a supported redundant/high-availability database design across ADs for an AD failure, and a separate cross-region DR strategy for regional failure.\",\n  realWorld:\"A business may run redundant database components across ADs and maintain a recovery copy in another region for a major disaster.\",\n  mcq:{question:\"What does multi-Availability-Domain database redundancy primarily protect against?\",options:[\"Only IAM mistakes\",\"Failure of one Availability Domain\",\"Loss of the entire internet\",\"Only cost overruns\"],correctIndex:1}\n},\n{\n  id:54, day:6, topic:\"Full Stack Disaster Recovery \u2014 Exam Extension\",\n  question:\"A regional disaster would affect a service's VMs, networking, database and other dependencies. The operations team wants one orchestrated recovery workflow rather than manually restoring each layer. Which OCI capability is designed for this purpose?\",\n  answer:\"OCI Full Stack Disaster Recovery is designed to orchestrate recovery of the complete application stack and its dependencies, not merely the database.\",\n  explanation:\"Full Stack Disaster Recovery coordinates recovery actions across application infrastructure so teams can execute an ordered recovery plan for a larger workload.\",\n  theory:{what:\"Full Stack Disaster Recovery orchestrates disaster recovery for an application stack and its infrastructure dependencies.\",why:\"Application recovery often requires more than restoring a database; compute, networking, storage and application components must be recovered in the correct order.\",how:\"Define the protected stack and recovery plan, configure dependencies and execute the orchestrated recovery workflow when required.\",example:\"A regional recovery can coordinate network preparation, compute recovery and database recovery rather than leaving operators to perform each step manually.\"},\n  quick:\"Full Stack DR orchestrates recovery of the application stack and its dependencies, not only the database.\",\n  remember:[\"Full Stack = beyond database\",\"Orchestrate the recovery order\"] ,\n  trap:\"Do not confuse database backup/replication with full application-stack orchestration.\",\n  wrongOptionsNote:\"Object Storage replication alone does not orchestrate a complete application recovery sequence.\",\n  diagram:{type:\"linear\",steps:[\"Primary Region\",\"Compute + Network + Database + Dependencies\",\"Failure\",\"Full Stack DR orchestration\",\"Recovery Region\"]},\n  examAnswer:\"OCI Full Stack Disaster Recovery orchestrates recovery of the broader application stack and dependencies beyond the database itself.\",\n  realWorld:\"An enterprise can recover network, compute and database components in an ordered workflow after a regional outage.\",\n  mcq:{question:\"What is the main purpose of OCI Full Stack Disaster Recovery?\",options:[\"Only create IAM users\",\"Only encrypt block volumes\",\"Orchestrate recovery of an application stack and dependencies\",\"Only calculate monthly cost\"],correctIndex:2}\n},\n{\n  id:55, day:2, topic:\"Audit and Log Retention Evidence\",\n  question:\"During an internal control review, auditors ask for evidence that administrative activity is retained for later investigation. Which OCI evidence source should the team examine, and what is the purpose of retention?\",\n  answer:\"The team should examine OCI Audit records and the configured logging/retention controls used for the required evidence. Retention preserves activity history so security and compliance teams can investigate actions after they occur.\",\n  explanation:\"Audit records provide evidence of API and administrative activity. Retention settings determine how long required evidence remains available for investigation and compliance review.\",\n  theory:{what:\"Audit evidence records who performed relevant OCI actions and when, while retention controls determine how long evidence is kept.\",why:\"Without retained activity history, an organization may be unable to demonstrate control operation or investigate past events.\",how:\"Review Audit records, required Logging configuration and retention policies according to the organization's compliance requirements.\",example:\"An auditor can review historical administrative API activity to verify that a sensitive change occurred under an approved identity.\"},\n  quick:\"Audit records provide activity evidence; retention keeps that evidence available for later investigation and compliance.\",\n  remember:[\"Audit = who did what\",\"Retention = keep the evidence\"] ,\n  trap:\"Cost Analysis cannot prove administrative activity retention; use the appropriate audit/logging evidence source.\",\n  wrongOptionsNote:\"Budgets and tags help with cost governance, not with proving who performed an administrative API action.\",\n  diagram:{type:\"linear\",steps:[\"OCI activity\",\"Audit records\",\"Logging / retention controls\",\"Historical evidence\",\"Compliance / investigation\"]},\n  examAnswer:\"Review Audit records and the relevant logging/retention configuration. Retention ensures activity evidence remains available for audits and investigations.\",\n  realWorld:\"A security team can investigate who changed a production resource weeks after the change if the required audit evidence was retained.\",\n  mcq:{question:\"Which OCI evidence is most relevant for proving historical administrative activity?\",options:[\"Budget alerts\",\"Audit records and appropriate retention\",\"Tag defaults only\",\"Compute shape list\"],correctIndex:1}\n}\n\n];\n\n/* ============================= GAMIFICATION DEFS ============================= */\nconst BADGES = [\n  {id:'first_correct', name:'First Blood', desc:'Answer your first question correctly', icon:'\ud83c\udfaf', cond:s=>Object.values(s.progress).filter(v=>v==='know').length>=1},\n  {id:'streak5', name:'On Fire', desc:'5 correct answers in a row', icon:'\ud83d\udd25', cond:s=>s.bestStreak>=5},\n  {id:'streak10', name:'Unstoppable', desc:'10 correct answers in a row', icon:'\u26a1', cond:s=>s.bestStreak>=10},\n  {id:'day1_master', name:'Day 1 Champion', desc:'Get every Day 1 question correct', icon:'\ud83e\udd47', cond:s=>DATA.filter(d=>d.day===1).every(d=>s.progress[d.id]==='know')},\n  {id:'day2_master', name:'Day 2 Champion', desc:'Get every Day 2 question correct', icon:'\ud83c\udfc6', cond:s=>DATA.filter(d=>d.day===2).every(d=>s.progress[d.id]==='know')},\n  {id:'day3_master', name:'Day 3 Champion', desc:'Get every Day 3 question correct', icon:'\ud83d\udc27', cond:s=>DATA.filter(d=>d.day===3).every(d=>s.progress[d.id]==='know')},\n  {id:'day4_master', name:'Day 4 Champion', desc:'Get every Day 4 question correct', icon:'\ud83e\uddf1', cond:s=>DATA.filter(d=>d.day===4).every(d=>s.progress[d.id]==='know')},\n  {id:'day5_master', name:'Day 5 Champion', desc:'Get every Day 5 question correct', icon:'\ud83c\udf10', cond:s=>DATA.filter(d=>d.day===5).every(d=>s.progress[d.id]==='know')},\n  {id:'day6_master', name:'Day 6 Champion', desc:'Get every Day 6 question correct', icon:'\ud83d\udd10', cond:s=>DATA.filter(d=>d.day===6).every(d=>s.progress[d.id]==='know')},\n  {id:'completionist', name:'Completionist', desc:'Attempt every question', icon:'\ud83d\udcd8', cond:s=>DATA.every(d=>s.progress[d.id])},\n  {id:'perfect', name:'Perfectionist', desc:'100% accuracy across all questions', icon:'\ud83d\udc8e', cond:s=>DATA.every(d=>s.progress[d.id]==='know')},\n  {id:'level5', name:'Level 5 Reached', desc:'Reach XP Level 5', icon:'\ud83d\ude80', cond:s=>s.level>=5}\n];\n\n/* ============================= STATE ============================= */\nconst state = {\n  mode:\"study\",\n  currentId:1,\n  search:\"\",\n  dayFilter:\"all\",\n  statusFilter:\"all\",\n  progress:{},\n  revealed:{},\n  collapsed:{},\n  mcqCache:{},\n  mcqSelected:{},\n  mcqAnswered:{},\n  examQueue:[],\n  examIndex:0,\n  examAnswers:{},\n  examStarted:false,\n  examFinished:false,\n  theme:\"light\",\n  xp:0, level:1, streak:0, bestStreak:0,\n  badges:new Set(),\n  activeToast:null,\n  toastTimer:null\n};\n\nfunction byId(id){ return DATA.find(d=>d.id===id); }\nfunction levelXpNeeded(level){ return level*150; }\nfunction xpIntoLevel(){ const base=(state.level-1)*150; return state.xp-base; }\nfunction xpPct(){ return Math.min(100, Math.round(xpIntoLevel()/150*100)); }\n\nfunction shuffle(arr){\n  const a = arr.slice();\n  for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }\n  return a;\n}\n\nfunction showToast(title, sub, icon){\n  state.activeToast = {title,sub,icon};\n  render();\n  if(state.toastTimer) clearTimeout(state.toastTimer);\n  state.toastTimer = setTimeout(()=>{ state.activeToast=null; renderToastOnly(); }, 3000);\n}\nfunction renderToastOnly(){\n  const host = document.getElementById(\"toast-host\");\n  host.innerHTML = state.activeToast ? toastHtml() : \"\";\n}\nfunction toastHtml(){\n  const t = state.activeToast;\n  return `<div class=\"toast\"><div class=\"ic\">${t.icon}</div><div><div class=\"t1\">${t.title}</div><div class=\"t2\">${t.sub}</div></div></div>`;\n}\n\nfunction addXP(amount){\n  state.xp += amount;\n  const newLevel = 1 + Math.floor(state.xp/150);\n  if(newLevel > state.level){\n    state.level = newLevel;\n    showToast(`Level Up! Level ${state.level}`, \"Keep going \u2014 new badges may unlock\", \"\ud83d\ude80\");\n  }\n}\n\nfunction checkBadges(){\n  BADGES.forEach(b=>{\n    if(!state.badges.has(b.id) && b.cond(state)){\n      state.badges.add(b.id);\n      setTimeout(()=>showToast(`Badge Unlocked: ${b.name}`, b.desc, b.icon), 350);\n    }\n  });\n}\n\nfunction handleAnswerResult(item, isCorrect){\n  if(isCorrect){\n    state.streak += 1;\n    state.bestStreak = Math.max(state.bestStreak, state.streak);\n    const bonus = Math.min(state.streak*2, 20);\n    addXP(15 + bonus);\n    state.progress[item.id] = 'know';\n  } else {\n    state.streak = 0;\n    addXP(3);\n    state.progress[item.id] = 'review';\n  }\n  checkBadges();\n}\n\n/* ============================= DIAGRAM ============================= */\nfunction renderDiagram(d){\n  if(!d) return \"\";\n  if(d.type===\"linear\"){\n    return `<div class=\"diagram\">${d.steps.map((s,i)=>`<div class=\"dbox\" data-n=\"${i+1}\">${s}</div>${i<d.steps.length-1?'<div class=\"darrow\">\u2193</div>':''}`).join(\"\")}</div>`;\n  }\n  if(d.type===\"tree\"){\n    return `<div class=\"diagram\"><div class=\"dtree\"><div class=\"dbox\" data-n=\"0\">${d.root}</div><div class=\"darrow\">\u2193</div><div class=\"children\">${d.children.map((c,i)=>`<div class=\"child\"><div class=\"dbox alt\" data-n=\"${i+1}\">${c}</div></div>`).join(\"\")}</div></div></div>`;\n  }\n  if(d.type===\"compare\"){\n    return `<div class=\"diagram\"><div class=\"dcompare\">${d.tracks.map(t=>`<div class=\"dtrack\"><div class=\"title\">${t.title}</div>${t.steps.map((s,i)=>`<div class=\"dbox\" data-n=\"${i+1}\">${s}</div>${i<t.steps.length-1?'<div class=\"darrow\">\u2193</div>':''}`).join(\"\")}</div>`).join(\"\")}</div></div>`;\n  }\n  if(d.type===\"layers\"){\n    return `<div class=\"diagram\"><div class=\"dlayers\">${d.layers.map(l=>`<div class=\"dlayer\"><b>${l.label}</b>${l.detail}</div>`).join(\"\")}</div></div>`;\n  }\n  return \"\";\n}\n\n/* ============================= HELPERS / SECTIONS ============================= */\nfunction sectionWrap(key,title,bodyHtml,openByDefault,icon){\n  const collapsed = state.collapsed[key]===undefined? !openByDefault : state.collapsed[key];\n  return `<div class=\"section ${collapsed?'collapsed':''}\" data-sectionkey=\"${key}\">\n    <div class=\"section-head\" onclick=\"toggleSection('${key}')\"><span class=\"chev\">\u25be</span><h4>${icon?icon+' ':''}${title}</h4></div>\n    <div class=\"section-body\">${bodyHtml}</div>\n  </div>`;\n}\nfunction toggleSection(key){ state.collapsed[key] = state.collapsed[key]===undefined? true : !state.collapsed[key]; render(); }\n\nfunction theoryBlock(item){\n  return `<div class=\"theory-grid\">\n    <div class=\"theory-box\"><div class=\"lbl\">\ud83d\udd0e What is it?</div>${item.theory.what}</div>\n    <div class=\"theory-box\"><div class=\"lbl\">\ud83c\udfaf Why is it used?</div>${item.theory.why}</div>\n    <div class=\"theory-box\"><div class=\"lbl\">\u2699\ufe0f How does it work?</div>${item.theory.how}</div>\n    <div class=\"theory-box\"><div class=\"lbl\">\u2601\ufe0f OCI Example</div>${item.theory.example}</div>\n  </div>`;\n}\nfunction quickBlock(item){ return `<div class=\"callout quick\"><span class=\"lbl\">\u26a1 Quick Answer</span>${item.quick}</div>`; }\nfunction rememberBlock(item){ return `<div class=\"callout remember\"><span class=\"lbl\">\ud83e\udde0 Remember This</span>${item.remember.map(r=>`<div class=\"remember-line\">${r}</div>`).join(\"\")}</div>`; }\nfunction trapBlock(item){ return `<div class=\"callout trap\"><span class=\"lbl\">\u26a0\ufe0f Exam Trap</span>${item.trap}</div>`; }\nfunction realWorldBlock(item){ return `<div class=\"callout real\"><span class=\"lbl\">\ud83c\udf0d Real-Life Example</span>${item.realWorld}</div>`; }\nfunction whyWrongBlock(item){ return `<div class=\"theory-box\" style=\"margin-top:6px;\"><div class=\"lbl\">\u274c Why other interpretations are wrong</div>${item.wrongOptionsNote}</div>`; }\nfunction explainSimpleBlock(item){ return `<div class=\"explain-simple\"><div class=\"lbl\">\ud83d\udcac In Plain Language</div>${item.quick}</div>`; }\nfunction examAnswerBlock(item){ return `<div class=\"callout correct-box\"><span class=\"lbl\">\ud83d\udcdd Exam Answer</span>${item.examAnswer}</div>`; }\n\n/* ============================= MCQ ============================= */\nfunction getShuffledMCQ(item){\n  if(!state.mcqCache[item.id]){\n    const opts = item.mcq.options.map((text,i)=>({text, correct:i===item.mcq.correctIndex}));\n    state.mcqCache[item.id] = shuffle(opts);\n  }\n  return state.mcqCache[item.id];\n}\nfunction selectMcqOption(itemId, idx){\n  if(state.mcqAnswered[itemId]) return;\n  state.mcqSelected[itemId] = idx;\n  render();\n}\nfunction submitMcq(itemId){\n  const item = byId(itemId);\n  const sel = state.mcqSelected[itemId];\n  if(sel===undefined) return;\n  const opts = getShuffledMCQ(item);\n  const isCorrect = opts[sel].correct;\n  state.mcqAnswered[itemId] = true;\n  state.revealed[itemId] = true;\n  handleAnswerResult(item, isCorrect);\n  render();\n}\nfunction renderMcqBlock(item, keyPrefix){\n  const opts = getShuffledMCQ(item);\n  const answered = !!state.mcqAnswered[item.id];\n  const sel = state.mcqSelected[item.id];\n  const letters = [\"A\",\"B\",\"C\",\"D\"];\n  let html = `<div class=\"mcq-list\">`;\n  opts.forEach((o,i)=>{\n    let cls = \"mcq-opt\";\n    if(!answered && sel===i) cls += \" selected\";\n    if(answered){\n      if(o.correct) cls += \" correct-reveal\";\n      else if(sel===i) cls += \" wrong-reveal\";\n      else cls += \" dim\";\n    }\n    html += `<button class=\"${cls}\" ${answered?'':`onclick=\"selectMcqOption(${item.id},${i})\"`}>\n      <span class=\"optkey\">${letters[i]}</span><span>${o.text}</span>\n    </button>`;\n  });\n  html += `</div>`;\n  if(!answered){\n    html += `<div class=\"btnrow\"><button class=\"btn primary\" ${sel===undefined?'disabled':''} onclick=\"submitMcq(${item.id})\">Submit Answer</button></div>`;\n  } else {\n    const isCorrect = opts[sel] ? opts[sel].correct : false;\n    html += `<div class=\"result-banner ${isCorrect?'correct':'incorrect'}\">\n      ${isCorrect? '\u2705 Correct! Nicely done.' : '\u274c Not quite \u2014 review the correct answer below.'}\n      <span class=\"xpgain\">+XP earned</span>\n    </div>`;\n  }\n  return html;\n}\n\n/* ============================= QUESTION CARD ============================= */\nfunction renderQuestionCard(item, mode){\n  const revealed = mode==='study' ? true : !!state.revealed[item.id];\n  const st = state.progress[item.id];\n\n  let html = `<div class=\"card\">\n    <div class=\"eyebrow\"><span class=\"pill day${item.day}\">Day ${item.day}</span><span class=\"pill\">${item.topic}</span><span class=\"pill mono\">Q${item.id} / ${DATA.length}</span>${st==='know'?'<span class=\"pill\" style=\"background:var(--green-soft); color:var(--green);\">\u2713 Mastered</span>':''}${st==='review'?'<span class=\"pill\" style=\"background:var(--rust-soft); color:var(--rust);\">\u21bb Review</span>':''}</div>\n    <div class=\"q-text\">${item.question}</div>`;\n\n  if(mode==='practice'){\n    html += `<div class=\"callout\" style=\"border-left:3px solid var(--violet); background:var(--violet-soft);\"><span class=\"lbl\">\ud83c\udfae Quick Check</span>${item.mcq.question}</div>`;\n    html += renderMcqBlock(item);\n  }\n\n  if(revealed){\n    html += `<div class=\"section\" data-sectionkey=\"ans-${item.id}\"><div class=\"section-body\">\n      <div class=\"callout\" style=\"border-left:3px solid var(--slate); background:var(--slate-soft); margin-top:14px;\">\n        <span class=\"lbl\">\u2714 Correct Answer</span>${item.answer}\n      </div>\n    </div></div>`;\n    html += sectionWrap(`explain-${item.id}`, \"Explanation\", `<p>${item.explanation}</p>`, true, \"\ud83d\udcd6\");\n    html += sectionWrap(`real-${item.id}`, \"Real-Life Example\", realWorldBlock(item), true, \"\ud83c\udf0d\");\n    html += sectionWrap(`theory-${item.id}`, \"Theory\", theoryBlock(item), true, \"\ud83c\udf93\");\n    html += sectionWrap(`visual-${item.id}`, \"Visual Explanation\", renderDiagram(item.diagram), true, \"\ud83d\uddbc\ufe0f\");\n    html += sectionWrap(`quick-${item.id}`, \"Quick Answer &amp; Remember This\", quickBlock(item)+rememberBlock(item), true, \"\u26a1\");\n    html += sectionWrap(`trap-${item.id}`, \"Exam Trap\", trapBlock(item), true, \"\u26a0\ufe0f\");\n    html += sectionWrap(`wrong-${item.id}`, \"Why Other Interpretations Are Wrong\", whyWrongBlock(item), false, \"\u274c\");\n    html += sectionWrap(`exam-${item.id}`, \"Exam Answer (write this in your exam)\", examAnswerBlock(item), false, \"\ud83d\udcdd\");\n    html += sectionWrap(`simple-${item.id}`, \"Explain Simply\", explainSimpleBlock(item), false, \"\ud83d\udcac\");\n\n    if(mode==='practice'){\n      html += `<div class=\"btnrow\" style=\"margin-top:16px; border-top:1px solid var(--line); padding-top:14px;\">\n        <button class=\"btn know ${st==='know'?'primary':''}\" onclick=\"markProgress(${item.id},'know')\">\u2713 Mark as Mastered</button>\n        <button class=\"btn review ${st==='review'?'primary':''}\" onclick=\"markProgress(${item.id},'review')\">\u21bb Needs Review</button>\n        <span style=\"flex:1\"></span>\n        <button class=\"btn ghost\" onclick=\"nextQuestion(${item.id})\">Next Question \u2192</button>\n      </div>`;\n    }\n  } else {\n    html += `<div style=\"color:var(--ink-soft); font-size:12.5px; margin-top:6px;\">Select an option and submit to unlock the explanation, theory, diagram and exam tips.</div>`;\n  }\n  html += `</div>`;\n  return html;\n}\n\nfunction markProgress(id, val){ state.progress[id] = val; checkBadges(); render(); }\nfunction nextQuestion(id){\n  const idx = DATA.findIndex(d=>d.id===id);\n  const next = DATA[(idx+1)%DATA.length];\n  state.currentId = next.id;\n  render();\n}\n\n/* ============================= SIDEBAR ============================= */\nfunction progressStats(dayFilter){\n  const list = dayFilter? DATA.filter(d=>d.day===dayFilter) : DATA;\n  const attempted = list.filter(d=>state.progress[d.id]).length;\n  const correct = list.filter(d=>state.progress[d.id]==='know').length;\n  const total = list.length;\n  const acc = attempted? Math.round(correct/attempted*100) : 0;\n  return {attempted,correct,total,acc};\n}\nfunction renderSidebar(){\n  const overall = progressStats();\n  const d1 = progressStats(1), d2 = progressStats(2), d3 = progressStats(3), d4 = progressStats(4), d5 = progressStats(5), d6 = progressStats(6);\n  const modes = [\n    {k:\"study\", ic:\"\u25c6\", label:\"Study Mode\"},\n    {k:\"practice\", ic:\"\ud83c\udfae\", label:\"Practice Mode\"},\n    {k:\"revision\", ic:\"\u26a1\", label:\"Quick Revision\"},\n    {k:\"visualize\", ic:\"\u25a4\", label:\"Visualize\"},\n    {k:\"exam\", ic:\"\u23f1\", label:\"Exam Mode\"},\n    {k:\"mistakes\", ic:\"\u26a0\", label:\"My Mistakes\"},\n  ];\n  const xppct = xpPct();\n  let html = `\n  <div class=\"brand\">\n    <div class=\"mark\">OCI</div>\n    <div><div class=\"name\">Foundations Visualizer</div><div class=\"sub\">Day 1\u20136 \u00b7 ${DATA.length} Questions</div></div>\n    <button class=\"theme-toggle\" onclick=\"toggleTheme()\" title=\"Toggle theme\">${state.theme==='light'?'\u263e':'\u2600'}</button>\n  </div>\n  <div class=\"hud\" style=\"--xppct:${xppct}\">\n    <div class=\"hud-top\">\n      <div class=\"level-badge\"><span>${state.level}</span></div>\n      <div>\n        <div class=\"hud-title\">Level ${state.level} Cloud Learner</div>\n        <div class=\"hud-sub\">${state.xp} XP total</div>\n      </div>\n    </div>\n    <div class=\"xpbar\"><div style=\"width:${xppct}%\"></div></div>\n    <div class=\"hud-row\">\n      <span>${xpIntoLevel()} / 150 XP to next level</span>\n      <span class=\"streak ${state.streak>=3?'hot':''}\">\ud83d\udd25 ${state.streak}</span>\n    </div>\n  </div>\n  <div class=\"ring-wrap\">\n    <div class=\"ring\" style=\"--pct:${overall.acc}\"><b>${overall.acc}%</b></div>\n    <div class=\"ring-legend\">Overall Accuracy<br><b>${overall.correct}</b> mastered \u00b7 <b>${overall.attempted}</b>/${overall.total} attempted</div>\n  </div>\n  <div class=\"badges-row\">\n    ${BADGES.map(b=>`<div class=\"badge-chip ${state.badges.has(b.id)?'unlocked':''}\" title=\"${b.name}: ${b.desc}\">${b.icon}</div>`).join(\"\")}\n  </div>\n  <div class=\"nav-label\">Modes</div>\n  <div class=\"nav-group\">\n    ${modes.map(m=>`<button class=\"nav-btn ${state.mode===m.k?'active':''}\" onclick=\"setMode('${m.k}')\"><span class=\"ic\">${m.ic}</span>${m.label}</button>`).join(\"\")}\n  </div>\n  <div class=\"nav-label\">Progress</div>\n  <div class=\"progress-mini\" style=\"margin:0 6px 6px; font-size:12px; color:var(--ink-soft);\">\n    <div class=\"hud-row\" style=\"margin-bottom:4px;\"><span>Day 1</span><b style=\"color:var(--ink)\">${d1.correct}/${d1.total} \u00b7 ${d1.acc}%</b></div>\n    <div class=\"hud-row\"><span>Day 2</span><b style=\"color:var(--ink)\">${d2.correct}/${d2.total} \u00b7 ${d2.acc}%</b></div>\n    <div class=\"hud-row\"><span>Day 3</span><b style=\"color:var(--ink)\">${d3.correct}/${d3.total} \u00b7 ${d3.acc}%</b></div>\n    <div class=\"hud-row\"><span>Day 4</span><b style=\"color:var(--ink)\">${d4.correct}/${d4.total} \u00b7 ${d4.acc}%</b></div>\n    <div class=\"hud-row\"><span>Day 5</span><b style=\"color:var(--ink)\">${d5.correct}/${d5.total} \u00b7 ${d5.acc}%</b></div>\n    <div class=\"hud-row\"><span>Day 6</span><b style=\"color:var(--ink)\">${d6.correct}/${d6.total} \u00b7 ${d6.acc}%</b></div>\n  </div>\n  <div class=\"nav-label\">Navigator</div>\n  <div class=\"qnav\">\n    ${DATA.map(d=>{\n      const st = state.progress[d.id];\n      const cls = st==='know'?'know':st==='review'?'review':'';\n      const cur = (state.mode!=='exam' && state.mode!=='revision' && state.mode!=='mistakes' && d.id===state.currentId)?'current':'';\n      return `<div class=\"qdot ${cls} ${cur}\" title=\"Q${d.id}: ${d.topic}\" onclick=\"jumpTo(${d.id})\">${d.id}</div>`;\n    }).join(\"\")}\n  </div>\n  `;\n  document.getElementById(\"sidebar\").innerHTML = html;\n}\nfunction toggleTheme(){ state.theme = state.theme==='light'?'dark':'light'; document.body.setAttribute('data-theme', state.theme); renderSidebar(); }\nfunction setMode(m){ state.mode = m; render(); }\nfunction jumpTo(id){ state.currentId = id; if(state.mode==='exam' || state.mode==='revision' || state.mode==='mistakes') state.mode='study'; render(); }\n\n/* ============================= TOPBAR ============================= */\nfunction renderTopbar(title, desc, showSearch, icon){\n  let html = `<div class=\"topbar\"><div><h2>${icon?icon+' ':''}${title}</h2><div class=\"desc\">${desc}</div></div>`;\n  if(showSearch){\n    html += `<div class=\"search-wrap\">\n      <input class=\"search-input\" placeholder=\"Search question, topic, keyword...\" value=\"${state.search}\" oninput=\"onSearch(this.value)\">\n      <button class=\"filter-chip ${state.dayFilter==='all'?'on':''}\" onclick=\"setDayFilter('all')\">All Days</button>\n      <button class=\"filter-chip ${state.dayFilter===1?'on':''}\" onclick=\"setDayFilter(1)\">Day 1</button>\n      <button class=\"filter-chip ${state.dayFilter===2?'on':''}\" onclick=\"setDayFilter(2)\">Day 2</button>\n      <button class=\"filter-chip ${state.dayFilter===3?'on':''}\" onclick=\"setDayFilter(3)\">Day 3</button>\n      <button class=\"filter-chip ${state.dayFilter===4?'on':''}\" onclick=\"setDayFilter(4)\">Day 4</button>\n      <button class=\"filter-chip ${state.dayFilter===5?'on':''}\" onclick=\"setDayFilter(5)\">Day 5</button>\n      <button class=\"filter-chip ${state.dayFilter===6?'on':''}\" onclick=\"setDayFilter(6)\">Day 6</button>\n      <button class=\"filter-chip ${state.statusFilter==='know'?'on':''}\" onclick=\"setStatusFilter('know')\">Mastered</button>\n      <button class=\"filter-chip ${state.statusFilter==='review'?'on':''}\" onclick=\"setStatusFilter('review')\">Weak Areas</button>\n      <button class=\"filter-chip ${state.statusFilter==='none'?'on':''}\" onclick=\"setStatusFilter('none')\">Not Attempted</button>\n    </div>`;\n  }\n  html += `</div>`;\n  return html;\n}\nfunction onSearch(v){ state.search=v; render(); }\nfunction setDayFilter(v){ state.dayFilter = state.dayFilter===v? 'all': v; render(); }\nfunction setStatusFilter(v){ state.statusFilter = state.statusFilter===v? 'all': v; render(); }\n\nfunction filteredList(){\n  return DATA.filter(d=>{\n    if(state.dayFilter!=='all' && d.day!==state.dayFilter) return false;\n    if(state.statusFilter!=='all'){\n      const st = state.progress[d.id];\n      if(state.statusFilter==='none' && st) return false;\n      if(state.statusFilter!=='none' && st!==state.statusFilter) return false;\n    }\n    if(state.search.trim()){\n      const q = state.search.toLowerCase();\n      const hay = (d.question+\" \"+d.topic+\" \"+d.quick).toLowerCase();\n      if(!hay.includes(q)) return false;\n    }\n    return true;\n  });\n}\n\n/* ============================= MODE RENDERERS ============================= */\nfunction renderStudyOrPractice(mode){\n  const list = filteredList();\n  let item = byId(state.currentId);\n  if(!list.find(d=>d.id===item.id)){ item = list[0]; if(item) state.currentId = item.id; }\n  let html = renderTopbar(\n    mode==='study' ? \"Study Mode\" : \"Practice Mode\",\n    mode==='study' ? \"Browse every question with full theory, diagrams, real-life examples and exam tips shown immediately.\" : \"Answer the Quick Check MCQ, then unlock the full breakdown \u2014 earn XP and build your streak.\",\n    true, mode==='study'?'\u25c6':'\ud83c\udfae'\n  );\n  if(!item){ html += `<div class=\"empty\"><div class=\"big\">\ud83d\udd0d</div>No questions match your filters.</div>`; }\n  else {\n    html += renderQuestionCard(item, mode);\n    const idx = DATA.findIndex(d=>d.id===item.id);\n    const prev = DATA[(idx-1+DATA.length)%DATA.length];\n    const next = DATA[(idx+1)%DATA.length];\n    html += `<div class=\"btnrow\"><button class=\"btn ghost\" onclick=\"jumpTo(${prev.id})\">\u2190 Q${prev.id}</button><span style=\"flex:1\"></span><button class=\"btn ghost\" onclick=\"jumpTo(${next.id})\">Q${next.id} \u2192</button></div>`;\n  }\n  document.getElementById(\"main\").innerHTML = html;\n}\n\nfunction renderRevision(){\n  const list = filteredList();\n  let html = renderTopbar(\"Quick Revision\", \"Fast pass through every concept \u2014 1-line explanation, quick answer, memory trick and exam trap.\", true, \"\u26a1\");\n  if(!list.length){ html += `<div class=\"empty\"><div class=\"big\">\ud83d\udd0d</div>No questions match your filters.</div>`; }\n  list.forEach(item=>{\n    html += `<div class=\"rev-card\">\n      <div class=\"eyebrow\"><span class=\"pill day${item.day}\">Day ${item.day}</span><span class=\"pill\">${item.topic}</span><span class=\"pill mono\">Q${item.id}</span></div>\n      <div class=\"rev-flow\">\n        <b>${item.topic}</b><br>\n        \u2193 ${item.explanation.split('.')[0]}.<br>\n        \u2193 <b>Quick Answer:</b> ${item.quick}<br>\n        \u2193 <b>Memory Trick:</b> ${item.remember.join(\" \u00b7 \")}<br>\n        \u2193 <b>Exam Trap:</b> ${item.trap}\n      </div>\n      <button class=\"btn ghost\" onclick=\"jumpTo(${item.id}); setMode('study')\">Open Full Question \u2192</button>\n    </div>`;\n  });\n  document.getElementById(\"main\").innerHTML = html;\n}\n\nfunction renderVisualize(){\n  const item = byId(state.currentId) || DATA[0];\n  let html = renderTopbar(\"Visualize\", \"Pick any question from the Navigator to see its concept diagram in focus.\", false, \"\u25a4\");\n  html += `<div class=\"card\">\n    <div class=\"eyebrow\"><span class=\"pill day${item.day}\">Day ${item.day}</span><span class=\"pill\">${item.topic}</span><span class=\"pill mono\">Q${item.id}</span></div>\n    <div class=\"q-text\">${item.question}</div>\n    ${renderDiagram(item.diagram)}\n    <div class=\"btnrow\">\n      <button class=\"btn ${state.revealed['viz-simple-'+item.id]?'primary':''}\" onclick=\"toggleSimple(${item.id})\">\ud83d\udcac Explain Simply</button>\n      <button class=\"btn ${state.revealed['viz-real-'+item.id]?'primary':''}\" onclick=\"toggleReal(${item.id})\">\ud83c\udf0d Real-Life Example</button>\n    </div>\n    ${state.revealed['viz-simple-'+item.id] ? explainSimpleBlock(item) : \"\"}\n    ${state.revealed['viz-real-'+item.id] ? realWorldBlock(item) : \"\"}\n  </div>`;\n  document.getElementById(\"main\").innerHTML = html;\n}\nfunction toggleSimple(id){ state.revealed['viz-simple-'+id] = !state.revealed['viz-simple-'+id]; render(); }\nfunction toggleReal(id){ state.revealed['viz-real-'+id] = !state.revealed['viz-real-'+id]; render(); }\n\n/* ============================= EXAM MODE (auto-graded MCQ) ============================= */\nfunction startExam(){\n  state.examQueue = shuffle(DATA.map(d=>d.id));\n  state.examIndex = 0;\n  state.examAnswers = {};\n  state.examStarted = true;\n  state.examFinished = false;\n  render();\n}\nfunction examSelect(id, idx){\n  if(state.examAnswers[id] !== undefined) return;\n  state._examTemp = state._examTemp || {};\n  state._examTemp[id] = idx;\n  render();\n}\nfunction examSubmitCurrent(){\n  const id = state.examQueue[state.examIndex];\n  const idx = (state._examTemp||{})[id];\n  if(idx===undefined) return;\n  const item = byId(id);\n  const opts = getShuffledMCQ(item);\n  state.examAnswers[id] = { selected:idx, correct: opts[idx].correct };\n  if(state.examIndex < state.examQueue.length-1){ state.examIndex++; }\n  else { state.examFinished = true; DATA.forEach(d=>{ if(state.examAnswers[d.id]) handleAnswerResult(d, state.examAnswers[d.id].correct); }); }\n  render();\n}\nfunction examReset(){ state.examStarted = false; state.examFinished = false; render(); }\n\nfunction renderExam(){\n  let html = \"\";\n  if(!state.examStarted){\n    html = renderTopbar(\"Exam Mode\", `Randomized 4-option run through all ${DATA.length} questions. No hints while answering \u2014 full score and topic breakdown at the end.`, false, \"\u23f1\");\n    html += `<div class=\"card\" style=\"text-align:center; padding:44px 24px;\">\n      <h3 style=\"margin-bottom:8px;\">\ud83c\udfc1 Ready for a full run?</h3>\n      <p style=\"color:var(--ink-soft); max-width:460px; margin:0 auto 18px;\">All ${DATA.length} questions from Day 1\u20136, each as a 4-option Quick Check, in random order with randomized answer positions. No explanations shown until the end \u2014 score, accuracy and topic-wise performance are calculated automatically.</p>\n      <button class=\"btn primary\" onclick=\"startExam()\">Start Exam</button>\n    </div>`;\n    document.getElementById(\"main\").innerHTML = html;\n    return;\n  }\n  if(state.examFinished){\n    const total = state.examQueue.length;\n    const correct = Object.values(state.examAnswers).filter(a=>a.correct).length;\n    const pct = Math.round(correct/total*100);\n    const topics = {};\n    state.examQueue.forEach(id=>{\n      const it = byId(id);\n      if(!topics[it.topic]) topics[it.topic] = {c:0,t:0};\n      topics[it.topic].t++;\n      if(state.examAnswers[id] && state.examAnswers[id].correct) topics[it.topic].c++;\n    });\n    html = renderTopbar(\"Exam Results\", \"Auto-graded performance summary for this run.\", false, \"\ud83c\udfc1\");\n    html += `<div class=\"card\">\n      <div class=\"result-grid\">\n        <div class=\"result-box\"><div class=\"num\">${pct}%</div><div class=\"lbl\">Score</div></div>\n        <div class=\"result-box\"><div class=\"num\" style=\"color:var(--green)\">${correct}</div><div class=\"lbl\">Correct</div></div>\n        <div class=\"result-box\"><div class=\"num\" style=\"color:var(--rust)\">${total-correct}</div><div class=\"lbl\">Incorrect</div></div>\n      </div>\n      <h4 style=\"margin-top:18px;\">Topic-wise Performance</h4>\n      ${Object.entries(topics).map(([topic,v])=>{\n        const p = Math.round(v.c/v.t*100);\n        return `<div class=\"topic-row\"><span>${topic}</span><div style=\"display:flex; align-items:center; gap:10px;\"><div class=\"tbar\"><div style=\"width:${p}%\"></div></div><span class=\"mono\" style=\"width:60px; text-align:right;\">${v.c}/${v.t}</span></div></div>`;\n      }).join(\"\")}\n      <div class=\"btnrow\" style=\"margin-top:20px;\">\n        <button class=\"btn primary\" onclick=\"startExam()\">Retake Exam (New Order)</button>\n        <button class=\"btn ghost\" onclick=\"examReset()\">Exit Exam Mode</button>\n      </div>\n    </div>`;\n    html += `<h3 style=\"margin-top:20px;\">Review Incorrect Questions</h3>`;\n    const wrong = state.examQueue.filter(id=>state.examAnswers[id] && !state.examAnswers[id].correct);\n    if(!wrong.length){ html += `<div class=\"empty\">\ud83c\udf89 No incorrect answers \u2014 perfect run!</div>`; }\n    wrong.forEach(id=>{\n      const it = byId(id);\n      html += `<div class=\"card\">\n        <div class=\"eyebrow\"><span class=\"pill day${it.day}\">Day ${it.day}</span><span class=\"pill\">${it.topic}</span></div>\n        <div class=\"q-text\">${it.question}</div>\n        <div class=\"callout\" style=\"border-left:3px solid var(--slate); background:var(--slate-soft);\"><span class=\"lbl\">Correct Answer</span>${it.answer}</div>\n        ${realWorldBlock(it)}\n        ${rememberBlock(it)}\n        ${trapBlock(it)}\n      </div>`;\n    });\n    document.getElementById(\"main\").innerHTML = html;\n    return;\n  }\n\n  const id = state.examQueue[state.examIndex];\n  const item = byId(id);\n  const opts = getShuffledMCQ(item);\n  const sel = (state._examTemp||{})[id];\n  const letters = [\"A\",\"B\",\"C\",\"D\"];\n  const pct = Math.round((state.examIndex)/state.examQueue.length*100);\n  html = `<div class=\"exam-progress\"><span>Question ${state.examIndex+1} of ${state.examQueue.length}</span><span>${pct}% complete</span></div>\n  <div class=\"exam-bar\"><div style=\"width:${pct}%\"></div></div>`;\n  html += `<div class=\"card\">\n    <div class=\"eyebrow\"><span class=\"pill day${item.day}\">Day ${item.day}</span><span class=\"pill\">${item.topic}</span></div>\n    <div class=\"q-text\">${item.question}</div>\n    <div class=\"callout\" style=\"border-left:3px solid var(--violet); background:var(--violet-soft);\"><span class=\"lbl\">\ud83c\udfae Quick Check</span>${item.mcq.question}</div>\n    <div class=\"mcq-list\">\n      ${opts.map((o,i)=>`<button class=\"mcq-opt ${sel===i?'selected':''}\" onclick=\"examSelect(${id},${i})\">\n        <span class=\"optkey\">${letters[i]}</span><span>${o.text}</span>\n      </button>`).join(\"\")}\n    </div>\n    <div class=\"btnrow\"><button class=\"btn primary\" ${sel===undefined?'disabled':''} onclick=\"examSubmitCurrent()\">${state.examIndex<state.examQueue.length-1?'Submit & Next \u2192':'Submit & Finish'}</button></div>\n  </div>`;\n  document.getElementById(\"main\").innerHTML = html;\n}\n\n/* ============================= MISTAKES ============================= */\nfunction renderMistakes(){\n  const mistakes = DATA.filter(d=>state.progress[d.id]==='review');\n  let html = renderTopbar(\"My Mistakes\", \"Every question you marked or answered incorrectly \u2014 practice these until they turn green.\", false, \"\u26a0\");\n  if(!mistakes.length){ html += `<div class=\"empty\"><div class=\"big\">\u2713</div>No mistakes logged yet. Answer questions in Practice or Exam Mode to build this list.</div>`; }\n  mistakes.forEach(item=>{\n    html += `<div class=\"card\">\n      <div class=\"eyebrow\"><span class=\"pill day${item.day}\">Day ${item.day}</span><span class=\"pill\">${item.topic}</span><span class=\"pill mono\">Q${item.id}</span></div>\n      <div class=\"q-text\">${item.question}</div>\n      <div class=\"callout\" style=\"border-left:3px solid var(--slate); background:var(--slate-soft);\"><span class=\"lbl\">Correct Answer</span>${item.answer}</div>\n      ${renderDiagram(item.diagram)}\n      ${realWorldBlock(item)}\n      ${rememberBlock(item)}\n      ${trapBlock(item)}\n      <div class=\"btnrow\"><button class=\"btn primary\" onclick=\"practiceAgain(${item.id})\">Practice Again</button></div>\n    </div>`;\n  });\n  document.getElementById(\"main\").innerHTML = html;\n}\nfunction practiceAgain(id){\n  state.currentId = id;\n  state.revealed[id] = false;\n  state.mcqAnswered[id] = false;\n  state.mcqSelected[id] = undefined;\n  delete state.mcqCache[id];\n  state.mode = 'practice';\n  render();\n}\n\n/* ============================= MAIN RENDER ============================= */\nfunction render(){\n  renderSidebar();\n  if(state.mode==='study') renderStudyOrPractice('study');\n  else if(state.mode==='practice') renderStudyOrPractice('practice');\n  else if(state.mode==='revision') renderRevision();\n  else if(state.mode==='visualize') renderVisualize();\n  else if(state.mode==='exam') renderExam();\n  else if(state.mode==='mistakes') renderMistakes();\n  renderToastOnly();\n}\nrender();\n"};
